// Orthographe : la phrase, les formes proposées, l'index de la bonne, la règle
B.ortho=[
  {id:'o01',niv:2,phrase:"Les lettres que j'ai ___ hier sont arrivées.",choix:["écrit","écrites","écrits"],bonne:1,regle:"Avec avoir, le participe s'accorde avec le COD placé avant : « que », mis pour « les lettres »."},
  {id:'o02',niv:3,phrase:"Elles se sont ___ les mains.",choix:["lavé","lavées","lavés"],bonne:0,regle:"Le COD « les mains » est placé après le verbe : pas d'accord."},
  {id:'o03',niv:2,phrase:"Les filles se sont ___ dans le parc.",choix:["promené","promenées","promenés"],bonne:1,regle:"Verbe pronominal sans autre COD : accord avec le sujet « les filles »."},
  {id:'o04',niv:1,phrase:"Il ___ beaucoup de travail cette semaine.",choix:["a","à"],bonne:0,regle:"Verbe avoir : on peut dire « il avait »."},
  {id:'o05',niv:1,phrase:"Je pars ___ Lyon demain matin.",choix:["a","à"],bonne:1,regle:"Préposition : on ne peut pas dire « avait »."},
  {id:'o06',niv:1,phrase:"___ en forgeant qu'on devient forgeron.",choix:["C'est","S'est","Ses","Ces"],bonne:0,regle:"« Cela est » : c'est."},
  {id:'o07',niv:1,phrase:"Il ___ trompé de route.",choix:["s'est","c'est","ses"],bonne:0,regle:"Verbe pronominal se tromper : il s'est trompé."},
  {id:'o08',niv:3,phrase:"___ que soient tes raisons, préviens-nous.",choix:["Quelles","Quelle","Quel","Quels"],bonne:0,regle:"« Quel que » s'accorde avec le sujet : les raisons, féminin pluriel."},
  {id:'o09',niv:1,phrase:"Je ___ ai parlé hier soir.",choix:["leur","leurs"],bonne:0,regle:"Pronom devant un verbe : « leur » est toujours invariable."},
  {id:'o10',niv:1,phrase:"Ils ont rangé ___ affaires.",choix:["leur","leurs"],bonne:1,regle:"Déterminant devant un nom pluriel : leurs affaires."},
  {id:'o11',niv:1,phrase:"Il faut ___ ce dossier avant midi.",choix:["terminer","terminé","terminez"],bonne:0,regle:"Après « il faut », on met l'infinitif. Astuce : remplace par « finir »."},
  {id:'o12',niv:1,phrase:"Le dossier est ___ depuis midi.",choix:["terminé","terminer"],bonne:0,regle:"Astuce : remplace par « fini » ou « finir ». On dit « il est fini »."},
  {id:'o13',niv:2,phrase:"Quoi qu'il ___, je viendrai.",choix:["arrive","arrives","arrivera"],bonne:0,regle:"« Quoi que » est suivi du subjonctif : quoi qu'il arrive."},
  {id:'o14',niv:1,phrase:"___ vas-tu ce week-end ?",choix:["Où","Ou"],bonne:0,regle:"Le lieu prend un accent : où. « Ou » sans accent signifie « ou bien »."},
  {id:'o15',niv:3,vu:'2026-11-02',phrase:"Elles sont ___ contentes de leur résultat.",choix:["tout","toutes"],bonne:1,regle:"« Tout » adverbe (ici : tout à fait) s'accorde devant un adjectif féminin qui commence par une consonne ou un h aspiré : toutes contentes, toutes honteuses."},
  {id:'o16',niv:3,phrase:"Nous avons ___ deux heures sous la pluie.",choix:["attendu","attendus"],bonne:0,regle:"« Deux heures » est un complément de durée, pas un COD : pas d'accord."},
  {id:'o17',niv:3,phrase:"La maison qu'ils ont ___ construire est superbe.",choix:["fait","faite"],bonne:0,regle:"« Fait » suivi d'un infinitif reste toujours invariable."},
  {id:'o18',niv:2,phrase:"Les fleurs que tu m'as ___ sont magnifiques.",choix:["offert","offertes","offerts"],bonne:1,regle:"COD « que » (les fleurs) placé avant avoir : accord au féminin pluriel."},
  {id:'o19',niv:2,phrase:"Si j'___ su, je serais venu.",choix:["avais","aurais"],bonne:0,regle:"Après « si » de condition, jamais de conditionnel : si j'avais su."},
  {id:'o20',niv:1,vu:'2026-11-02',phrase:"C'est décidé : demain, je ___ à Lyon toute la journée.",choix:["serai","serais"],bonne:0,regle:"Action certaine dans le futur : futur simple (je serai). Le conditionnel exprime une hypothèse ou une condition : je serais à Lyon si le train partait."},
  {id:'o21',niv:1,phrase:"Ils ___ partis très tôt ce matin.",choix:["sont","son"],bonne:0,regle:"Verbe être : on peut dire « ils étaient partis »."},
  {id:'o22',niv:3,phrase:"J'ai payé quatre-___ euros.",choix:["vingts","vingt"],bonne:0,regle:"« Vingt » prend un s quand il est multiplié et termine le nombre : quatre-vingts."},
  {id:'o23',niv:2,phrase:"Il a mangé ___ pommes en rentrant.",choix:["quelques","quelque"],bonne:0,regle:"Devant un nom pluriel, « quelques » s'accorde."},
  {id:'o24',niv:3,phrase:"Ci-___ les documents demandés.",choix:["joint","jointes","joints"],bonne:0,regle:"En tête de phrase, devant le nom, « ci-joint » reste invariable."},
  {id:'o25',niv:2,phrase:"Ce sont les règles ___ je t'ai parlé.",choix:["dont","que"],bonne:0,regle:"On parle DE quelque chose : le relatif est « dont »."},
  {id:'o26',niv:3,phrase:"Les efforts qu'il a ___ ont payé.",choix:["fallu","fallus"],bonne:0,regle:"Le participe de « falloir » est toujours invariable."},
  {id:'o27',niv:3,phrase:"Ils se sont ___ des cadeaux.",choix:["offert","offerts"],bonne:0,regle:"Le COD « des cadeaux » est placé après le verbe : pas d'accord, même avec être."},
  {id:'o28',niv:3,phrase:"Elle s'est ___ compte de son erreur.",choix:["rendu","rendue"],bonne:0,regle:"« Se rendre compte » : « compte » est le COD, placé après. Le participe reste invariable."},
  {id:'o29',niv:2,phrase:"Ils ont ___ leurs devoirs.",choix:["fini","finit","finis"],bonne:0,regle:"Avec avoir et un COD placé après, le participe ne s'accorde pas. Astuce : « ils ont pris », pas « ils ont prit »."},
  {id:'o30',niv:2,phrase:"Il faut que tu ___ à l'heure.",choix:["sois","soit","soi"],bonne:0,regle:"Subjonctif d'être : que je sois, que tu sois, qu'il soit. « Soi » est un pronom."},
  {id:'o31',niv:1,phrase:"C'est ___ que je pensais.",choix:["ce","se"],bonne:0,regle:"« Ce » désigne une chose (cela). « Se » accompagne un verbe pronominal : il se lave."},
  {id:'o32',niv:2,phrase:"Les enfants, ___ par le bruit, se sont réveillés.",choix:["dérangé","dérangés"],bonne:1,regle:"Participe employé comme adjectif : il s'accorde avec « les enfants »."},
  {id:'o33',niv:1,phrase:"Je vous ___ de bonnes vacances.",choix:["souhaite","souhaites"],bonne:0,regle:"Le sujet est « je » : je souhaite. « Vous » est ici complément."},
  {id:'o34',niv:2,phrase:"Tu es ___ arriver à huit heures.",choix:["sensé","censé"],bonne:1,regle:"« Censé » veut dire « supposé ». « Sensé » veut dire « qui a du bon sens » : une remarque sensée."},
  {id:'o35',niv:1,phrase:"Je suis ___ à partir.",choix:["près","prêt"],bonne:1,regle:"« Prêt à » : préparé à. « Près de » : à côté de."},
  {id:'o36',niv:1,phrase:"Il ___ pleuvoir cet après-midi.",choix:["peu","peut","peux"],bonne:1,regle:"Verbe pouvoir : il peut. Astuce : on peut dire « il pouvait »."},
  {id:'o37',niv:1,phrase:"Il a ___ d'amis dans cette ville.",choix:["peu","peut"],bonne:0,regle:"« Peu » signifie « pas beaucoup ». On ne peut pas dire « il a pouvait d'amis »."},
  {id:'o38',niv:2,phrase:"___ à moi, je préfère rester.",choix:["Quand","Quant","Qu'en"],bonne:1,regle:"« Quant à » signifie « en ce qui concerne ». « Quand » marque le temps."},
  {id:'o39',niv:2,phrase:"Je ne sais pas ___ penser.",choix:["qu'en","quand","quant"],bonne:0,regle:"« Qu'en » = « que » + « en » : que penser de cela."},
  {id:'o40',niv:2,phrase:"Pour réussir, il faudra travailler ___.",choix:["d'avantage","davantage"],bonne:1,regle:"« Davantage », en un mot, signifie « plus ». « Un avantage » est un bénéfice."},
  {id:'o41',niv:3,phrase:"Elles se sont ___ toute la soirée.",choix:["parlées","parlé","parlés"],bonne:1,regle:"On parle à quelqu'un : « se » est complément indirect. Pas d'accord : elles se sont parlé."},
  {id:'o42',niv:3,phrase:"Elles se sont ___ de leur erreur.",choix:["aperçu","aperçues"],bonne:1,regle:"« S'apercevoir de » ne s'emploie qu'à la forme pronominale : le participe s'accorde avec le sujet."},
  {id:'o43',niv:2,phrase:"Il porte des chaussures ___.",choix:["marron","marrons"],bonne:0,regle:"Un nom employé comme couleur reste invariable : des chaussures marron, des yeux noisette."},
  {id:'o44',niv:3,phrase:"Elle a acheté des robes ___.",choix:["rose","roses"],bonne:1,regle:"« Rose » fait exception : avec mauve, fauve, pourpre et écarlate, il s'accorde."},
  {id:'o45',niv:3,phrase:"Il a mis ses chemises bleu ___.",choix:["claires","clair"],bonne:1,regle:"Une couleur composée de deux mots reste invariable : des chemises bleu clair."},
  {id:'o46',niv:2,phrase:"Bien qu'il ___ tard, je reste encore un peu.",choix:["est","soit"],bonne:1,regle:"« Bien que » est toujours suivi du subjonctif : bien qu'il soit tard."},
  {id:'o47',niv:2,phrase:"Je te rappellerai après que tu ___ rentré.",choix:["seras","sois"],bonne:0,regle:"« Après que » se construit avec l'indicatif, car l'action est réalisée. Le subjonctif, très répandu, est une faute."},
  {id:'o48',niv:2,phrase:"Ces livres, je les ai tous ___.",choix:["lu","lus"],bonne:1,regle:"Le COD « les » (ces livres) est placé avant avoir : accord au masculin pluriel."},
  {id:'o49',niv:2,phrase:"Combien de pommes as-tu ___ ?",choix:["mangé","mangées"],bonne:1,regle:"« Combien de pommes » est le COD, placé avant avoir : accord au féminin pluriel."},
  {id:'o50',niv:3,phrase:"Elle est ___ heureuse de sa journée.",choix:["tout","toute"],bonne:0,regle:"« Tout » adverbe reste invariable devant un adjectif féminin qui commence par une voyelle ou un h muet."},
  {id:'o51',niv:1,vu:'2026-11-02',phrase:"Montre-moi ___ livres-là, sur l'étagère du haut.",choix:["ses","ces"],bonne:1,regle:"« Ces » montre : ces livres-là. « Ses » indique qu'ils appartiennent à quelqu'un d'autre : ses livres à lui."},
  {id:'o52',niv:3,phrase:"Il y avait deux ___ cinquante invités.",choix:["cents","cent"],bonne:1,regle:"« Cent » ne prend pas de s quand il est suivi d'un autre nombre : deux cent cinquante, mais deux cents."},
  {id:'o53',niv:3,phrase:"Il a parcouru trois ___ kilomètres à vélo.",choix:["mille","milles"],bonne:0,regle:"« Mille » est toujours invariable."},
  {id:'o54',niv:1,phrase:"La réunion de ce soir a été ___.",choix:["annulé","annulée","annuler"],bonne:1,regle:"Avec être, le participe s'accorde avec le sujet : la réunion, féminin singulier."},
  {id:'o55',niv:1,phrase:"Vous devez ___ ce formulaire avant lundi.",choix:["rempli","remplir","remplis"],bonne:1,regle:"Après un verbe comme « devoir », on met l'infinitif. Astuce : remplace par « prendre »."},
  {id:'o56',niv:3,phrase:"___ grands que soient leurs efforts, ils n'y arriveront pas seuls.",choix:["Quelques","Quelque","Quels que"],bonne:1,regle:"Devant un adjectif, « quelque » signifie « si » : il est adverbe, donc invariable."},
  {id:'o57',niv:3,phrase:"Les sommes ___ seront remboursées.",choix:["dûes","dues","dûs"],bonne:1,regle:"« Dû » ne garde son accent qu'au masculin singulier : due, dus, dues."},
  {id:'o58',niv:1,phrase:"Il a ___ partir plus tôt que prévu.",choix:["du","dû"],bonne:1,regle:"Participe passé de devoir : dû, avec un accent qui le distingue de l'article « du »."},
  {id:'o59',niv:3,phrase:"Elle s'est ___ de partir sans prévenir.",choix:["permise","permis"],bonne:1,regle:"On permet quelque chose à quelqu'un : « se » est complément indirect, pas d'accord."},
  {id:'o60',niv:3,phrase:"Elles ont ___ toute la nuit.",choix:["dormies","dormi"],bonne:1,regle:"« Dormir » n'a jamais de COD : avec avoir, son participe ne s'accorde pas."},
  {id:'o61',niv:2,phrase:"Voici la lettre ___ j'attendais.",choix:["dont","que"],bonne:1,regle:"On attend quelque chose, sans préposition : le relatif est « que ». On dit « dont » pour « parler de »."},
  {id:'o62',niv:1,src:"Dictionnaire de l'Académie française, 9e édition, articles « ça » et « sa »",vu:'2026-10-31',phrase:"Il a oublié ___ veste au bureau.",choix:["sa","ça"],bonne:0,regle:"« Sa » est un déterminant : sa veste, la sienne. « Ça » est un pronom qui remplace « cela » : on ne dirait pas « cela veste »."},
  {id:'o63',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (impératif)",vu:'2026-10-31',phrase:"___ chercher du pain, s'il te plaît.",choix:["Va","Vas"],bonne:0,regle:"À l'impératif, « aller » et les verbes en -er ne prennent pas de s à la 2e personne du singulier : va, mange, parle. Le s revient seulement devant « en » ou « y » : vas-y, manges-en."},
  {id:'o64',niv:1,src:"Bescherelle, L'orthographe pour tous (homophones et/est)",vu:'2026-11-02',phrase:"Le ciel ___ couvert depuis ce matin.",choix:["est","et"],bonne:0,regle:"Verbe être : on peut dire « le ciel était couvert ». « Et » relie deux mots : le ciel et la mer."},
  {id:'o65',niv:1,src:"Bescherelle, L'orthographe pour tous (homophones on/ont)",vu:'2026-11-02',phrase:"Ils ___ oublié leurs clés dans la voiture.",choix:["on","ont"],bonne:1,regle:"Verbe avoir : on peut dire « ils avaient oublié ». « On » est un pronom sujet : on oublie."},
  {id:'o66',niv:2,src:"Bescherelle, L'orthographe pour tous (homophones ni/n'y)",vu:'2026-11-02',phrase:"Il ___ a plus de pain à la boulangerie.",choix:["n'y","ni"],bonne:0,regle:"« N'y » = négation + « y » : il y a, il n'y a plus. « Ni » relie deux négations : ni pain ni beurre."},
  {id:'o67',niv:2,src:"Bescherelle, L'orthographe pour tous (homophones s'en/sans/c'en)",vu:'2026-11-02',phrase:"Il ___ est allé sans dire au revoir.",choix:["sans","s'en","c'en"],bonne:1,regle:"S'en aller : il s'en va, il s'en est allé. « Sans » marque l'absence ; « c'en » = « cela en » : c'en est trop."},
  {id:'o68',niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (infinitif après préposition)",vu:'2026-11-02',phrase:"Il est parti sans ___ un mot.",choix:["dit","dis","dire"],bonne:2,regle:"Après une préposition (sans, pour, de), le verbe est à l'infinitif. Astuce : remplace par « prendre »."},
  {id:'o69',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du verbe avec le sujet)",vu:'2026-11-02',phrase:"Où sont les clés que tu ___ prises ce matin ?",choix:["as","a"],bonne:0,regle:"Le sujet de « avoir » est « tu » : tu as. Le participe « prises » s'accorde avec « que » (les clés), placé avant."},
  {id:'o70',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord après « qui »)",vu:'2026-11-02',phrase:"C'est moi qui ___ raison, cette fois.",choix:["a","ai"],bonne:1,regle:"Après « qui », le verbe s'accorde avec le mot que « qui » remplace : moi qui ai, toi qui as, nous qui avons."},
  {id:'o71',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:'2026-11-02',phrase:"Nous nous sommes ___ de bonne heure pour partir.",choix:["levé","levés","lever"],bonne:1,regle:"Se lever, sans autre COD : le participe s'accorde avec le sujet « nous »."},
  {id:'o72',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (« la plupart »)",vu:'2026-11-02',phrase:"La plupart des invités ___ partis avant minuit.",choix:["est","sont"],bonne:1,regle:"Après « la plupart », le verbe se met au pluriel : la plupart des invités sont partis, la plupart pensent."},
  {id:'o73',niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:'2026-11-02',phrase:"Elle s'est ___ les cheveux toute seule.",choix:["coupés","coupée","coupé"],bonne:2,regle:"Le COD « les cheveux » est placé après le verbe : pas d'accord. Comparez : elle s'est coupée (en cuisinant)."},
  {id:'o74',niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes essentiellement pronominaux)",vu:'2026-11-02',phrase:"Ses camarades se sont ___ de lui.",choix:["moqués","moqué"],bonne:0,regle:"« Se moquer » n'existe qu'à la forme pronominale : le participe s'accorde avec le sujet, « ses camarades »."},
  {id:'o75',niv:1,src:"Bescherelle, La conjugaison pour tous (présent)",vu:'2026-11-02',phrase:"Voilà une heure que je t'___ devant la gare.",choix:["attend","attends"],bonne:1,regle:"Avec « je », les verbes en -dre prennent un s : j'attends, je prends. Le t ou le d seul, c'est « il » : il attend."},
  {id:'o76',niv:1,src:"Bescherelle, La conjugaison pour tous (présent)",vu:'2026-11-02',phrase:"Tu ___ très bien que j'ai raison.",choix:["sait","sais"],bonne:1,regle:"Avec « tu », le verbe se termine par s : tu sais, tu fais. « Il sait » prend un t."},
  {id:'o77',niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (adjectif employé comme adverbe)",vu:'2026-11-02',phrase:"Ces roses sentent ___.",choix:["bons","bonnes","bon"],bonne:2,regle:"Après « sentir », « bon » qualifie le verbe, pas les roses : il est adverbe, donc invariable. De même : elles coûtent cher, ils parlent fort."},
  {id:'o78',niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (adjectif employé comme adverbe)",vu:'2026-11-02',phrase:"Elle porte les cheveux coupés ___.",choix:["courts","court"],bonne:1,regle:"« Court » dit comment ils sont coupés : adverbe, donc invariable. Mais : elle a les cheveux courts (adjectif)."},
  {id:'o79',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (infinitif passé)",vu:'2026-11-02',phrase:"Après ___ dîné, ils sont sortis marcher.",choix:["avait","avoir","avaient"],bonne:1,regle:"« Après » suivi d'un verbe demande l'infinitif passé : après avoir dîné, après être parti."},
  {id:'o80',niv:1,src:"Bescherelle, L'orthographe pour tous (homophones ce/se)",vu:'2026-11-02',phrase:"Il ne faut pas ___ fier aux apparences.",choix:["ce","se"],bonne:1,regle:"« Se fier » est un verbe pronominal : se. « Ce » désigne une chose : ce livre, c'est."},
  {id:'o81',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:'2026-11-02',phrase:"Ils se sont ___ au travail dès l'aube.",choix:["mises","mis","mit"],bonne:1,regle:"Se mettre au travail, sans autre COD : accord avec le sujet « ils », masculin pluriel. Le participe de mettre est « mis »."},
  {id:'o82',niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:'2026-11-02',phrase:"Les crêpes ? Je les ai ___ ce matin.",choix:["faites","fait","faits"],bonne:0,regle:"Le COD « les » (les crêpes) est placé avant avoir : accord au féminin pluriel."},
  {id:"o83",niv:1,src:"Bescherelle, L'orthographe pour tous (ces/ses)",vu:"2026-11-04",phrase:"___ livres sont rangés sur l'étagère du salon.",choix:["Ses","Ces","C'est"],bonne:1,regle:"« Ces » montre : ces livres-là. « Ses » marque la possession (les siens), ce que rien n'indique ici."},
  {id:"o84",niv:1,src:"Bescherelle, L'orthographe pour tous (ces/ses)",vu:"2026-11-04",phrase:"Elle a pris ___ affaires et elle est partie.",choix:["ces","ses","c'est"],bonne:1,regle:"Ce sont les siennes : « ses »."},
  {id:"o85",niv:1,src:"Bescherelle, L'orthographe pour tous (c'est/s'est)",vu:"2026-11-04",phrase:"___ une belle journée pour se promener.",choix:["C'est","S'est","Sait"],bonne:0,regle:"« Cela est » une belle journée : « c'est »."},
  {id:"o86",niv:1,src:"Bescherelle, L'orthographe pour tous (c'est/s'est)",vu:"2026-11-04",phrase:"Il ___ blessé en tombant de vélo.",choix:["c'est","s'est","sait"],bonne:1,regle:"Verbe pronominal « se blesser » : il s'est blessé. On ne peut pas dire « cela est blessé »."},
  {id:"o87",niv:1,src:"Bescherelle, L'orthographe pour tous (ou/où)",vu:"2026-11-04",phrase:"Tu préfères le thé ___ le café ?",choix:["ou","où"],bonne:0,regle:"« Ou » marque le choix : on peut dire « ou bien ». « Où » indique le lieu ou le temps."},
  {id:"o88",niv:1,src:"Bescherelle, L'orthographe pour tous (ou/où)",vu:"2026-11-04",phrase:"La maison ___ j'ai grandi a été vendue.",choix:["ou","où"],bonne:1,regle:"Lieu : la maison dans laquelle. On ne peut pas dire « ou bien »."},
  {id:"o89",niv:1,src:"Bescherelle, L'orthographe pour tous (son/sont)",vu:"2026-11-04",phrase:"Les enfants ___ dans le jardin.",choix:["son","sont"],bonne:1,regle:"Verbe être : on peut dire « étaient ». « Son » est un déterminant : son jardin."},
  {id:"o90",niv:1,src:"Bescherelle, L'orthographe pour tous (son/sont)",vu:"2026-11-04",phrase:"Il a perdu ___ parapluie dans le métro.",choix:["son","sont"],bonne:0,regle:"C'est le sien : déterminant possessif « son »."},
  {id:"o91",niv:1,src:"Bescherelle, L'orthographe pour tous (la/là/l'a)",vu:"2026-11-04",phrase:"Pose ton sac ___, près de la porte.",choix:["la","là","l'a"],bonne:1,regle:"« Là » indique le lieu, avec un accent grave."},
  {id:"o92",niv:1,src:"Bescherelle, L'orthographe pour tous (la/là/l'a)",vu:"2026-11-04",phrase:"Cette lettre, il ___ lue deux fois.",choix:["la","là","l'a"],bonne:2,regle:"On peut dire « il l'avait lue » : c'est le pronom l' suivi du verbe avoir."},
  {id:"o93",niv:1,src:"Bescherelle, L'orthographe pour tous (peu/peut/peux)",vu:"2026-11-04",phrase:"Il ___ venir demain s'il le souhaite.",choix:["peu","peut","peux"],bonne:1,regle:"Verbe pouvoir à la 3e personne : il peut (on peut dire « il pouvait »)."},
  {id:"o94",niv:1,src:"Bescherelle, L'orthographe pour tous (peu/peut/peux)",vu:"2026-11-04",phrase:"Il reste un ___ de soupe dans la casserole.",choix:["peu","peut","peux"],bonne:0,regle:"« Un peu » marque la petite quantité : on ne peut pas dire « pouvait »."},
  {id:"o95",niv:2,src:"Bescherelle, L'orthographe pour tous (leur/leurs)",vu:"2026-11-04",phrase:"Je ___ souhaite bonne chance à tous les deux.",choix:["leur","leurs"],bonne:0,regle:"Devant un verbe, « leur » est un pronom (= à eux) : il est toujours invariable."},
  {id:"o96",niv:2,src:"Bescherelle, L'orthographe pour tous (leur/leurs)",vu:"2026-11-04",phrase:"Les voisins ont garé ___ voitures devant chez nous.",choix:["leur","leurs"],bonne:1,regle:"Chacun a sa voiture : il y a plusieurs voitures, « leurs » s'accorde."},
  {id:"o97",niv:2,src:"Bescherelle, L'orthographe pour tous (ni/n'y)",vu:"2026-11-04",phrase:"Ce jardin, il ___ va plus depuis l'hiver.",choix:["ni","n'y"],bonne:1,regle:"« Il ne va plus là-bas » : « n'y », négation et pronom y."},
  {id:"o98",niv:2,src:"Bescherelle, L'orthographe pour tous (sans/s'en)",vu:"2026-11-04",phrase:"Il est parti ___ prévenir personne.",choix:["sans","s'en","c'en"],bonne:0,regle:"« Sans » est une préposition : on peut dire « avec »."},
  {id:"o99",niv:2,src:"Bescherelle, L'orthographe pour tous (sans/s'en)",vu:"2026-11-04",phrase:"Il a pris le dernier gâteau et ___ est allé.",choix:["sans","s'en","c'en"],bonne:1,regle:"Verbe « s'en aller » : il s'en est allé."},
  {id:"o100",niv:2,src:"Bescherelle, L'orthographe pour tous (quand/quant/qu'en)",vu:"2026-11-04",phrase:"___ à moi, je reste à la maison.",choix:["Quand","Quant","Qu'en"],bonne:1,regle:"« Quant à » veut dire « en ce qui concerne ». « Quand » indique le temps."},
  {id:"o101",niv:1,src:"Bescherelle, L'orthographe pour tous (quand/quant/qu'en)",vu:"2026-11-04",phrase:"Préviens-moi ___ tu arriveras.",choix:["quand","quant","qu'en"],bonne:0,regle:"Temps : « au moment où ». On peut dire « lorsque »."},
  {id:"o102",niv:2,src:"Bescherelle, L'orthographe pour tous (quand/quant/qu'en)",vu:"2026-11-04",phrase:"___ penses-tu, toi ?",choix:["Quand","Quant","Qu'en"],bonne:2,regle:"« Que penses-tu de cela ? » : « qu'en », que + en."},
  {id:"o103",niv:2,src:"Bescherelle, L'orthographe pour tous (quel/qu'elle)",vu:"2026-11-04",phrase:"___ belle surprise !",choix:["Quel","Quelle","Qu'elle"],bonne:1,regle:"Exclamation devant un nom féminin : « quelle » s'accorde avec « surprise »."},
  {id:"o104",niv:2,src:"Bescherelle, L'orthographe pour tous (quel/qu'elle)",vu:"2026-11-04",phrase:"Je crois ___ viendra ce soir.",choix:["quelle","qu'elle"],bonne:1,regle:"On peut dire « qu'il viendra » : c'est « que » + « elle »."},
  {id:"o105",niv:1,src:"Bescherelle, L'orthographe pour tous (mes/mais/m'est)",vu:"2026-11-04",phrase:"Je voulais venir, ___ j'étais malade.",choix:["mes","mais","m'est"],bonne:1,regle:"« Mais » marque l'opposition : on peut dire « pourtant »."},
  {id:"o106",niv:2,src:"Bescherelle, L'orthographe pour tous (mes/mais/m'est)",vu:"2026-11-04",phrase:"Il ___ venu une idée en marchant.",choix:["mes","mais","m'est"],bonne:2,regle:"« Il est venu à moi » : « m'est », pronom me + verbe être."},
  {id:"o107",niv:2,src:"Bescherelle, L'orthographe pour tous (près/prêt)",vu:"2026-11-04",phrase:"Le train est ___ à partir.",choix:["près","prêt"],bonne:1,regle:"« Prêt à » veut dire préparé, disposé. « Près de » indique la proximité."},
  {id:"o108",niv:2,src:"Bescherelle, L'orthographe pour tous (près/prêt)",vu:"2026-11-04",phrase:"Il habite tout ___ de la gare.",choix:["près","prêt"],bonne:0,regle:"Proximité : « près de »."},
  {id:"o109",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « plutôt »",vu:"2026-11-04",phrase:"Arrive ___ demain, nous aurons le temps de parler.",choix:["plutôt","plus tôt"],bonne:1,regle:"« Plus tôt » s'oppose à « plus tard ». « Plutôt » marque la préférence."},
  {id:"o110",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « plutôt »",vu:"2026-11-04",phrase:"Je prendrai ___ le train que la voiture.",choix:["plutôt","plus tôt"],bonne:0,regle:"Préférence : « de préférence ». On ne peut pas dire « plus tard »."},
  {id:"o111",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (quoique/quoi que)",vu:"2026-11-04",phrase:"___ tu fasses, fais-le bien.",choix:["Quoique","Quoi que"],bonne:1,regle:"« Quoi que » en deux mots veut dire « quelle que soit la chose que ». « Quoique » en un mot veut dire « bien que »."},
  {id:"o112",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (quoique/quoi que)",vu:"2026-11-04",phrase:"___ fatigué, il a terminé la course.",choix:["Quoique","Quoi que"],bonne:0,regle:"On peut dire « bien que fatigué » : « quoique » en un mot."},
  {id:"o113",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (quel que)",vu:"2026-11-04",phrase:"___ soient tes raisons, je ne changerai pas d'avis.",choix:["Quelles que","Quelques","Quel que"],bonne:0,regle:"Devant le verbe être, « quel que » s'écrit en deux mots et « quel » s'accorde avec le sujet : tes raisons, féminin pluriel."},
  {id:"o114",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (quelque)",vu:"2026-11-04",phrase:"Il a lu ___ livres pendant les vacances.",choix:["quelques","quelque","quels que"],bonne:0,regle:"Devant un nom pluriel, « quelques » veut dire « un petit nombre de » et s'accorde."},
  {id:"o115",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (quelque)",vu:"2026-11-04",phrase:"Il y a ___ trente ans, cette rue était un champ.",choix:["quelques","quelque"],bonne:1,regle:"Devant un nombre, « quelque » veut dire « environ » : c'est un adverbe, invariable."},
  {id:"o116",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « censé »",vu:"2026-11-04",phrase:"Il n'est pas ___ ignorer la loi.",choix:["censé","sensé"],bonne:0,regle:"« Censé » veut dire « supposé ». « Sensé » veut dire « qui a du bon sens »."},
  {id:"o117",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « sensé »",vu:"2026-11-04",phrase:"C'est une remarque très ___.",choix:["censée","sensée"],bonne:1,regle:"Pleine de bon sens : « sensée »."},
  {id:"o118",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « voire »",vu:"2026-11-04",phrase:"Ce film est long, ___ ennuyeux.",choix:["voir","voire"],bonne:1,regle:"« Voire » veut dire « et même ». « Voir » est le verbe."},
  {id:"o119",niv:2,src:"Académie française, Dire, ne pas dire (à faire, affaire)",vu:"2026-11-04",phrase:"J'ai encore beaucoup de choses ___ avant ce soir.",choix:["à faire","affaire"],bonne:0,regle:"Des choses que je dois faire : « à faire », préposition + verbe."},
  {id:"o120",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, article « tache »",vu:"2026-11-04",phrase:"Il a une ___ d'encre sur sa chemise.",choix:["tache","tâche"],bonne:0,regle:"La « tache » est une salissure. La « tâche », avec accent, est un travail à faire."},
  {id:"o121",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, article « tâche »",vu:"2026-11-04",phrase:"Chacun s'acquitte de sa ___ avec soin.",choix:["tache","tâche"],bonne:1,regle:"Un travail à accomplir : « tâche », avec un accent circonflexe."},
  {id:"o122",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (tout)",vu:"2026-11-04",phrase:"Ils sont ___ venus à la fête.",choix:["tous","tout","toutes"],bonne:0,regle:"Pronom qui reprend « ils » : tous (on prononce le s)."},
  {id:"o123",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (tout adverbe)",vu:"2026-11-04",phrase:"Elles étaient ___ émues par ce discours.",choix:["tout","toutes"],bonne:0,regle:"Devant un adjectif féminin commençant par une voyelle, « tout » adverbe (= tout à fait) reste invariable : tout émues."},
  {id:"o124",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (tout adverbe)",vu:"2026-11-04",phrase:"Elles étaient ___ honteuses de leur erreur.",choix:["tout","toutes"],bonne:1,regle:"Devant un adjectif féminin commençant par une consonne ou un h aspiré, « tout » adverbe s'accorde par euphonie : toutes honteuses."},
  {id:"o125",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « davantage »",vu:"2026-11-04",phrase:"Il faudrait travailler ___.",choix:["davantage","d'avantage"],bonne:0,regle:"« Davantage » en un mot veut dire « plus ». « D'avantage » veut dire « d'un avantage » : il n'y a pas d'avantage."},
  {id:"o126",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « cours »",vu:"2026-11-04",phrase:"Cet élève suit des ___ de dessin le mercredi.",choix:["cours","cour","court"],bonne:0,regle:"Des leçons : « cours », toujours avec un s. La « cour » est un espace (la cour de récréation), « court » est un adjectif ou un terrain de tennis."},
  {id:"o127",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, article « cour »",vu:"2026-11-04",phrase:"Les enfants jouent dans la ___ de l'école.",choix:["cours","cour","court"],bonne:1,regle:"L'espace entouré de bâtiments : « la cour »."},
  {id:"o128",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-04",phrase:"Nous avons ___ la maison de fond en comble.",choix:["nettoyée","nettoyé","nettoyés"],bonne:1,regle:"Le COD « la maison » est placé après le verbe : pas d'accord avec avoir."},
  {id:"o129",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec être)",vu:"2026-11-04",phrase:"Elles sont ___ à l'heure ce matin.",choix:["arrivé","arrivées","arrivés"],bonne:1,regle:"Avec être, le participe s'accorde avec le sujet « elles » : féminin pluriel."},
  {id:"o130",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:"2026-11-04",phrase:"La réunion s'est ___ sans incident.",choix:["déroulé","déroulée","déroulés"],bonne:1,regle:"Verbe essentiellement pronominal : accord avec le sujet « la réunion »."},
  {id:"o131",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:"2026-11-04",phrase:"Elles se sont ___ des cadeaux.",choix:["offert","offertes","offerts"],bonne:0,regle:"Le COD « des cadeaux » est placé après ; « se » est complément indirect (à elles-mêmes) : pas d'accord."},
  {id:"o132",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:"2026-11-04",phrase:"Les cadeaux qu'elles se sont ___ étaient ravissants.",choix:["offert","offertes","offerts"],bonne:2,regle:"Le COD « qu' », mis pour « les cadeaux », est placé avant : accord au masculin pluriel."},
  {id:"o133",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:"2026-11-04",phrase:"Ils se sont ___ sans se dire un mot.",choix:["parlé","parlés"],bonne:0,regle:"On parle à quelqu'un : « se » est complément indirect. Pas d'accord."},
  {id:"o134",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (verbes pronominaux)",vu:"2026-11-04",phrase:"Elles se sont ___ dans le miroir.",choix:["regardé","regardées"],bonne:1,regle:"On regarde quelqu'un : « se » est COD, placé avant. Accord avec elles."},
  {id:"o135",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe des verbes impersonnels)",vu:"2026-11-04",phrase:"Les efforts qu'il a ___ pour réussir sont immenses.",choix:["fallu","fallus"],bonne:0,regle:"« Falloir » est impersonnel : son participe est toujours invariable."},
  {id:"o136",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe et complément de mesure)",vu:"2026-11-04",phrase:"Les trois heures que j'ai ___ m'ont paru longues.",choix:["marché","marchées"],bonne:0,regle:"« Pendant trois heures » est un complément de durée, pas un COD : pas d'accord."},
  {id:"o137",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe suivi d'un infinitif)",vu:"2026-11-04",phrase:"La chanson que j'ai entendu ___ était très belle.",choix:["chanter","chantée"],bonne:0,regle:"Après un participe suivi d'un infinitif, c'est l'infinitif qui suit : « entendu chanter »."},
  {id:"o138",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe suivi d'un infinitif)",vu:"2026-11-04",phrase:"Les musiciens que j'ai ___ jouer étaient excellents.",choix:["entendu","entendus"],bonne:1,regle:"Ce sont les musiciens qui jouent : le COD placé avant fait l'action de l'infinitif, on accorde."},
  {id:"o139",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe avec en)",vu:"2026-11-04",phrase:"Des pommes, j'en ai ___ trois.",choix:["mangé","mangées"],bonne:0,regle:"Avec « en », le participe reste en général invariable."},
  {id:"o140",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (adjectifs de couleur)",vu:"2026-11-04",phrase:"Elle porte des chaussures ___.",choix:["marron","marrons"],bonne:0,regle:"Une couleur désignée par un nom (le marron, le fruit) reste invariable : des chaussures marron, orange."},
  {id:"o141",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (adjectifs de couleur)",vu:"2026-11-04",phrase:"Il a acheté des chemises ___.",choix:["blanche","blanches"],bonne:1,regle:"« Blanc » est un vrai adjectif de couleur : il s'accorde."},
  {id:"o142",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (adjectifs de couleur composés)",vu:"2026-11-04",phrase:"Elle a les yeux ___.",choix:["bleu clair","bleus clairs","bleus clair"],bonne:0,regle:"Un adjectif de couleur composé reste invariable : des yeux bleu clair."},
  {id:"o143",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (vingt et cent)",vu:"2026-11-04",phrase:"La salle compte quatre-___ places.",choix:["vingt","vingts"],bonne:1,regle:"« Vingt » prend un s quand il est multiplié et termine le nombre : quatre-vingts."},
  {id:"o144",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (vingt et cent)",vu:"2026-11-04",phrase:"Il y avait quatre-___-deux participants.",choix:["vingt","vingts"],bonne:0,regle:"Suivi d'un autre nombre, « vingt » ne prend pas de s : quatre-vingt-deux."},
  {id:"o145",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (vingt et cent)",vu:"2026-11-04",phrase:"Ce livre coûte deux ___ euros.",choix:["cent","cents"],bonne:1,regle:"« Cent » multiplié et qui termine le nombre prend un s : deux cents."},
  {id:"o146",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (vingt et cent)",vu:"2026-11-04",phrase:"Il a payé trois ___ cinquante euros.",choix:["cent","cents"],bonne:0,regle:"Suivi d'un autre nombre, « cent » ne prend pas de s : trois cent cinquante."},
  {id:"o147",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (mille)",vu:"2026-11-04",phrase:"La ville compte dix ___ habitants.",choix:["mille","milles"],bonne:0,regle:"« Mille », nombre, est toujours invariable."},
  {id:"o148",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (demi)",vu:"2026-11-04",phrase:"Il est arrivé à midi et ___.",choix:["demi","demie"],bonne:0,regle:"Après le nom, « demi » s'accorde en genre avec lui. « Midi » est masculin : midi et demi. Mais : une heure et demie."},
  {id:"o149",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (demi)",vu:"2026-11-04",phrase:"Nous avons attendu une ___-heure.",choix:["demi","demie"],bonne:0,regle:"Devant le nom, avec un trait d'union, « demi » reste invariable : une demi-heure."},
  {id:"o150",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (demi)",vu:"2026-11-04",phrase:"Il est resté deux heures et ___.",choix:["demi","demie"],bonne:1,regle:"Après le nom, « demi » s'accorde en genre avec lui : heure est féminin, donc « et demie »."},
  {id:"o151",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (même)",vu:"2026-11-04",phrase:"Ils sont venus eux-___.",choix:["même","mêmes"],bonne:1,regle:"Après un pronom, « même » s'accorde : eux-mêmes."},
  {id:"o152",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (même)",vu:"2026-11-04",phrase:"Les enfants, ___ les plus jeunes, ont compris.",choix:["même","mêmes"],bonne:0,regle:"« Même » veut dire ici « aussi, y compris » : c'est un adverbe, invariable."},
  {id:"o153",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (chaque)",vu:"2026-11-04",phrase:"___ élève doit apporter son cahier.",choix:["Chaque","Chaques"],bonne:0,regle:"« Chaque » est toujours au singulier."},
  {id:"o154",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (ci-joint)",vu:"2026-11-04",phrase:"Vous trouverez la copie ___.",choix:["ci-joint","ci-jointe"],bonne:1,regle:"Placé après le nom, « ci-joint » s'accorde comme un adjectif : la copie ci-jointe."},
  {id:"o155",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (nu)",vu:"2026-11-04",phrase:"Il marchait ___ dans le sable.",choix:["nu-pieds","nus-pieds","nu-pied"],bonne:0,regle:"Devant le nom, avec un trait d'union, « nu » est invariable : nu-pieds. Mais : pieds nus."},
  {id:"o156",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du verbe)",vu:"2026-11-04",phrase:"Les feuilles mortes ___ le chemin.",choix:["recouvre","recouvrent"],bonne:1,regle:"Le verbe s'accorde avec son sujet, « les feuilles mortes », pluriel."},
  {id:"o157",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord avec un collectif)",vu:"2026-11-04",phrase:"La plupart des invités ___ déjà partis.",choix:["est","sont"],bonne:1,regle:"Avec « la plupart de », le verbe s'accorde avec le complément au pluriel."},
  {id:"o158",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord après qui)",vu:"2026-11-04",phrase:"C'est moi qui ___ raison.",choix:["a","ai"],bonne:1,regle:"Après « qui », le verbe s'accorde avec l'antécédent « moi » : j'ai raison, donc « moi qui ai »."},
  {id:"o159",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord après qui)",vu:"2026-11-04",phrase:"C'est toi qui ___ le plus vite.",choix:["court","cours"],bonne:1,regle:"Le verbe s'accorde avec l'antécédent « toi » : tu cours."},
  {id:"o160",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord avec plusieurs sujets)",vu:"2026-11-04",phrase:"Ma sœur et moi ___ partis tôt.",choix:["sommes","sont"],bonne:0,regle:"« Ma sœur et moi » équivaut à « nous » : nous sommes."},
  {id:"o161",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des noms en -ail)",vu:"2026-11-04",phrase:"Ces ___ sont très confortables.",choix:["chandails","chandaux"],bonne:0,regle:"Les noms en -ail font leur pluriel en -s, sauf sept exceptions (bail, corail, émail, soupirail, travail, vantail, vitrail)."},
  {id:"o162",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des noms en -ail)",vu:"2026-11-04",phrase:"Les ___ du château sont splendides.",choix:["vitrails","vitraux"],bonne:1,regle:"« Vitrail » fait partie des exceptions : des vitraux."},
  {id:"o163",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des noms en -ou)",vu:"2026-11-04",phrase:"Il a rangé ses ___ dans le placard.",choix:["bijous","bijoux"],bonne:1,regle:"Sept noms en -ou prennent un x au pluriel : bijou, caillou, chou, genou, hibou, joujou, pou."},
  {id:"o164",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des noms)",vu:"2026-11-04",phrase:"Les ___ de l'autoroute sont chers.",choix:["péages","péage"],bonne:0,regle:"Plusieurs péages : le nom prend un s."},
  {id:"o165",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (noms composés)",vu:"2026-11-04",phrase:"Il fait des ___ d'œil à tout le monde.",choix:["clins","clin"],bonne:0,regle:"Dans « clin d'œil », c'est « clin » qui varie : des clins d'œil."},
  {id:"o166",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (noms composés)",vu:"2026-11-04",phrase:"Ils ont acheté deux ___ neufs.",choix:["tire-bouchons","tires-bouchons","tire-bouchon"],bonne:0,regle:"Dans un nom composé d'un verbe et d'un nom, le verbe reste invariable ; le nom prend la marque du pluriel : des tire-bouchons."},
  {id:"o167",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (noms composés)",vu:"2026-11-04",phrase:"Les ___ sont fleuris au printemps.",choix:["arcs-en-ciel","arcs-en-ciels"],bonne:0,regle:"Seul le premier nom varie : des arcs-en-ciel."},
  {id:"o168",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (noms composés avec grand)",vu:"2026-11-04",phrase:"Ses ___ sont bien entretenus.",choix:["grands-parents","grand-parents"],bonne:0,regle:"Dans « grands-parents », l'adjectif s'accorde : grands. Mais « grand-mère » au singulier."},
  {id:"o169",niv:1,src:"Bescherelle, La conjugaison pour tous (infinitif)",vu:"2026-11-04",phrase:"Je vais ___ mes devoirs ce soir.",choix:["finir","finis","fini"],bonne:0,regle:"Après « aller », le verbe est à l'infinitif : je vais finir."},
  {id:"o170",niv:1,src:"Bescherelle, La conjugaison pour tous (infinitif)",vu:"2026-11-04",phrase:"Il faut ___ la table avant le dîner.",choix:["mettre","mets","mis"],bonne:0,regle:"Après « il faut », l'infinitif : il faut mettre."},
  {id:"o171",niv:1,src:"Bescherelle, La conjugaison pour tous (-é/-er/-ez)",vu:"2026-11-04",phrase:"Vous ___ vraiment très bien.",choix:["chanté","chantez","chanter"],bonne:1,regle:"Présent avec « vous » : vous chantez. On peut remplacer par « vous prenez »."},
  {id:"o172",niv:1,src:"Bescherelle, La conjugaison pour tous (-é/-er/-ez)",vu:"2026-11-04",phrase:"Il a ___ toute la soirée.",choix:["dansé","danser","dansez"],bonne:0,regle:"Après l'auxiliaire avoir, le participe passé : il a dansé. On peut dire « il a pris »."},
  {id:"o173",niv:1,src:"Bescherelle, La conjugaison pour tous (-é/-er/-ez)",vu:"2026-11-04",phrase:"Elle commence à ___ le piano.",choix:["étudié","étudier"],bonne:1,regle:"Après une préposition (à, de, pour…), on met l'infinitif : on peut dire « à prendre »."},
  {id:"o174",niv:2,src:"Bescherelle, La conjugaison pour tous (futur/conditionnel)",vu:"2026-11-04",phrase:"Demain, je ___ à la piscine.",choix:["serai","serais"],bonne:0,regle:"Futur, une action certaine : je serai. « Je serais » est le conditionnel."},
  {id:"o175",niv:2,src:"Bescherelle, La conjugaison pour tous (futur/conditionnel)",vu:"2026-11-04",phrase:"Si j'avais le temps, je ___ un livre.",choix:["lirai","lirais"],bonne:1,regle:"Après « si » + imparfait, le verbe principal est au conditionnel : je lirais."},
  {id:"o176",niv:2,src:"Bescherelle, La conjugaison pour tous (subjonctif)",vu:"2026-11-04",phrase:"J'aimerais que tu ___ plus tôt.",choix:["viens","viennes"],bonne:1,regle:"Après « j'aimerais que », le subjonctif : que tu viennes."},
  {id:"o177",niv:2,src:"Bescherelle, La conjugaison pour tous (subjonctif)",vu:"2026-11-04",phrase:"Il faut que nous ___ rapidement.",choix:["partons","partions"],bonne:1,regle:"Après « il faut que », le subjonctif : que nous partions (avec un i)."},
  {id:"o178",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (bien que)",vu:"2026-11-04",phrase:"Bien qu'il ___ tard, nous continuons.",choix:["est","soit"],bonne:1,regle:"« Bien que » est suivi du subjonctif : bien qu'il soit."},
  {id:"o179",niv:3,src:"Académie française, Dire, ne pas dire (après que)",vu:"2026-11-04",phrase:"Après qu'il ___ parti, la fête continue.",choix:["est","soit"],bonne:0,regle:"« Après que » est suivi de l'indicatif, car l'action est réalisée : après qu'il est parti. Le subjonctif, très répandu, est critiqué."},
  {id:"o180",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (avant que)",vu:"2026-11-04",phrase:"Avant qu'il ___, rangeons la maison.",choix:["arrive","arrivera"],bonne:0,regle:"« Avant que » est suivi du subjonctif : avant qu'il arrive."},
  {id:"o181",niv:2,src:"Bescherelle, La conjugaison pour tous (peindre)",vu:"2026-11-04",phrase:"Il ___ sa chambre en bleu l'été dernier.",choix:["peint","peignit","peindit"],bonne:1,regle:"Passé simple de « peindre » : il peignit. « Peindit » n'existe pas."},
  {id:"o182",niv:2,src:"Bescherelle, La conjugaison pour tous (prendre)",vu:"2026-11-04",phrase:"Je ___ mon manteau et je sortis.",choix:["pris","prit","prends"],bonne:0,regle:"Passé simple de « prendre » à la 1re personne : je pris."},
  {id:"o183",niv:2,src:"Bescherelle, La conjugaison pour tous (ouvrir)",vu:"2026-11-04",phrase:"Il ___ la porte et entra sans frapper.",choix:["ouvra","ouvrit"],bonne:1,regle:"« Ouvrir » se conjugue au passé simple comme un verbe en -ir : il ouvrit."},
  {id:"o184",niv:2,src:"Bescherelle, La conjugaison pour tous (cueillir)",vu:"2026-11-04",phrase:"Je ___ des champignons chaque automne.",choix:["cueille","cueilles","cueillis"],bonne:0,regle:"« Cueillir » se conjugue au présent comme un verbe en -er : je cueille."},
  {id:"o185",niv:2,src:"Bescherelle, La conjugaison pour tous (appeler)",vu:"2026-11-04",phrase:"Il ___ ses amis pour son anniversaire.",choix:["appelle","appele","apelle"],bonne:0,regle:"« Appeler » double le l devant un e muet : il appelle, mais nous appelons."},
  {id:"o186",niv:2,src:"Bescherelle, La conjugaison pour tous (jeter)",vu:"2026-11-04",phrase:"Nous ___ nos vieux papiers.",choix:["jetons","jettons"],bonne:0,regle:"« Jeter » double le t seulement devant un e muet : je jette, mais nous jetons."},
  {id:"o187",niv:2,src:"Bescherelle, La conjugaison pour tous (lever)",vu:"2026-11-04",phrase:"Il ___ chaque matin à six heures.",choix:["se lève","se lêve","se léve"],bonne:0,regle:"« Lever » prend un accent grave devant une syllabe muette : il se lève."},
  {id:"o188",niv:2,src:"Bescherelle, La conjugaison pour tous (dire)",vu:"2026-11-04",phrase:"Vous ___ toujours la vérité.",choix:["dites","disez"],bonne:0,regle:"« Dire » fait « vous dites » au présent, comme « faire » fait « vous faites »."},
  {id:"o189",niv:2,src:"Bescherelle, La conjugaison pour tous (faire)",vu:"2026-11-04",phrase:"Que ___-vous ce week-end ?",choix:["faites","faisez"],bonne:0,regle:"Le présent de « faire » est « vous faites ». « Faisez » n'existe pas."},
  {id:"o190",niv:3,src:"Bescherelle, La conjugaison pour tous (résoudre)",vu:"2026-11-04",phrase:"Il ___ la solution après une heure de recherche.",choix:["résolut","résolva","résout"],bonne:0,regle:"Passé simple de « résoudre » : il résolut."},
  {id:"o191",niv:3,src:"Bescherelle, La conjugaison pour tous (résoudre)",vu:"2026-11-04",phrase:"Le problème est enfin ___.",choix:["résolu","résout","résous"],bonne:0,regle:"Participe passé de « résoudre » : résolu."},
  {id:"o192",niv:3,src:"Dictionnaire de l'Académie française, 9e édition, article « acquis »",vu:"2026-11-04",phrase:"Il a ___ une grande expérience à l'étranger.",choix:["acquis","acquit","acquéri"],bonne:0,regle:"Participe passé d'« acquérir » : acquis. « Acquit » est un autre mot (pour acquit, au sens de quittance)."},
  {id:"o193",niv:2,src:"Bescherelle, La conjugaison pour tous (croire)",vu:"2026-11-04",phrase:"Je ___ que tu as raison.",choix:["crois","croit"],bonne:0,regle:"Avec « je », le verbe croire prend un s : je crois."},
  {id:"o194",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (impératif)",vu:"2026-11-04",phrase:"___-moi tes cahiers, s'il te plaît.",choix:["Donnes","Donne"],bonne:1,regle:"À l'impératif, les verbes en -er n'ont pas de s à la 2e personne du singulier : donne."},
  {id:"o195",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (impératif)",vu:"2026-11-04",phrase:"Des légumes ? ___-en un peu plus.",choix:["Prends","Prend"],bonne:0,regle:"« Prendre » n'est pas un verbe en -er : à l'impératif, il garde son s, prends."},
  {id:"o196",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (impératif)",vu:"2026-11-04",phrase:"Des pommes ? ___-en une.",choix:["Mange","Manges"],bonne:1,regle:"Devant « en » ou « y », l'impératif en -e prend un s pour la liaison : manges-en."},
  {id:"o197",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (fut/fût)",vu:"2026-11-04",phrase:"Il fallait qu'il ___ prêt avant l'aube.",choix:["fut","fût"],bonne:1,regle:"Subjonctif imparfait : qu'il fût, avec un accent circonflexe. « Il fut », sans accent, est un passé simple."},
  {id:"o198",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (fut/fût)",vu:"2026-11-04",phrase:"Il ___ roi pendant vingt ans.",choix:["fut","fût"],bonne:0,regle:"Passé simple de l'indicatif : il fut, sans accent."},
  {id:"o199",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (si + présent)",vu:"2026-11-04",phrase:"Si tu ___ venir, préviens-moi.",choix:["peux","pourrais","pourras"],bonne:0,regle:"Après « si » de condition, l'indicatif présent : si tu peux."},
  {id:"o200",niv:2,src:"Académie française, Dire, ne pas dire (pallier)",vu:"2026-11-04",phrase:"Il faut ___ ce manque de moyens.",choix:["pallier","pallier à"],bonne:0,regle:"« Pallier » est transitif direct : on pallie quelque chose, sans « à »."},
  {id:"o201",niv:2,src:"Académie française, Dire, ne pas dire (se rappeler)",vu:"2026-11-04",phrase:"Je me ___ très bien de ce voyage.",choix:["rappelle","souviens"],bonne:1,regle:"On se souvient DE quelque chose, mais on se rappelle quelque chose (sans « de ») : je me rappelle ce voyage."},
  {id:"o202",niv:2,src:"Académie française, Dire, ne pas dire (se rappeler)",vu:"2026-11-04",phrase:"Je ___ notre première rencontre.",choix:["me rappelle","me rappelle de"],bonne:0,regle:"« Se rappeler » se construit sans « de » : je me rappelle notre rencontre."},
  {id:"o203",niv:2,src:"Académie française, Dire, ne pas dire (aller au coiffeur)",vu:"2026-11-04",phrase:"Demain, je vais ___ coiffeur.",choix:["au","chez le"],bonne:1,regle:"On va chez une personne, à un lieu : chez le coiffeur, chez le médecin ; mais à la boulangerie."},
  {id:"o204",niv:3,src:"Académie française, Dire, ne pas dire (malgré que)",vu:"2026-11-04",phrase:"___ la pluie, nous sommes sortis.",choix:["Malgré","Malgré que"],bonne:0,regle:"« Malgré » est suivi d'un nom. « Malgré que » est déconseillé par l'Académie : on dit « bien que »."},
  {id:"o205",niv:2,src:"Académie française, Dire, ne pas dire (au temps pour moi)",vu:"2026-11-04",phrase:"Je me suis trompé, ___ !",choix:["au temps pour moi","autant pour moi"],bonne:0,regle:"L'Académie recommande « au temps pour moi », venu du commandement militaire (« au temps ! », reprenez le mouvement). « Autant pour moi » est très répandu."},
  {id:"o206",niv:2,src:"Académie française, Dire, ne pas dire (rémunérer)",vu:"2026-11-04",phrase:"Ce patron ___ bien ses employés.",choix:["rémunère","rénumère"],bonne:0,regle:"« Rémunérer » vient du latin munus, « présent, charge » : ré-mu-né-rer. « Rénumérer » est un barbarisme."},
  {id:"o207",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « infarctus »",vu:"2026-11-04",phrase:"Il a été victime d'un ___.",choix:["infarctus","infractus"],bonne:0,regle:"On écrit et prononce « infarctus » : le c vient avant le t."},
  {id:"o208",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « aéroport »",vu:"2026-11-04",phrase:"Nous partons de l'___ de Lyon.",choix:["aéroport","aréoport"],bonne:0,regle:"« Aéro- » vient du grec aêr, « air » : aéroport, aérien."},
  {id:"o209",niv:3,src:"Dictionnaire de l'Académie française, 9e édition, article « dilemme »",vu:"2026-11-04",phrase:"Il est face à un véritable ___.",choix:["dilemme","dilemne"],bonne:0,regle:"On écrit « dilemme », avec deux m : du grec di-lêmma, « double proposition »."},
  {id:"o210",niv:2,src:"Académie française, Dire, ne pas dire (pécuniaire)",vu:"2026-11-04",phrase:"Il a des soucis ___.",choix:["pécuniaires","pécuniers"],bonne:0,regle:"L'adjectif est « pécuniaire », au masculin comme au féminin : un problème pécuniaire."},
  {id:"o211",niv:3,src:"Dictionnaire de l'Académie française, 9e édition, article « conjoncture »",vu:"2026-11-04",phrase:"La ___ économique est mauvaise cette année.",choix:["conjoncture","conjecture"],bonne:0,regle:"La conjoncture est la situation du moment. Une conjecture est une supposition."},
  {id:"o212",niv:3,src:"Dictionnaire de l'Académie française, 9e édition, article « conjecture »",vu:"2026-11-04",phrase:"Ce n'est qu'une ___ : rien n'est prouvé.",choix:["conjoncture","conjecture"],bonne:1,regle:"Une supposition : « conjecture »."},
  {id:"o213",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « oublier »",vu:"2026-11-04",phrase:"Il a ___ son rendez-vous.",choix:["oublié","oublié de"],bonne:0,regle:"On oublie quelque chose, sans « de » quand le complément est un nom."},
  {id:"o214",niv:2,src:"Bescherelle, La conjugaison pour tous (mettre/émettre)",vu:"2026-11-04",phrase:"Le ministre a ___ un plan ambitieux.",choix:["émis","émit"],bonne:0,regle:"Après l'auxiliaire avoir, le participe passé : a émis."},
  {id:"o215",niv:3,src:"Académie française, Dire, ne pas dire (il s'en faut de peu)",vu:"2026-11-04",phrase:"Il ___ de peu qu'il ne rate son train.",choix:["s'en est fallu","s'en ait fallu"],bonne:0,regle:"« Il s'en est fallu de peu » : passé composé de « falloir » avec être."},
  {id:"o216",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord de l'attribut)",vu:"2026-11-04",phrase:"Il fait ___ dans ce bureau.",choix:["sombre","sombres"],bonne:0,regle:"Sujet impersonnel « il » : l'adjectif reste au singulier."},
  {id:"o217",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, article « piscine »",vu:"2026-11-04",phrase:"Cette ___ est très profonde.",choix:["piscine","picine"],bonne:0,regle:"On écrit « piscine », avec sc, du latin piscina, « vivier »."},
  {id:"o218",niv:2,src:"Bescherelle, La conjugaison pour tous (conclure)",vu:"2026-11-04",phrase:"Ils ont ___ un accord.",choix:["conclu","conclus","conclut"],bonne:0,regle:"Participe passé de « conclure » : conclu (sans s ni t)."},
  {id:"o219",niv:2,src:"Bescherelle, La conjugaison pour tous (exclure/inclure)",vu:"2026-11-04",phrase:"Il a ___ cette hypothèse.",choix:["exclu","exclus","inclu"],bonne:0,regle:"Participe passé d'« exclure » : exclu. Mais attention : « inclure » fait « inclus », avec un s."},
  {id:"o220",niv:3,src:"Bescherelle, La conjugaison pour tous (inclure)",vu:"2026-11-04",phrase:"Le service est ___ dans le prix.",choix:["inclu","inclus"],bonne:1,regle:"Participe passé d'« inclure » : inclus, avec un s, contrairement à « exclu »."},
  {id:"o221",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe détaché)",vu:"2026-11-04",phrase:"___ au pied de la lettre, la consigne est absurde.",choix:["Prise","Pris"],bonne:0,regle:"Le participe se rapporte à « la consigne », féminin : prise."},
  {id:"o222",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des adjectifs)",vu:"2026-11-04",phrase:"Ce sont des femmes très ___.",choix:["matinales","matinals"],bonne:0,regle:"Les adjectifs en -al font -aux au masculin pluriel, mais le féminin pluriel est régulier : matinales."},
  {id:"o223",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des adjectifs en -al)",vu:"2026-11-04",phrase:"Ces combats ont été ___.",choix:["navals","navaux"],bonne:0,regle:"« Naval » fait exception : navals, comme banals, fatals, finals."},
  {id:"o224",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des adjectifs en -al)",vu:"2026-11-04",phrase:"Ces débats étaient très ___.",choix:["banals","banaux"],bonne:0,regle:"« Banal » fait « banals » au masculin pluriel (« banaux » ne survit que dans un vieux sens juridique, les fours banaux)."},
  {id:"o225",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des noms en -ou)",vu:"2026-11-04",phrase:"Il a mal aux ___.",choix:["genous","genoux"],bonne:1,regle:"« Genou » fait partie des sept noms en -ou qui prennent un x : des genoux."},
  {id:"o226",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (nul)",vu:"2026-11-04",phrase:"Je n'ai ___ besoin de ton aide.",choix:["nul","nulle"],bonne:0,regle:"« Nul » s'accorde avec le nom qui suit : « besoin » est masculin, donc « nul besoin ». Mais : nulle part."},
  {id:"o227",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec être)",vu:"2026-11-04",phrase:"Ils sont ___ hier soir.",choix:["rentré","rentrés"],bonne:1,regle:"Avec être, accord avec le sujet « ils » : rentrés."},
  {id:"o228",niv:1,src:"Bescherelle, L'orthographe pour tous (donc/dont)",vu:"2026-11-04",phrase:"Il pleut, ___ nous restons à la maison.",choix:["donc","dont"],bonne:0,regle:"« Donc » annonce une conséquence. « Dont » est un pronom relatif : le livre dont je parle."},
  {id:"o229",niv:2,src:"Bescherelle, L'orthographe pour tous (donc/dont)",vu:"2026-11-04",phrase:"Voici l'ami ___ je t'ai parlé.",choix:["donc","dont","que"],bonne:1,regle:"On parle DE quelqu'un : le relatif est « dont »."},
  {id:"o230",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord de l'attribut)",vu:"2026-11-04",phrase:"Il est ___ qu'il pleuve demain.",choix:["probable","probables"],bonne:0,regle:"Sujet impersonnel « il » : l'adjectif reste au singulier."},
  {id:"o231",niv:2,src:"Bescherelle, L'orthographe pour tous (faut/faux)",vu:"2026-11-04",phrase:"Il ___ attendre son tour.",choix:["faut","faux","fau"],bonne:0,regle:"Verbe « falloir » : il faut. « Faux » est le contraire de vrai, ou l'outil du faucheur."},
  {id:"o232",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (féminin des adjectifs)",vu:"2026-11-04",phrase:"Ta réponse est ___.",choix:["faut","faux","fausse"],bonne:2,regle:"« Réponse » est féminin : faux devient fausse."},
  {id:"o233",niv:1,src:"Bescherelle, La conjugaison pour tous (être)",vu:"2026-11-04",phrase:"Nous ___ allés au cinéma hier.",choix:["somme","sommes"],bonne:1,regle:"Verbe être avec « nous » : nous sommes."},
  {id:"o234",niv:2,src:"Bescherelle, L'orthographe pour tous (on/ont)",vu:"2026-11-04",phrase:"Ils ___ peur du noir.",choix:["on","ont"],bonne:1,regle:"Verbe avoir : ils avaient peur."},
  {id:"o235",niv:1,src:"Bescherelle, L'orthographe pour tous (on/ont)",vu:"2026-11-04",phrase:"___ dit qu'il va neiger.",choix:["On","Ont"],bonne:0,regle:"Pronom sujet : on peut le remplacer par « il »."},
  {id:"o236",niv:2,src:"Bescherelle, La conjugaison pour tous (faire)",vu:"2026-11-04",phrase:"Il a ___ ce qu'il fallait.",choix:["fait","fais","fé"],bonne:0,regle:"Participe passé de « faire » : fait."},
  {id:"o237",niv:2,src:"Bescherelle, La conjugaison pour tous (faire)",vu:"2026-11-04",phrase:"Je ___ du piano depuis dix ans.",choix:["fait","fais"],bonne:1,regle:"Avec « je », le verbe faire prend un s : je fais."},
  {id:"o238",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (adverbe)",vu:"2026-11-04",phrase:"Ce sont des personnes ___ âgées.",choix:["fort","forte","fortes"],bonne:0,regle:"« Fort » veut dire ici « très » : adverbe, invariable."},
  {id:"o239",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « grand »",vu:"2026-11-04",phrase:"La porte était ___ ouverte.",choix:["grand","grande"],bonne:1,regle:"Dans « grand ouvert », « grand » s'accorde traditionnellement : une porte grande ouverte, des fenêtres grandes ouvertes."},
  {id:"o240",niv:2,src:"Bescherelle, L'orthographe pour tous (plus/plu)",vu:"2026-11-04",phrase:"Il n'y a ___ de place dans le train.",choix:["plus","plu","plut"],bonne:0,regle:"Négation « ne… plus ». « Plu » est le participe de plaire et de pleuvoir."},
  {id:"o241",niv:2,src:"Bescherelle, La conjugaison pour tous (plaire)",vu:"2026-11-04",phrase:"Ce film m'a beaucoup ___.",choix:["plus","plu","plut"],bonne:1,regle:"Participe passé de « plaire » : il m'a plu."},
  {id:"o242",niv:3,src:"Bescherelle, La conjugaison pour tous (pleuvoir)",vu:"2026-11-04",phrase:"Il a ___ toute la nuit.",choix:["plu","plut","plus"],bonne:0,regle:"Participe passé de « pleuvoir » : il a plu."},
  {id:"o243",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « foie »",vu:"2026-11-04",phrase:"Il a mangé du ___ gras à Noël.",choix:["fois","foie","foi"],bonne:1,regle:"Le « foie » est l'organe. La « foi » est la croyance, et « une fois » marque le nombre."},
  {id:"o244",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, article « foi »",vu:"2026-11-04",phrase:"Il a gardé la ___ malgré les épreuves.",choix:["fois","foie","foi"],bonne:2,regle:"La croyance, la confiance : « la foi »."},
  {id:"o245",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-04",phrase:"Elle a ___ ses lunettes quelque part.",choix:["mis","mise","mit"],bonne:0,regle:"COD « ses lunettes » placé après : pas d'accord. Participe passé de mettre : mis."},
  {id:"o246",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-04",phrase:"Ses lunettes, elle les a ___ sur la table.",choix:["mis","mises","mit"],bonne:1,regle:"Le COD « les » (ses lunettes) est placé avant : accord au féminin pluriel."},
  {id:"o247",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec être)",vu:"2026-11-04",phrase:"Le magasin est ___ le dimanche.",choix:["fermé","fermer","fermée"],bonne:0,regle:"« Magasin » est masculin : fermé."},
  // art de vivre et patrimoine (novembre 2026) : le vocabulaire de la table, du jardin, de la ferme et du bâti
  {id:"o248",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des noms composés) ; Académie française, « chou-fleur »",vu:"2026-11-05",phrase:"Au marché, j'ai acheté deux ___.",choix:["chou-fleurs","choux-fleurs","choux-fleur"],bonne:1,regle:"Nom + nom : les deux mots prennent la marque du pluriel. Un chou-fleur, des choux-fleurs."},
  {id:"o249",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, « mille-feuille »",vu:"2026-11-05",phrase:"Le pâtissier a préparé trois ___.",choix:["mille-feuilles","milles-feuilles","mille-feuille"],bonne:0,regle:"« Mille » est invariable ; seul « feuille » prend la marque du pluriel."},
  {id:"o250",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, « arc-boutant »",vu:"2026-11-05",phrase:"Les ___ de la cathédrale soutiennent la voûte.",choix:["arc-boutants","arcs-boutant","arcs-boutants"],bonne:2,regle:"Nom + participe employé comme adjectif : les deux varient. Un arc-boutant, des arcs-boutants."},
  {id:"o251",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord de l'adjectif)",vu:"2026-11-05",phrase:"Ces pommes de terre sont ___ à point.",choix:["cuits","cuites","cuite"],bonne:1,regle:"« Pommes de terre » est féminin pluriel : cuites."},
  {id:"o252",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-05",phrase:"Les confitures que ma grand-mère a ___ sont délicieuses.",choix:["fait","faites","faits"],bonne:1,regle:"Le COD « que » (les confitures) est placé avant « avoir » : accord au féminin pluriel."},
  {id:"o253",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-05",phrase:"Elle a ___ les tomates du jardin.",choix:["cueilli","cueillies","cueillit"],bonne:0,regle:"Le COD « les tomates » est placé après : pas d'accord. « Cueillit » est le passé simple."},
  {id:"o254",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-05",phrase:"Les tomates qu'elle a ___ sont encore vertes.",choix:["cueilli","cueillis","cueillies"],bonne:2,regle:"Le COD « que » (les tomates) est placé avant : accord au féminin pluriel."},
  {id:"o255",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, « verre », « ver », « vers », « vert »",vu:"2026-11-05",phrase:"Il a versé un ___ de vin dans la sauce.",choix:["verre","vers","ver","vert"],bonne:0,regle:"Le récipient, c'est le « verre ». « Vers » : la poésie ou la direction ; « ver » : l'animal ; « vert » : la couleur."},
  {id:"o256",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, « ver »",vu:"2026-11-05",phrase:"Le ___ de terre aère le sol du potager.",choix:["verre","ver","vert"],bonne:1,regle:"L'animal s'écrit « ver », comme dans « ver à soie »."},
  {id:"o257",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, « pâte », « patte »",vu:"2026-11-05",phrase:"Le boulanger pétrit la ___ dès l'aube.",choix:["pâte","patte","pâté"],bonne:0,regle:"La « pâte » (farine et eau) prend un accent circonflexe. La « patte » est celle d'un animal, le « pâté » se mange en tranches."},
  {id:"o258",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (infinitif après un verbe)",vu:"2026-11-05",phrase:"Il faut laisser la pâte ___ une heure.",choix:["reposé","reposée","reposer"],bonne:2,regle:"Après « laisser », l'infinitif : on peut dire « laisser mordre », pas « laisser mordu »."},
  {id:"o259",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, « donjon »",vu:"2026-11-05",phrase:"Le ___ du château domine la vallée.",choix:["dongeon","donjon","donjeon"],bonne:1,regle:"« Donjon » s'écrit avec un j, comme « jardin »."},
  {id:"o260",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, « chœur », « cœur »",vu:"2026-11-05",phrase:"Le ___ de l'église est éclairé par des vitraux.",choix:["cœur","chœur","chœurs"],bonne:1,regle:"La partie de l'église où se tient le clergé, comme le groupe de chanteurs, c'est le « chœur ». Le « cœur » est l'organe."},
  {id:"o261",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe des verbes pronominaux)",vu:"2026-11-05",phrase:"Elle s'est ___ une part de tarte.",choix:["servi","servie","servis"],bonne:0,regle:"« Se » est ici complément indirect (servi à elle) ; le COD « une part » est placé après : pas d'accord."},
  {id:"o262",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe des verbes pronominaux)",vu:"2026-11-05",phrase:"La part de tarte qu'elle s'est ___ était énorme.",choix:["servi","servies","servie"],bonne:2,regle:"Le COD « que » (la part) est placé avant : accord au féminin singulier."},
  {id:"o263",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe des verbes pronominaux)",vu:"2026-11-05",phrase:"Les invités se sont ___ la main.",choix:["serrés","serré","serrées"],bonne:1,regle:"Ils ont serré la main à eux-mêmes : « se » est complément indirect, le COD « la main » est après. Pas d'accord."},
  {id:"o264",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe des verbes pronominaux)",vu:"2026-11-05",phrase:"Les invités se sont ___ à table à huit heures.",choix:["mit","mis","mises"],bonne:1,regle:"« Se mettre » : « se » est COD, le participe s'accorde avec le sujet masculin pluriel. « Mis » ne change pas au masculin pluriel ; « mit » est le passé simple."},
  {id:"o265",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe des verbes pronominaux)",vu:"2026-11-05",phrase:"Merci pour ce dîner, mon frère et moi nous sommes ___ !",choix:["régalés","régalé","régaler"],bonne:0,regle:"« Se régaler » s'accorde avec le sujet : « mon frère et moi », masculin pluriel."},
  {id:"o266",niv:3,src:"Grevisse et Goosse, Le Bon Usage, 2016 (mode après « après que »)",vu:"2026-11-05",phrase:"Après qu'il ___ fini son assiette, on servit le dessert.",choix:["eût","ait","eut"],bonne:2,regle:"« Après que » se construit avec l'indicatif : le fait est accompli. Le subjonctif (« eût », « ait ») est une faute courante, par analogie avec « avant que »."},
  {id:"o267",niv:1,src:"Bescherelle, La conjugaison pour tous (être, subjonctif présent)",vu:"2026-11-05",phrase:"Il faut que vous ___ à l'heure chez vos hôtes.",choix:["soyiez","soyez","soyer"],bonne:1,regle:"Subjonctif présent d'« être » : que vous soyez, sans i après le y."},
  {id:"o268",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, « accueillir » ; Le Bon Usage (accord avec avoir)",vu:"2026-11-05",phrase:"Nos hôtes nous ont ___ chaleureusement, mon père et moi.",choix:["accueilli","accueillis","acceuillis"],bonne:1,regle:"Le COD « nous » (masculin pluriel) est placé avant : accord. Et « accueillir » s'écrit « cue » après le c, pour garder le son [k]."},
  {id:"o269",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (infinitif après un verbe)",vu:"2026-11-05",phrase:"À table, il ne faut pas ___ la bouche pleine.",choix:["parler","parlé","parlez"],bonne:0,regle:"Après « il faut », l'infinitif : on dirait « il ne faut pas mordre »."},
  {id:"o270",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-05",phrase:"Le vigneron a ___ ses vignes avant l'hiver.",choix:["taillées","tailler","taillé"],bonne:2,regle:"Le COD « ses vignes » est placé après : pas d'accord."},
  {id:"o271",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-05",phrase:"Les vignes qu'il a ___ donneront un bon vin.",choix:["taillé","taillées","taillés"],bonne:1,regle:"Le COD « que » (les vignes) est placé avant : accord au féminin pluriel."},
  {id:"o272",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe passé employé sans auxiliaire)",vu:"2026-11-05",phrase:"Les jardins ___ par Le Nôtre attirent des visiteurs du monde entier.",choix:["dessiné","dessinés","dessinées"],bonne:1,regle:"Participe employé sans auxiliaire : il s'accorde comme un adjectif avec « jardins », masculin pluriel."},
  {id:"o273",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (infinitif après un verbe)",vu:"2026-11-05",phrase:"Il faut ___ les blancs en neige.",choix:["monter","monté","montez"],bonne:0,regle:"Après « il faut », l'infinitif : on dirait « il faut battre »."},
  {id:"o274",niv:2,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe passé employé sans auxiliaire)",vu:"2026-11-05",phrase:"Une fois ___, les blancs se travaillent délicatement.",choix:["monté","montées","montés"],bonne:2,regle:"Le participe s'accorde avec « les blancs », masculin pluriel."},
  {id:"o275",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, « vitrail »",vu:"2026-11-05",phrase:"Les ___ de la Sainte-Chapelle sont célèbres.",choix:["vitrails","vitraux","vitrals"],bonne:1,regle:"Un vitrail, des vitraux, comme un travail, des travaux."},
  {id:"o276",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (pluriel des noms en -al)",vu:"2026-11-05",phrase:"Le fermier a vendu deux de ses ___.",choix:["chevals","chevaux","cheveaux"],bonne:1,regle:"Les noms en -al font leur pluriel en -aux : un cheval, des chevaux."},
  {id:"o277",niv:3,src:"Dictionnaire de l'Académie française, 9e édition, « vantail »",vu:"2026-11-05",phrase:"Les deux ___ du portail sont en chêne.",choix:["vantaux","ventaux","vantails"],bonne:0,regle:"Un vantail (le battant d'une porte), des vantaux, comme vitrail et travail."},
  {id:"o278",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (article contracté)",vu:"2026-11-05",phrase:"Pour le dessert, une tarte ___ pommes.",choix:["au","os","aux"],bonne:2,regle:"« À les » se contracte en « aux » devant un pluriel : une tarte aux pommes."},
  {id:"o279",niv:2,src:"Dictionnaire de l'Académie française, 9e édition, « pot-au-feu »",vu:"2026-11-05",phrase:"Le ___ mijote depuis trois heures.",choix:["pot au feu","pot-au-feu","pot-aux-feux"],bonne:1,regle:"« Pot-au-feu » s'écrit avec deux traits d'union."},
  {id:"o280",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (accord du participe avec avoir)",vu:"2026-11-05",phrase:"Le chef a ___ le rôti à point.",choix:["cuis","cuit","cuits"],bonne:1,regle:"Le COD « le rôti » est placé après : participe passé sans accord, « cuit »."},
  {id:"o281",niv:1,src:"Grevisse et Goosse, Le Bon Usage, 2016 (participe passé employé sans auxiliaire)",vu:"2026-11-05",phrase:"Ils ont hérité d'une ferme ___ en Auvergne.",choix:["située","situé","situer"],bonne:0,regle:"Le participe s'accorde avec « ferme », féminin singulier."},
  {id:"o282",niv:1,src:"Dictionnaire de l'Académie française, 9e édition, « charpente »",vu:"2026-11-05",phrase:"La ___ de la grange est en chêne.",choix:["charpante","charpent","charpente"],bonne:2,regle:"« Charpente » s'écrit avec « en », comme « charpentier »."}
];

// Lecture et résumé : le texte, trois questions [question, réponses (la bonne en premier, l'appli mélange), explication tirée du texte] —
// un fait, le sens, un mot —, trois idées clés pour vérifier un résumé ; lien : la page Wikisource des extraits du domaine public
B.textes=[
  {id:'t01',th:"sciences",src:"Rasch et Born, Physiological Reviews, 2013",titre:"Le sommeil et la mémoire",
   texte:"Pendant longtemps, on a pensé que le cerveau se mettait en veille la nuit. Les recherches des dernières décennies montrent l'inverse : le sommeil joue un rôle actif dans la mémoire. Pendant le sommeil lent profond, l'hippocampe « rejoue » les expériences de la journée et les transfère progressivement vers le cortex, où elles sont stockées à plus long terme. Le sommeil paradoxal, lui, semble aider à relier les souvenirs entre eux et à en extraire des règles générales. Une nuit blanche après un apprentissage réduit nettement ce que l'on retient, même après plusieurs nuits de récupération. À l'inverse, une courte sieste après une séance d'étude peut améliorer la rétention. Conclusion pratique : réviser tard en sacrifiant son sommeil est souvent un mauvais calcul.",
   quiz:[["Pendant quelle phase l'hippocampe « rejoue »-t-il les expériences de la journée ?",["Le sommeil lent profond","Le sommeil paradoxal","Le sommeil léger"],"Le texte : pendant le sommeil lent profond, l'hippocampe rejoue la journée et la transfère vers le cortex."],["Que provoque une nuit blanche après un apprentissage ?",["Une baisse de rétention qui persiste malgré la récupération","Rien, si l'on récupère les nuits suivantes","Une meilleure mémorisation"],"Une nuit blanche réduit ce que l'on retient, « même après plusieurs nuits de récupération »."],["Pourquoi réviser tard en sacrifiant son sommeil est-il un mauvais calcul ?",["On se prive du travail de mémoire qui se fait la nuit","On lit moins vite le soir","Le sommeil efface ce qu'on a révisé"],"Le sommeil joue un rôle actif : le sacrifier, c'est perdre ce travail de consolidation."]],
   idees:["Le sommeil participe activement à la mémoire","En sommeil profond, l'hippocampe rejoue la journée et la transfère vers le cortex","Sacrifier son sommeil pour réviser est un mauvais calcul"]},
  {id:'t02',th:"sciences",src:"Ebbinghaus, 1885 ; Cepeda et al., Psychological Bulletin, 2006",titre:"L'effet d'espacement",
   texte:"Si tu dois apprendre quelque chose, vaut-il mieux l'étudier trois heures d'affilée ou trois fois une heure, à quelques jours d'intervalle ? Depuis les travaux d'Hermann Ebbinghaus à la fin du XIXe siècle, la réponse est connue : l'apprentissage espacé l'emporte presque toujours. Quand on révise juste avant d'oublier, le cerveau doit faire un effort pour retrouver l'information, et cet effort renforce la trace. Réviser en bloc donne une impression de maîtrise, car tout est frais, mais cette impression est trompeuse : ce qui est appris vite s'oublie vite. Les applications de cartes mémoire reposent sur ce principe en programmant les révisions à des intervalles croissants. L'effet a été reproduit des centaines de fois, chez des enfants comme chez des adultes.",
   quiz:[["Qui a mis en évidence l'effet d'espacement ?",["Hermann Ebbinghaus","Anders Ericsson","Platon"],"Le texte cite les travaux d'Hermann Ebbinghaus, à la fin du XIXe siècle."],["Pourquoi réviser en bloc est-il trompeur ?",["Ça donne une impression de maîtrise qui ne dure pas","Ça fatigue trop le cerveau","Ça empêche de dormir"],"Tout est frais quand on révise en bloc : on se croit maître du sujet, mais « ce qui est appris vite s'oublie vite »."],["Que veut dire « espacé » dans « apprentissage espacé » ?",["Réparti en plusieurs séances séparées dans le temps","Fait dans une pièce vaste et calme","Interrompu par des pauses très longues dans une même séance"],"Le texte oppose trois heures d'affilée à trois fois une heure, à quelques jours d'intervalle."]],
   idees:["Étudier en plusieurs fois espacées l'emporte sur l'étude en bloc","L'effort de rappel juste avant l'oubli renforce la trace","L'étude en bloc donne une impression trompeuse de maîtrise"]},
  {id:'t03',th:"philo histoire",src:"Platon, Phèdre, 274c-275b",titre:"Socrate contre l'écriture",
   texte:"Dans le Phèdre, écrit par Platon vers 370 avant notre ère, Socrate raconte une légende égyptienne. Le dieu Theuth présente l'écriture au roi Thamous comme un remède pour la mémoire et la sagesse. Le roi refuse : selon lui, l'écriture produira l'oubli, car les hommes, se fiant aux signes extérieurs, cesseront d'exercer leur mémoire. Ils paraîtront savants sans l'être, ayant beaucoup lu sans avoir été instruits. L'argument fait sourire aujourd'hui, car l'écriture a démultiplié la pensée humaine. Mais il n'est pas absurde : toute technologie qui externalise une fonction mentale la transforme. La vraie question n'est pas de savoir si l'on doit utiliser l'outil, mais ce que l'on choisit de continuer à faire soi-même.",
   quiz:[["Dans quel dialogue de Platon se trouve cette légende ?",["Le Phèdre","La République","Le Banquet"],"Le texte : « Dans le Phèdre, écrit par Platon vers 370 avant notre ère »."],["Selon le roi Thamous, l'écriture va…",["produire l'oubli","rendre les hommes plus sages","remplacer les dieux"],"Le roi pense que les hommes, se fiant aux signes écrits, cesseront d'exercer leur mémoire."],["Que signifie ici « externaliser » une fonction mentale ?",["La confier à un outil hors de sa tête","L'exercer en plein air","L'oublier complètement"],"L'écriture confie la mémoire à des signes extérieurs : c'est le sens d'externaliser."]],
   idees:["Dans le Phèdre, le roi Thamous craint que l'écriture produise l'oubli","Toute technologie qui externalise une fonction mentale la transforme","La vraie question : ce que l'on choisit de continuer à faire soi-même"]},
  {id:'t04',th:"sciences philo",src:"Nickerson, Review of General Psychology, 1998",titre:"Le biais de confirmation",
   texte:"Nous ne cherchons pas l'information de façon neutre. Face à une question, nous avons tendance à remarquer, retenir et juger plus convaincants les éléments qui confirment ce que nous pensons déjà, et à ignorer ou minimiser ceux qui le contredisent. C'est le biais de confirmation. Il ne touche pas que les personnes peu instruites : des experts y sont sujets dans leur propre domaine. Il s'aggrave quand le sujet nous tient à cœur ou touche notre identité. Les moteurs de recherche et les assistants conversationnels peuvent l'amplifier, car la manière dont on formule la question oriente souvent la réponse. Un antidote simple consiste à chercher activement le meilleur argument contre sa propre position avant de conclure.",
   quiz:[["Quel antidote le texte propose-t-il ?",["Chercher le meilleur argument contre sa propre position","Lire plus de sources qui vont dans son sens","Demander l'avis d'un expert"],"Le texte : chercher activement le meilleur argument contre sa propre position avant de conclure."],["Quand ce biais s'aggrave-t-il ?",["Quand le sujet touche notre identité","Quand on lit sur papier","Quand on est fatigué"],"Le biais s'aggrave « quand le sujet nous tient à cœur ou touche notre identité »."],["Pourquoi un assistant conversationnel peut-il amplifier ce biais ?",["La façon de poser la question oriente la réponse","Il ment volontairement","Il ne connaît pas le sujet"],"Le texte : « la manière dont on formule la question oriente souvent la réponse »."]],
   idees:["On remarque et on croit davantage ce qui confirme nos idées","Il touche aussi les experts et s'aggrave quand notre identité est en jeu","Antidote : chercher le meilleur argument contre sa propre position"]},
  {id:'t05',th:"sciences",src:"Ophir, Nass et Wagner, PNAS, 2009",titre:"Le mythe du multitâche",
   texte:"Beaucoup de gens pensent bien gérer plusieurs tâches à la fois. Pour les tâches qui demandent de l'attention, le cerveau ne fait en réalité pas deux choses en même temps : il passe rapidement de l'une à l'autre. Chaque bascule a un coût. Il faut quelques instants pour se réengager, et une partie de l'attention reste accrochée à la tâche précédente. Résultat : on va moins vite et on fait plus d'erreurs que si l'on enchaînait les tâches une par une. Les notifications aggravent le problème, car elles provoquent des bascules non choisies. Plusieurs études suggèrent même que ceux qui pratiquent le plus le multitâche avec les médias se laissent davantage distraire par les informations sans importance.",
   quiz:[["Que fait le cerveau face à deux tâches qui demandent de l'attention ?",["Il bascule de l'une à l'autre","Il les traite en parallèle","Il en ignore une"],"Le cerveau « passe rapidement de l'une à l'autre », il ne fait pas deux choses en même temps."],["Qu'est-ce que les notifications aggravent ?",["Les bascules d'attention non choisies","La mémoire à long terme","La fatigue visuelle"],"Les notifications « provoquent des bascules non choisies »."],["Pourquoi enchaîner les tâches une par une est-il plus efficace ?",["On évite le coût de chaque bascule","On travaille plus longtemps","Le cerveau se repose entre deux tâches"],"Chaque bascule coûte du temps pour se réengager et laisse une part d'attention accrochée à la tâche précédente."]],
   idees:["Pour les tâches d'attention, le cerveau bascule au lieu de tout faire à la fois","Chaque bascule coûte du temps et des erreurs","Les notifications imposent des bascules non choisies"]},
  {id:'t06',th:"sciences sport",src:"Ericsson, Krampe et Tesch-Römer, Psychological Review, 1993 ; Macnamara et al., 2014",titre:"La pratique délibérée",
   texte:"Pourquoi certaines personnes progressent-elles pendant des années alors que d'autres stagnent malgré autant d'heures de pratique ? Le psychologue Anders Ericsson a proposé une réponse : ce n'est pas la quantité d'entraînement qui compte le plus, mais sa qualité. La pratique délibérée vise une faiblesse précise, se situe juste au-delà de ce que l'on sait faire, s'accompagne d'un retour immédiat et demande une concentration intense. Elle est donc inconfortable. Jouer pour le plaisir ou répéter ce que l'on maîtrise déjà fait peu progresser. Ce cadre a été discuté et nuancé depuis, notamment sur la part du talent, mais son message central reste utile : pour s'améliorer, il faut chercher la difficulté plutôt que l'éviter.",
   quiz:[["Qui a proposé la notion de pratique délibérée ?",["Anders Ericsson","Hermann Ebbinghaus","Daniel Kahneman"],"Le texte : « Le psychologue Anders Ericsson a proposé une réponse »."],["Quelle est l'une de ses caractéristiques ?",["Elle vise une faiblesse précise","Elle répète ce que l'on maîtrise déjà","Elle se fait sans retour extérieur"],"Elle « vise une faiblesse précise », avec un retour immédiat."],["Pourquoi la pratique délibérée est-elle « inconfortable » ?",["Elle se place juste au-delà de ce qu'on sait faire","Elle se pratique debout","Elle dure plusieurs heures sans pause"],"On travaille ses faiblesses, à la limite de ses capacités, avec une concentration intense : d'où l'inconfort."]],
   idees:["La qualité de l'entraînement compte plus que la quantité","Pratique délibérée : une faiblesse ciblée, juste au-delà de son niveau, avec retour immédiat","Un cadre nuancé depuis, mais chercher la difficulté reste utile"]},
  {id:'t07',th:"histoire lettres",vu:'2026-10-30',src:"Établissement public Rebâtir Notre-Dame de Paris ; Viollet-le-Duc, Dictionnaire raisonné (1854-1868)",titre:"Les bâtisseurs de Notre-Dame",
   texte:"La construction de Notre-Dame de Paris commence en 1163, à l'initiative de l'évêque Maurice de Sully. Le chantier dure près de deux siècles : plusieurs générations d'architectes, de tailleurs de pierre et de charpentiers se succèdent sans voir l'œuvre achevée. La charpente, faite de chênes abattus au Moyen Âge, est surnommée « la forêt ». Au XIXe siècle, après des décennies de dégradations, Viollet-le-Duc restaure l'édifice et ajoute la flèche, inspirée de l'ancienne. Le 15 avril 2019, un incendie détruit la charpente et la flèche. Charpentiers, tailleurs de pierre et verriers reprennent alors les gestes de leurs prédécesseurs, et la cathédrale rouvre le 7 décembre 2024, cinq ans plus tard. Le roman de Victor Hugo, publié en 1831, avait déjà contribué à sauver le monument de l'oubli.",
   quiz:[["Qui a ajouté la flèche détruite en 2019 ?",["Viollet-le-Duc","Maurice de Sully","Victor Hugo"],"Au XIXe siècle, Viollet-le-Duc « ajoute la flèche, inspirée de l'ancienne »."],["Pourquoi appelait-on la charpente « la forêt » ?",["Elle était faite d'une multitude de chênes","Elle était peinte en vert","Elle avait été montée dans un bois"],"La charpente était faite de chênes abattus au Moyen Âge, d'où le surnom."],["Combien de temps la cathédrale est-elle restée fermée après l'incendie ?",["Environ cinq ans","Deux siècles","Un an"],"De l'incendie du 15 avril 2019 à la réouverture du 7 décembre 2024 : « cinq ans plus tard »."]],
   idees:["Un chantier de près de deux siècles, commencé en 1163","Restaurée au XIXe siècle par Viollet-le-Duc, qui ajoute la flèche","Détruite en partie en 2019, rebâtie avec les gestes anciens et rouverte en 2024"]},
  {id:'t08',th:"sciences histoire",vu:'2026-10-30',src:"Institut Pasteur ; Patrice Debré, Louis Pasteur (1994)",titre:"Pasteur et la rage",
   texte:"Le 6 juillet 1885, une mère alsacienne arrive à Paris avec son fils, Joseph Meister, neuf ans, mordu par un chien enragé deux jours plus tôt. La rage, une fois déclarée, est alors toujours mortelle. Louis Pasteur, qui n'est pas médecin mais chimiste, travaille depuis des années sur un traitement testé sur des chiens. Après avoir consulté des médecins, il décide de tenter l'essai. Ce sont eux qui pratiquent les injections : une série de moelles de lapins infectés, desséchées de plus en plus brièvement, donc de plus en plus virulentes. L'enfant survit. Le succès, annoncé à l'Académie des sciences en octobre, fait le tour du monde et conduit à la fondation de l'Institut Pasteur en 1888. La décision reste discutée : le traitement n'avait jamais été essayé sur l'homme.",
   quiz:[["Quelle était la formation de Pasteur ?",["Chimiste","Médecin","Vétérinaire"],"Le texte : Pasteur « n'est pas médecin mais chimiste »."],["Qui a pratiqué les injections sur Joseph Meister ?",["Des médecins","Pasteur lui-même","Un vétérinaire alsacien"],"« Ce sont eux qui pratiquent les injections » : les médecins consultés."],["Pourquoi la décision de Pasteur « reste discutée » ?",["Le traitement n'avait jamais été essayé sur l'homme","L'enfant n'a pas survécu","Pasteur a agi sans consulter personne"],"Dernière phrase du texte : « le traitement n'avait jamais été essayé sur l'homme »."]],
   idees:["La rage déclarée était toujours mortelle","Pasteur, chimiste, tente avec des médecins un traitement jamais essayé sur l'homme","Le succès mène à l'Institut Pasteur, mais la décision reste discutée"]},
  {id:'t09',th:"sciences",vu:'2026-10-30',src:"Roediger et Karpicke, Psychological Science, 2006",titre:"Se tester pour retenir",
   texte:"Pour apprendre un texte, vaut-il mieux le relire ou essayer de le réciter ? En 2006, les psychologues Henry Roediger et Jeffrey Karpicke ont posé la question à des étudiants. Les uns relisaient plusieurs fois un passage, les autres le lisaient puis s'efforçaient d'écrire de mémoire tout ce qu'ils en retenaient. Cinq minutes après, les relecteurs s'en sortaient un peu mieux. Mais une semaine plus tard, ceux qui s'étaient testés retenaient nettement davantage. Se rappeler une information renforce la trace en mémoire, alors que relire donne surtout une impression de familiarité. C'est l'effet de test, l'un des résultats les plus solides de la psychologie de l'apprentissage. Il explique pourquoi les fiches, les questions et les exercices valent mieux que le surlignage.",
   quiz:[["Qui s'en sortait le mieux une semaine plus tard ?",["Ceux qui s'étaient testés","Ceux qui avaient relu","Les deux groupes à égalité"],"Une semaine plus tard, « ceux qui s'étaient testés retenaient nettement davantage »."],["Que donne surtout la relecture, selon le texte ?",["Une impression de familiarité","Une mémoire durable","Une meilleure compréhension"],"Le texte : « relire donne surtout une impression de familiarité »."],["Que nomme-t-on « l'effet de test » ?",["Se rappeler une information la fixe mieux que la relire","Les examens rendent anxieux","On réussit mieux quand on connaît les questions"],"Se rappeler renforce la trace en mémoire : c'est l'effet de test."]],
   idees:["Se tester bat la relecture à une semaine, même si la relecture gagne à cinq minutes","Le rappel renforce la trace, la relecture donne une illusion de familiarité","D'où l'intérêt des questions et exercices plutôt que du surlignage"]},
  {id:'t10',th:"histoire philo",vu:'2026-10-30',src:"Règle de saint Benoît, prologue et ch. 2, 58, 64",titre:"La Règle de saint Benoît",
   texte:"Vers 530, Benoît de Nursie fonde un monastère au mont Cassin, en Italie, et rédige une règle pour ses moines. En soixante-treize chapitres courts, elle organise toute la journée : la prière à heures fixes, le travail manuel, la lecture. Elle se veut une « école du service du Seigneur » où l'on ne prescrit « rien de dur, rien de pesant ». L'abbé doit s'adapter à chacun, encourager les faibles sans décourager les forts. La règle impose aussi la stabilité : le moine s'engage à rester dans sa communauté. Sa mesure explique son succès. Elle est adoptée par des milliers de monastères en Europe, qui deviennent pendant des siècles des lieux de culture, d'agriculture et de copie des livres. La devise qu'on lui associera plus tard, ora et labora, ne figure pas dans le texte.",
   quiz:[["Qu'impose la stabilité ?",["Rester dans sa communauté","Prier à heures fixes","Travailler la terre"],"Le moine « s'engage à rester dans sa communauté »."],["D'où vient la devise ora et labora ?",["On l'a associée plus tard à la Règle","Elle ouvre la Règle","Elle est gravée au mont Cassin depuis 530"],"Le texte : la devise qu'on lui associera plus tard « ne figure pas dans le texte »."],["Que veut dire ici la « mesure » de la Règle ?",["Sa modération : rien de trop dur","Sa longueur exacte","Les horaires qu'elle fixe"],"La Règle ne prescrit « rien de dur, rien de pesant » et l'abbé s'adapte à chacun : c'est sa mesure."]],
   idees:["Une règle écrite vers 530 qui organise prière, travail et lecture","Une règle mesurée : l'abbé s'adapte à chacun, rien de trop dur","Adoptée par des milliers de monastères, foyers de culture en Europe"]},
  {id:'t11',th:"philo lettres",vu:'2026-10-30',src:"Descartes, Discours de la méthode, 1637, 1re et 2e parties",titre:"Le Discours de la méthode",
   texte:"En 1637, René Descartes publie à Leyde le Discours de la méthode. Fait rare pour un savant de son temps, il écrit en français et non en latin, pour être lu par tous ceux qui ont du bon sens. Il y raconte comment, déçu par ce qu'il avait appris au collège, il a décidé de tout reprendre à zéro. Il se donne quatre règles : ne tenir pour vrai que ce qui est évident, diviser chaque difficulté en autant de parties qu'il faut, avancer du plus simple au plus complexe, et faire des revues si complètes qu'on soit sûr de ne rien omettre. C'est dans ce livre qu'apparaît la formule « je pense, donc je suis » : la seule certitude qui résiste au doute. Le Discours servait de préface à trois essais scientifiques, dont la Géométrie.",
   quiz:[["Pourquoi Descartes écrit-il en français ?",["Pour être lu par tous ceux qui ont du bon sens","Parce qu'il ne savait pas le latin","Pour obéir au roi"],"Il écrit en français « pour être lu par tous ceux qui ont du bon sens »."],["Laquelle est l'une de ses quatre règles ?",["Diviser chaque difficulté en parties","Toujours suivre les autorités","Commencer par le plus complexe"],"Deuxième règle : « diviser chaque difficulté en autant de parties qu'il faut »."],["Que veut dire « je pense, donc je suis » dans ce texte ?",["C'est la seule certitude qui résiste au doute","Il faut beaucoup penser pour exister","Les animaux ne pensent pas"],"Le texte : « la seule certitude qui résiste au doute »."]],
   idees:["Un livre de 1637 écrit en français pour tous","Quatre règles : évidence, division, ordre, revue complète","« Je pense, donc je suis » : la certitude qui résiste au doute"]},
  {id:'t12',th:"eco",vu:'2026-10-30',src:"Calcul : 1 000 × 1,05^10 ≈ 1 629 ; 1 000 × 1,05^30 ≈ 4 322",titre:"La force des intérêts composés",
   texte:"Place 1 000 euros à 5 % par an. La première année, tu gagnes 50 euros. La deuxième, les intérêts portent sur 1 050 euros : tu gagnes 52,50 euros. Chaque année, les intérêts produisent à leur tour des intérêts. Au bout de dix ans, le capital atteint environ 1 629 euros ; au bout de trente ans, environ 4 322 euros, soit plus de quatre fois la mise. Une règle simple permet d'estimer le temps de doublement : diviser 72 par le taux. À 5 %, il faut un peu plus de quatorze ans. Le même mécanisme joue contre l'emprunteur : une dette à taux élevé qu'on ne rembourse pas grossit de plus en plus vite. Et l'inflation, qui ronge chaque année la valeur de l'argent, est elle aussi un taux composé.",
   quiz:[["Combien vaut le capital après trente ans, environ ?",["4 322 euros","2 500 euros","1 629 euros"],"Au bout de trente ans, « environ 4 322 euros, soit plus de quatre fois la mise »."],["Comment estimer le temps de doublement ?",["Diviser 72 par le taux","Multiplier le taux par 10","Diviser 100 par le taux"],"Règle de 72 : à 5 %, 72 ÷ 5 donne un peu plus de quatorze ans."],["Pourquoi le gain de la deuxième année est-il plus grand que celui de la première ?",["Les intérêts portent aussi sur les intérêts déjà gagnés","Le taux augmente chaque année","La banque ajoute une prime"],"La deuxième année, les intérêts portent sur 1 050 euros : 52,50 euros au lieu de 50."]],
   idees:["Les intérêts produisent eux-mêmes des intérêts, d'où une croissance accélérée","La règle de 72 estime le temps de doublement","Le mécanisme joue aussi contre l'emprunteur et avec l'inflation"]},
  {id:'t13',th:"sciences nature",vu:'2026-10-30',src:"Wegener, Die Entstehung der Kontinente und Ozeane, 1915 ; Vine et Matthews, Nature, 1963",titre:"Wegener et la dérive des continents",
   texte:"En 1912, le météorologue allemand Alfred Wegener remarque que les côtes de l'Amérique du Sud et de l'Afrique s'emboîtent comme les pièces d'un puzzle. Il relève aussi des fossiles identiques de part et d'autre de l'Atlantique et des roches de même âge. Il en conclut que les continents formaient autrefois un seul bloc, la Pangée, et qu'ils ont dérivé. La plupart des géologues rejettent l'idée : Wegener ne sait pas expliquer quelle force pourrait déplacer des continents. Il meurt en 1930 au Groenland. Dans les années 1960, l'étude des fonds marins montre que la croûte océanique se forme le long des dorsales et s'écarte de part et d'autre. La tectonique des plaques est née. L'Atlantique s'élargit encore aujourd'hui de quelques centimètres par an.",
   quiz:[["Pourquoi l'idée de Wegener fut-elle d'abord rejetée ?",["Il ne savait pas expliquer quelle force déplaçait les continents","Ses fossiles étaient des faux","Les côtes ne s'emboîtaient pas vraiment"],"Les géologues rejettent l'idée car Wegener « ne sait pas expliquer quelle force » déplace les continents."],["Qu'est-ce qui a confirmé la dérive dans les années 1960 ?",["L'étude des fonds marins","Les satellites","Un séisme au Groenland"],"Dans les années 1960, l'étude des fonds marins montre la croûte qui se forme le long des dorsales."],["Quels indices Wegener avait-il réunis ?",["Des côtes qui s'emboîtent, des fossiles et des roches identiques","Des mesures par satellite","Des récits de marins"],"Le texte cite les côtes en puzzle, des fossiles identiques et des roches de même âge."]],
   idees:["Wegener propose en 1912 la dérive des continents à partir d'indices concordants","Rejetée faute de mécanisme","Confirmée dans les années 1960 par l'étude des fonds marins"]},
  {id:'t14',th:"histoire",vu:'2026-10-30',src:"Régine Pernoud, Jeanne d'Arc par elle-même et par ses témoins (1962)",titre:"Jeanne d'Arc",
   texte:"Jeanne naît vers 1412 à Domrémy, aux confins de la Lorraine, pendant la guerre de Cent Ans. Elle dit entendre des voix qui lui demandent de libérer le royaume. En 1429, à dix-sept ans environ, elle obtient de rencontrer le dauphin Charles à Chinon. Le 8 mai, l'armée qu'elle accompagne lève le siège d'Orléans. Le 17 juillet, Charles est sacré à Reims, ce qui renforce sa légitimité. Capturée à Compiègne en 1430 par les Bourguignons, elle est livrée aux Anglais, jugée à Rouen par un tribunal d'Église favorable à l'Angleterre, et brûlée vive le 30 mai 1431. Un procès en nullité, ouvert à la demande de sa mère, l'annule en 1456. Jeanne est canonisée en 1920 et devient l'une des deux saintes patronnes secondaires de la France.",
   quiz:[["Quel événement suit la levée du siège d'Orléans ?",["Le sacre de Charles à Reims","La capture de Jeanne à Rouen","La fin de la guerre de Cent Ans"],"Le siège d'Orléans est levé le 8 mai, le sacre a lieu le 17 juillet 1429."],["Que se passe-t-il en 1456 ?",["Sa condamnation est annulée","Elle est canonisée","Elle rencontre le dauphin"],"Le procès en nullité, ouvert à la demande de sa mère, annule la condamnation en 1456."],["Pourquoi le sacre de Reims compte-t-il tant ?",["Il renforce la légitimité de Charles","Il met fin à la guerre","Il libère Orléans"],"Le texte : Charles est sacré à Reims, « ce qui renforce sa légitimité »."]],
   idees:["En 1429, Jeanne fait lever le siège d'Orléans et conduit Charles au sacre de Reims","Capturée, jugée à Rouen et brûlée en 1431","Réhabilitée en 1456, canonisée en 1920"]},
  {id:'t15',th:"sciences sport",vu:'2026-10-30',src:"Erickson et al., PNAS, 2011",titre:"Marcher pour son cerveau",
   texte:"L'hippocampe, une structure du cerveau essentielle à la mémoire, rétrécit avec l'âge, d'environ 1 à 2 % par an après soixante ans. En 2011, l'équipe de Kirk Erickson a suivi 120 adultes âgés pendant un an. La moitié marchait d'un bon pas quarante minutes, trois fois par semaine ; l'autre moitié faisait des étirements. Dans le groupe de marche, le volume de l'hippocampe a augmenté d'environ 2 %, alors qu'il continuait à diminuer chez les autres. Chez eux, ce gain allait de pair avec de meilleurs résultats de mémoire spatiale. L'étude ne dit pas que la marche rend intelligent, et d'autres travaux sont plus nuancés. Mais elle montre que le cerveau reste modifiable tard dans la vie, et que l'exercice d'endurance en fait partie.",
   quiz:[["Que faisait le groupe témoin ?",["Des étirements","Rien du tout","De la musculation"],"L'autre moitié du groupe « faisait des étirements »."],["Que conclut prudemment le texte ?",["Le cerveau reste modifiable tard dans la vie","La marche rend intelligent","L'hippocampe ne rétrécit plus après soixante ans"],"Le texte conclut que le cerveau « reste modifiable tard dans la vie »."],["Pourquoi le texte dit-il que l'étude « ne dit pas que la marche rend intelligent » ?",["Elle mesure un effet précis, et d'autres travaux sont plus nuancés","Les marcheurs ont perdu la mémoire","L'étude a été retirée"],"On a mesuré l'hippocampe et la mémoire spatiale, pas l'intelligence ; et d'autres travaux sont « plus nuancés »."]],
   idees:["L'hippocampe rétrécit avec l'âge","Un an de marche régulière l'a fait grossir d'environ 2 % dans une étude contrôlée","Le cerveau reste modifiable, sans que la marche rende « intelligent »"]},
  {id:'t16',th:"lettres",vu:'2026-10-30',src:"La Fontaine, Fables, 1668, dédicace et préface ; livre I, fable 10",titre:"Les Fables de La Fontaine",
   texte:"En 1668, Jean de La Fontaine publie un premier recueil de fables, dédié au Dauphin, le fils de Louis XIV, alors âgé de six ans. Il reprend des sujets très anciens, venus surtout du Grec Ésope et du Latin Phèdre, mais il les transforme : là où Ésope racontait en quelques lignes, La Fontaine fait de petites comédies en vers, avec des personnages, des dialogues et un rythme vif. La morale n'est pas toujours où on l'attend. Dans « Le Loup et l'Agneau », elle annonce cyniquement que « la raison du plus fort est toujours la meilleure » ; la fable montre en réalité l'injustice de cette loi. La Fontaine disait se servir d'animaux pour instruire les hommes. Les écoliers apprennent encore ses vers par cœur, ce qui en fait sans doute le poète le plus récité de France.",
   quiz:[["D'où viennent surtout les sujets des fables ?",["D'Ésope et de Phèdre","De la Bible","Des contes de Perrault"],"Il reprend des sujets « venus surtout du Grec Ésope et du Latin Phèdre »."],["Que montre en réalité « Le Loup et l'Agneau » ?",["L'injustice de la loi du plus fort","Que le plus fort a raison","Qu'il faut se méfier des agneaux"],"Le texte : la fable « montre en réalité l'injustice de cette loi »."],["Que veut dire « cyniquement », pour la morale du Loup et l'Agneau ?",["En affichant sans honte une idée choquante","Avec tristesse","En plaisantant gentiment"],"Cynique : qui dit sans honte une chose contraire à la morale. La fable, elle, en montre l'injustice."]],
   idees:["Premier recueil en 1668, dédié au Dauphin","Des sujets anciens d'Ésope et Phèdre transformés en petites comédies en vers","Une morale parfois ironique : la fable instruit les hommes par les animaux"]},
  {id:'t17',th:"sciences philo",vu:'2026-10-30',src:"Kruger et Dunning, Journal of Personality and Social Psychology, 1999 ; Nuhfer et al., Numeracy, 2016",titre:"Ceux qui ne savent pas qu'ils ne savent pas",
   texte:"En 1999, les psychologues David Dunning et Justin Kruger font passer à des étudiants de Cornell des tests de logique, de grammaire et d'humour, puis leur demandent d'estimer leur rang. Ceux qui ont les plus mauvais scores se surestiment fortement : en logique, le quart le plus faible, en moyenne au 12e rang sur 100, se croit au-dessus de la moyenne. Les auteurs avancent une explication : les compétences qui permettent de réussir sont aussi celles qui permettent de voir qu'on a échoué. L'effet a depuis été très popularisé, souvent de façon exagérée. Des chercheurs ont montré qu'une partie du phénomène vient d'un simple effet statistique, et que presque tout le monde a du mal à juger son propre niveau. Le remède reste le même : se confronter à des corrections précises.",
   quiz:[["Selon les auteurs, pourquoi les moins compétents se surestiment-ils ?",["Il faut des compétences pour voir qu'on a échoué","Ils sont plus orgueilleux","Ils n'ont pas compris la consigne"],"Le texte : « les compétences qui permettent de réussir sont aussi celles qui permettent de voir qu'on a échoué »."],["Quelle nuance le texte apporte-t-il ?",["Une partie de l'effet vient d'un artefact statistique","L'effet n'a jamais été reproduit","Il ne touche que les étudiants"],"Une partie du phénomène vient « d'un simple effet statistique »."],["Quel remède le texte propose-t-il ?",["Se confronter à des corrections précises","Éviter les tests","Se comparer aux plus faibles"],"Dernière phrase : « se confronter à des corrections précises »."]],
   idees:["Les moins performants se surestiment le plus dans l'étude de 1999","Explication : il faut de la compétence pour voir son échec","Effet exagéré dans sa version populaire ; le remède reste la correction précise"]},
  {id:'t18',th:"histoire sciences",vu:'2026-10-30',src:"Bureau international des poids et mesures ; Ken Alder, Mesurer le monde (2005)",titre:"La naissance du mètre",
   texte:"Avant la Révolution, la France compte des centaines d'unités de mesure différentes : l'aune, la toise ou le pied changent d'une province à l'autre, ce qui favorise les fraudes. En 1791, l'Assemblée décide d'une unité tirée de la nature : le mètre sera la dix-millionième partie de la distance du pôle Nord à l'équateur. Deux astronomes, Delambre et Méchain, mesurent de 1792 à 1798 la distance entre Dunkerque et Barcelone, au milieu des troubles de la Révolution. Le système métrique est adopté, mais il faudra attendre 1840 pour qu'il devienne obligatoire en France. Il s'étend ensuite au monde presque entier. Depuis 1983, le mètre est défini par la vitesse de la lumière : la distance qu'elle parcourt dans le vide en 1/299 792 458 de seconde.",
   quiz:[["Quelle distance Delambre et Méchain ont-ils mesurée ?",["Dunkerque–Barcelone","Paris–Marseille","Le tour de la Terre"],"Delambre et Méchain mesurent de 1792 à 1798 la distance entre Dunkerque et Barcelone."],["Comment le mètre est-il défini depuis 1983 ?",["Par la vitesse de la lumière","Par une barre de platine","Par la longueur d'un pendule"],"Depuis 1983, le mètre est la distance parcourue par la lumière en 1/299 792 458 de seconde."],["Pourquoi tant d'unités différentes posaient-elles problème avant la Révolution ?",["Elles changeaient d'une province à l'autre et favorisaient les fraudes","Elles étaient trop précises","Elles venaient d'Angleterre"],"Le texte : l'aune, la toise ou le pied « changent d'une province à l'autre, ce qui favorise les fraudes »."]],
   idees:["Une multitude d'unités locales favorisait les fraudes","Le mètre, tiré du méridien, mesuré entre Dunkerque et Barcelone","Obligatoire en 1840, défini par la lumière depuis 1983"]},
  {id:'t19',th:"sciences",vu:'2026-10-30',src:"Maguire et al., PNAS, 2000 ; Woollett et Maguire, Current Biology, 2011",titre:"Le cerveau des chauffeurs de taxi",
   texte:"Pour obtenir leur licence, les chauffeurs de taxi londoniens doivent apprendre « le Savoir » : environ 25 000 rues et des milliers de lieux, ce qui demande souvent trois à quatre ans. En 2000, la neurologue Eleanor Maguire compare leur cerveau à celui d'autres hommes. La partie arrière de leur hippocampe, impliquée dans la navigation, est plus volumineuse, et d'autant plus qu'ils exercent depuis longtemps. Une étude ultérieure suit des apprentis : chez ceux qui réussissent l'examen, cette zone grossit pendant l'apprentissage. Chez ceux qui échouent ou abandonnent, non. Le cerveau adulte se modifie donc avec l'usage. La question se pose à l'envers depuis que l'on suit un GPS : ce qu'on ne fait plus soi-même, le cerveau cesse peut-être de l'entretenir.",
   quiz:[["Quelle partie de l'hippocampe est plus volumineuse chez eux ?",["La partie arrière","La partie avant","Aucune, c'est le cortex"],"La partie arrière de l'hippocampe, impliquée dans la navigation, est plus volumineuse."],["Que montre l'étude des apprentis ?",["La zone grossit chez ceux qui réussissent l'examen","Tous les apprentis ont un gros hippocampe dès le départ","Le GPS fait grossir l'hippocampe"],"Chez ceux qui réussissent, la zone grossit ; chez ceux qui échouent ou abandonnent, non."],["Quelle inquiétude le texte tire-t-il de ces études pour nous ?",["Ce qu'on confie au GPS, le cerveau cesse peut-être de l'entretenir","Le GPS abîme les yeux","Les chauffeurs de taxi vont disparaître"],"Dernière phrase : « ce qu'on ne fait plus soi-même, le cerveau cesse peut-être de l'entretenir »."]],
   idees:["Apprendre la carte de Londres prend des années","L'hippocampe arrière des chauffeurs grossit avec l'apprentissage","Le cerveau se modifie avec l'usage, ce qui interroge notre dépendance au GPS"]},
  {id:'t20',th:"philo",vu:'2026-10-30',src:"Pascal, Pensées, fragment « Infini rien » (Lafuma 418, Sellier 680)",titre:"Le pari de Pascal",
   texte:"Blaise Pascal meurt en 1662 en laissant des centaines de fragments destinés à une apologie de la religion chrétienne. Ses proches les publient en 1670 sous le titre de Pensées. L'un des plus célèbres est le « pari ». Pascal s'adresse à un libertin qui dit ne pas pouvoir prouver l'existence de Dieu. Soit, répond-il, mais il faut choisir : « vous êtes embarqué ». Si l'on parie que Dieu existe et que c'est vrai, on gagne un bonheur infini ; si c'est faux, on perd peu. Si l'on parie contre et que Dieu existe, on perd tout. Le raisonnement compare des gains et leurs chances, comme on le fera en théorie des décisions. Pascal ne prétend pas qu'il suffise de calculer pour croire : il invite surtout l'incrédule à chercher.",
   quiz:[["Quand les Pensées ont-elles été publiées ?",["En 1670, après la mort de Pascal","En 1662, par Pascal lui-même","Au XIXe siècle"],"Pascal meurt en 1662, ses proches publient les fragments en 1670."],["À qui Pascal adresse-t-il le pari ?",["À un libertin qui ne peut pas prouver Dieu","À un évêque","À son ami Descartes"],"Il s'adresse « à un libertin qui dit ne pas pouvoir prouver l'existence de Dieu »."],["Que veut dire « vous êtes embarqué » ?",["On ne peut pas éviter de choisir","On part en voyage","On a déjà perdu"],"Pascal répond qu'« il faut choisir » : ne pas parier, c'est déjà parier contre."]],
   idees:["Les Pensées, fragments publiés après la mort de Pascal","Le pari : on ne peut pas ne pas choisir, et l'on compare gains et chances","Pas une preuve de Dieu mais une invitation à chercher"]},
  {id:'ws1',th:"lettres",vu:'2026-11-02',src:"Gustave Flaubert, « Un cœur simple », Trois Contes (1877), chapitre I (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Trois_Contes_(Flaubert)/Un_C%C5%93ur_simple",titre:"Félicité, un cœur simple",
   texte:"Pendant un demi-siècle, les bourgeoises de Pont-l'Évêque envièrent à Mme Aubain sa servante Félicité. Pour cent francs par an, elle faisait la cuisine et le ménage, cousait, lavait, repassait, savait brider un cheval, engraisser les volailles, battre le beurre, et resta fidèle à sa maîtresse, — qui cependant n'était pas une personne agréable. […] Elle se levait dès l'aube, pour ne pas manquer la messe, et travaillait jusqu'au soir sans interruption ; puis le dîner étant fini, la vaisselle en ordre et la porte bien close, elle enfouissait la bûche sous les cendres et s'endormait devant l'âtre, son rosaire à la main. Personne, dans les marchandages, ne montrait plus d'entêtement. Quant à la propreté, le poli de ses casseroles faisait le désespoir des autres servantes. Économe, elle mangeait avec lenteur, et recueillait du doigt sur la table les miettes de son pain, — un pain de douze livres, cuit exprès pour elle, et qui durait vingt jours.",
   quiz:[["Combien Félicité gagnait-elle ?",["Cent francs par an","Cent francs par mois","Rien : elle était seulement logée et nourrie"],"Le texte : « Pour cent francs par an, elle faisait la cuisine et le ménage »."],["Combien de temps durait son pain ?",["Vingt jours","Une semaine","Deux jours"],"Un pain de douze livres, cuit exprès pour elle, « qui durait vingt jours »."],["Que veut dire « économe », à propos de Félicité ?",["Qui ne gaspille rien","Qui tient les comptes de la maison","Qui mange peu par maladie"],"Elle ramasse du doigt les miettes de son pain : elle ne perd rien."]],
   idees:["Pendant cinquante ans, Félicité sert Mme Aubain pour cent francs par an","Elle fait tout et reste fidèle à une maîtresse peu agréable","Une vie pieuse, laborieuse et économe, réglée de l'aube au soir"]},
  {id:'ws2',th:"lettres nature",sem:'bretagne',vu:'2026-11-02',src:"Chateaubriand, Mémoires d'outre-tombe, première partie, livre III (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/M%C3%A9moires_d%E2%80%99outre-tombe/Premi%C3%A8re_partie/Livre_III",titre:"La grive de Montboissier",
   texte:"Je fus tiré de mes réflexions par le gazouillement d'une grive perchée sur la plus haute branche d'un bouleau. À l'instant, ce son magique fit reparaître à mes yeux le domaine paternel ; j'oubliai les catastrophes dont je venais d'être le témoin, et, transporté subitement dans le passé, je revis ces campagnes où j'entendis si souvent siffler la grive. Quand je l'écoutais alors, j'étais triste de même qu'aujourd'hui ; mais cette première tristesse était celle qui naît d'un désir vague de bonheur, lorsqu'on est sans expérience ; la tristesse que j'éprouve actuellement vient de la connaissance des choses appréciées et jugées. Le chant de l'oiseau dans les bois de Combourg m'entretenait d'une félicité que je croyais atteindre ; le même chant dans le parc de Montboissier me rappelait des jours perdus à la poursuite de cette félicité insaisissable.",
   quiz:[["Quel oiseau tire l'auteur de ses réflexions ?",["Une grive","Un rossignol","Une alouette"],"Le gazouillement « d'une grive perchée sur la plus haute branche d'un bouleau »."],["Où entendait-il ce chant dans sa jeunesse ?",["Dans les bois de Combourg","Dans le parc de Montboissier","Dans les jardins de Paris"],"Le chant de l'oiseau « dans les bois de Combourg » parlait d'une félicité qu'il croyait atteindre."],["Quelle différence l'auteur fait-il entre ses deux tristesses ?",["Jeune, il désirait un bonheur vague ; aujourd'hui il sait ce que valent les choses","Jeune, il était plus malheureux qu'aujourd'hui","Elles sont identiques"],"La première tristesse naît « d'un désir vague de bonheur », la seconde « de la connaissance des choses appréciées et jugées »."]],
   idees:["Le chant d'une grive fait revivre à l'auteur le domaine de son enfance","La tristesse de la jeunesse naissait d'un désir vague de bonheur","Celle d'aujourd'hui vient de l'expérience : le bonheur poursuivi s'est révélé insaisissable"]},
  {id:'ws3',th:"lettres histoire",vu:'2026-11-02',src:"Alphonse Daudet, « La dernière classe », Contes du lundi (1873) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Les_Contes_du_lundi/La_Derni%C3%A8re_classe",titre:"La dernière classe",
   texte:"« Je ne te gronderai pas, mon petit Franz, tu dois être assez puni… Voilà ce que c'est. Tous les jours on se dit : Bah ! j'ai bien le temps. J'apprendrai demain. Et puis tu vois ce qui arrive… Ah ! ç'a été le grand malheur de notre Alsace de toujours remettre son instruction à demain. Maintenant ces gens-là sont en droit de nous dire : Comment ! Vous prétendiez être Français, et vous ne savez ni parler ni écrire votre langue !… Dans tout ça, mon pauvre Franz, ce n'est pas encore toi le plus coupable. Nous avons tous notre bonne part de reproches à nous faire. « Vos parents n'ont pas assez tenu à vous voir instruits. Ils aimaient mieux vous envoyer travailler à la terre ou aux filatures pour avoir quelques sous de plus. Moi-même, n'ai-je rien à me reprocher ? Est-ce que je ne vous ai pas souvent fait arroser mon jardin au lieu de travailler ? Et quand je voulais aller pêcher des truites, est-ce que je me gênais pour vous donner congé ?… »",
   quiz:[["Selon M. Hamel, quel a été le grand malheur de l'Alsace ?",["Toujours remettre son instruction à demain","Manquer de maîtres d'école","Parler deux langues"],"M. Hamel : « ç'a été le grand malheur de notre Alsace de toujours remettre son instruction à demain »."],["Que se reproche M. Hamel lui-même ?",["D'avoir fait arroser son jardin et donné congé pour aller pêcher","D'avoir été trop sévère","D'avoir enseigné l'allemand"],"Il avoue avoir fait arroser son jardin et donné congé pour aller pêcher des truites."],["Que veut dire M. Hamel en disant que Franz est « assez puni » ?",["La situation elle-même est une punition suffisante","Franz a déjà été puni par ses parents","Franz est resté au coin toute la matinée"],"C'est la dernière classe de français : Franz ne pourra plus rattraper ce qu'il n'a pas appris."]],
   idees:["M. Hamel ne gronde pas Franz : la leçon est déjà assez dure","Le malheur de l'Alsace : toujours remettre l'instruction à demain","Chacun a sa part de faute : les parents, et le maître lui-même"]},
  {id:'ws4',th:"lettres nature",vu:'2026-11-02',src:"Alphonse Daudet, « La chèvre de M. Seguin », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/La_ch%C3%A8vre_de_monsieur_Seguin",titre:"La chèvre de M. Seguin",
   texte:"La chèvre se trouvait très heureuse et broutait l'herbe de si bon cœur que M. Seguin était ravi. — Enfin, pensait le pauvre homme, en voilà une qui ne s'ennuiera pas chez moi ! M. Seguin se trompait, sa chèvre s'ennuya. Un jour, elle se dit en regardant la montagne : — Comme on doit être bien là-haut ! Quel plaisir de gambader dans la bruyère, sans cette maudite longe qui vous écorche le cou !… C'est bon pour l'âne ou pour le bœuf de brouter dans un clos !… Les chèvres, il leur faut du large. À partir de ce moment, l'herbe du clos lui parut fade. L'ennui lui vint. Elle maigrit, son lait se fit rare. C'était pitié de la voir tirer tout le jour sur sa longe, la tête tournée du côté de la montagne, la narine ouverte, en faisant Mê !… tristement.",
   quiz:[["Qu'est-ce qui pèse à la chèvre dans le clos ?",["La longe qui l'attache et lui écorche le cou","Le manque d'herbe","La peur du loup"],"Elle rêve de gambader « sans cette maudite longe qui vous écorche le cou »."],["Comment son ennui se voit-il ?",["Elle maigrit et donne moins de lait","Elle casse sa corde","Elle refuse de se laisser traire"],"Le texte : « Elle maigrit, son lait se fit rare »."],["Que signifie « fade », dans « l'herbe du clos lui parut fade » ?",["Sans goût","Trop sèche","Empoisonnée"],"Fade : sans saveur. L'herbe n'a pas changé, c'est l'ennui qui lui ôte son goût."]],
   idees:["La chèvre, d'abord heureuse, finit par s'ennuyer dans le clos","Elle rêve de la montagne et de liberté, sans longe","L'ennui la ronge : elle maigrit et tire sur sa corde en regardant la montagne"]},
  {id:'ws5',th:"lettres histoire",vu:'2026-11-02',src:"Victor Hugo, « Après la bataille », La Légende des siècles (1859) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/La_L%C3%A9gende_des_si%C3%A8cles/Apr%C3%A8s_la_bataille",titre:"Après la bataille",
   texte:"Mon père, ce héros au sourire si doux,\nSuivi d'un seul housard qu'il aimait entre tous\nPour sa grande bravoure et pour sa haute taille,\nParcourait à cheval, le soir d'une bataille,\nLe champ couvert de morts sur qui tombait la nuit.\nIl lui sembla dans l'ombre entendre un faible bruit.\nC'était un Espagnol de l'armée en déroute\nQui se traînait sanglant sur le bord de la route,\nRâlant, brisé, livide, et mort plus qu'à moitié,\nEt qui disait : « À boire ! à boire par pitié ! »\nMon père, ému, tendit à son housard fidèle\nUne gourde de rhum qui pendait à sa selle,\nEt dit : « Tiens, donne à boire à ce pauvre blessé. »\nTout à coup, au moment où le housard baissé\nSe penchait vers lui, l'homme, une espèce de maure,\nSaisit un pistolet qu'il étreignait encore,\nEt vise au front mon père en criant : « Caramba ! »\nLe coup passa si près, que le chapeau tomba\nEt que le cheval fit un écart en arrière.\n« Donne-lui tout de même à boire, » dit mon père.",
   quiz:[["Que demande le blessé espagnol ?",["À boire","Qu'on le laisse mourir","Qu'on appelle un médecin"],"Le blessé disait : « À boire ! à boire par pitié ! »"],["Que fait le père après le coup de pistolet ?",["Il ordonne de lui donner quand même à boire","Il fait arrêter le blessé","Il riposte et le tue"],"Le père répond : « Donne-lui tout de même à boire »."],["Qu'est-ce qu'un « housard » ?",["Un soldat de cavalerie légère","Un médecin militaire","Un domestique de ferme"],"Housard (hussard) : cavalier de la cavalerie légère. Le texte le montre à cheval avec le père."]],
   idees:["Le soir d'une bataille, un officier et son housard trouvent un ennemi blessé qui demande à boire","Au moment d'être secouru, le blessé tire sur l'officier et le manque de peu","L'officier répond par la générosité : « Donne-lui tout de même à boire »"]},
  {id:"ws6",th:"lettres",vu:"2026-11-04",src:"Victor Hugo, Les Misérables, t. II « Cosette », livre III, chapitre 5 (1862) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Les_Mis%C3%A9rables/Tome_2/Livre_3/05",titre:"Cosette au bout du village",
   texte:"Cosette traversa ainsi le labyrinthe de rues tortueuses et désertes qui terminent du côté de Chelles le village de Montfermeil. Tant qu'elle eut des maisons et même seulement des murs des deux côtés de son chemin, elle alla assez hardiment. De temps en temps, elle voyait le rayonnement d'une chandelle à travers la fente d'un volet, c'était de la lumière et de la vie, il y avait là des gens, cela la rassurait. Cependant, à mesure qu'elle avançait, sa marche se ralentissait comme machinalement. Quand elle eut passé l'angle de la dernière maison, Cosette s'arrêta. Aller au delà de la dernière boutique avait été difficile ; aller plus loin que la dernière maison, cela devenait impossible. Elle posa le seau à terre, plongea sa main dans ses cheveux et se mit à se gratter lentement la tête, geste propre aux enfants terrifiés et indécis.",
   quiz:[["Qu'est-ce qui rassure Cosette tant qu'elle est dans le village ?",["La lumière des chandelles derrière les volets","Le bruit de ses pas","La présence de son chien"],"La lumière d'une chandelle par la fente d'un volet : « il y avait là des gens, cela la rassurait »."],["Que fait-elle en s'arrêtant après la dernière maison ?",["Elle pose le seau et se gratte la tête","Elle se met à chanter","Elle appelle au secours"],"Elle « posa le seau à terre » et se gratta lentement la tête."],["Que montre le geste de se gratter la tête ?",["Sa peur et son hésitation","Qu'elle a des poux","Qu'elle réfléchit au chemin"],"Le texte : « geste propre aux enfants terrifiés et indécis »."]],
   idees:["Cosette traverse seule le village de nuit pour aller chercher de l'eau","Tant qu'il y a des maisons, les lueurs aux fenêtres la rassurent","Après la dernière maison, la peur l'arrête : avancer devient impossible"]},
  {id:"ws7",th:"lettres nature",vu:"2026-11-04",src:"Victor Hugo, Les Misérables, t. II « Cosette », livre III, chapitre 5 (1862) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Les_Mis%C3%A9rables/Tome_2/Livre_3/05",titre:"La source dans le bois",
   texte:"Il n'y avait que sept ou huit minutes de la lisière du bois à la source. Cosette connaissait le chemin pour l'avoir fait plusieurs fois le jour. Chose étrange, elle ne se perdit pas. Un reste d'instinct la conduisait vaguement. Elle ne jetait cependant les yeux ni à droite ni à gauche, de crainte de voir des choses dans les branches et dans les broussailles. Elle arriva ainsi à la source. C'était une étroite cuve naturelle creusée par l'eau dans un sol glaiseux, profonde d'environ deux pieds, entourée de mousse et de ces grandes herbes gaufrées qu'on appelle collerettes de Henri IV, et pavée de quelques grosses pierres. Un ruisseau s'en échappait avec un petit bruit tranquille.",
   quiz:[["Pourquoi Cosette ne se perd-elle pas ?",["Elle connaît le chemin pour l'avoir fait de jour","Une lanterne l'éclaire","Elle suit le ruisseau à l'oreille"],"Le texte : « Cosette connaissait le chemin pour l'avoir fait plusieurs fois le jour »."],["Pourquoi ne regarde-t-elle ni à droite ni à gauche ?",["Par crainte de voir des choses dans les branches","Parce qu'elle est pressée","Parce qu'il fait trop froid"],"Elle ne regarde pas autour d'elle, « de crainte de voir des choses dans les branches »."],["Que veut dire « glaiseux », dans « un sol glaiseux » ?",["Fait d'argile","Couvert de glace","Plein de cailloux"],"La glaise est une terre argileuse, collante, que l'eau creuse facilement."]],
   idees:["La source est à quelques minutes de la lisière du bois","Cosette s'y rend sans se perdre, guidée par l'habitude et l'instinct","La source est une petite cuve naturelle entourée de mousse et d'herbes"]},
  {id:"ws8",th:"lettres",vu:"2026-11-04",src:"Gustave Flaubert, Madame Bovary, première partie, chapitre 1 (1857) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Madame_Bovary/Premi%C3%A8re_partie/1",titre:"Le nouveau",
   texte:"Resté dans l'angle, derrière la porte, si bien qu'on l'apercevait à peine, le nouveau était un gars de la campagne, d'une quinzaine d'années environ, et plus haut de taille qu'aucun de nous tous. Il avait les cheveux coupés droit sur le front, comme un chantre de village, l'air raisonnable et fort embarrassé. Quoiqu'il ne fût pas large des épaules, son habit-veste de drap vert à boutons noirs devait le gêner aux entournures et laissait voir, par la fente des parements, des poignets rouges habitués à être nus. Ses jambes, en bas bleus, sortaient d'un pantalon jaunâtre très tiré par les bretelles. Il était chaussé de souliers forts, mal cirés, garnis de clous.",
   quiz:[["Quel âge a environ le nouveau ?",["Une quinzaine d'années","Dix ans","Vingt ans"],"Le texte : « d'une quinzaine d'années environ »."],["Qu'est-ce qui montre que son habit est trop petit ?",["On voit ses poignets rouges par la fente des parements","Ses boutons ont sauté","Il le porte ouvert"],"L'habit-veste « devait le gêner aux entournures » et laissait voir ses poignets."],["Que révèlent ses « poignets rouges habitués à être nus » ?",["Un garçon de la campagne, peu habitué aux beaux habits","Un garçon malade","Un garçon qui s'est battu"],"Le texte le dit d'abord « un gars de la campagne » : ses poignets sont faits au grand air, pas aux manches."]],
   idees:["Le nouveau, garçon de la campagne, se tient à l'écart, gêné","Il est plus grand que les autres et mal à l'aise dans ses vêtements","Chaque détail de sa tenue trahit son origine modeste et rurale"]},
  {id:"ws9",th:"lettres",vu:"2026-11-04",src:"Guy de Maupassant, « Aux champs », Contes de la bécasse (1883) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Contes_de_la_b%C3%A9casse_(Havard,_1894)/Aux_champs",titre:"La soupe des Tuvache et des Vallin",
   texte:"Tout cela vivait péniblement de soupe, de pommes de terre et de grand air. À sept heures, le matin, puis à midi, puis à six heures, le soir, les ménagères réunissaient leurs mioches pour donner la pâtée, comme des gardeurs d'oies assemblent leurs bêtes. Les enfants étaient assis, par rang d'âge, devant la table en bois, vernie par cinquante ans d'usage. Le dernier moutard avait à peine la bouche au niveau de la planche. On posait devant eux l'assiette creuse pleine de pain molli dans l'eau où avaient cuit les pommes de terre, un demi-chou et trois oignons ; et toute la ligne mangeait jusqu'à plus faim. La mère empâtait elle-même le petit. Un peu de viande au pot-au-feu, le dimanche, était une fête pour tous ; et le père, ce jour-là, s'attardait au repas en répétant : « Je m'y ferais bien tous les jours. »",
   quiz:[["Combien de fois par jour les enfants mangent-ils ?",["Trois fois","Deux fois","Quatre fois"],"À sept heures, à midi et à six heures du soir : trois repas."],["Qu'est-ce qui fait la fête du dimanche ?",["Un peu de viande au pot-au-feu","Un gâteau","Une promenade en ville"],"Le texte : « Un peu de viande au pot-au-feu, le dimanche, était une fête pour tous »."],["Que veut dire « mioches » et « moutard » ?",["Des enfants, en langage familier","Des petits animaux","Des plats de légumes"],"Les mères réunissent leurs « mioches » ; le dernier « moutard » a la bouche au niveau de la table : ce sont les enfants."]],
   idees:["Les deux familles paysannes vivent pauvrement de soupe et de pommes de terre","Les mères nourrissent leurs enfants en rang, comme on rassemble des bêtes","Un peu de viande le dimanche suffit à faire une fête"]},
  {id:"ws10",th:"lettres",vu:"2026-11-04",src:"Guy de Maupassant, « La Ficelle », Miss Harriet (1884) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Miss_Harriet_(recueil)/%C3%89dition_Conard,_1910/La_Ficelle",titre:"Le bout de ficelle",
   texte:"Maître Hauchecorne, de Bréauté, venait d'arriver à Goderville, et il se dirigeait vers la place, quand il aperçut par terre un petit bout de ficelle. Maître Hauchecorne, économe en vrai Normand, pensa que tout était bon à ramasser qui peut servir ; et il se baissa péniblement, car il souffrait de rhumatismes. Il prit par terre le morceau de corde mince, et il se disposait à le rouler avec soin, quand il remarqua, sur le seuil de sa porte, maître Malandain, le bourrelier, qui le regardait. Ils avaient eu des affaires ensemble au sujet d'un licol, autrefois, et ils étaient restés fâchés, étant rancuniers tout deux. Maître Hauchecorne fut pris d'une sorte de honte d'être vu ainsi par son ennemi, cherchant dans la crotte un bout de ficelle. Il cacha brusquement sa trouvaille sous sa blouse, puis dans la poche de sa culotte ; puis il fit semblant de chercher encore par terre quelque chose qu'il ne trouvait point, et il s'en alla vers le marché, la tête en avant, courbé en deux par ses douleurs.",
   quiz:[["Pourquoi maître Hauchecorne ramasse-t-il la ficelle ?",["Par économie : tout ce qui peut servir est bon à prendre","Pour attacher sa vache","Pour la rendre à son propriétaire"],"Le texte : « économe en vrai Normand, [il] pensa que tout était bon à ramasser qui peut servir »."],["Pourquoi cache-t-il sa trouvaille ?",["Il a honte d'être vu par son ennemi Malandain","Il croit l'avoir volée","Il a peur des gendarmes"],"Il est pris de honte « d'être vu ainsi par son ennemi »."],["Qu'est-ce qu'un bourrelier, le métier de maître Malandain ?",["Un artisan qui fait les harnais des chevaux","Un boulanger","Un marchand de bois"],"Le bourrelier fait les harnais ; d'où la vieille dispute « au sujet d'un licol »."]],
   idees:["Un paysan économe ramasse un bout de ficelle en arrivant au marché","Son ennemi, le bourrelier Malandain, le voit faire","Honteux, il cache la ficelle et fait semblant de chercher autre chose"]},
  {id:"ws11",th:"lettres eco",vu:"2026-11-04",src:"Alphonse Daudet, « Le Secret de maître Cornille », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Le_secret_de_ma%C3%AEtre_Cornille",titre:"Les moulins et la minoterie",
   texte:"De droite et de gauche on ne voyait que des ailes qui viraient au mistral par-dessus les pins, des ribambelles de petits ânes chargés de sacs, montant et dévalant le long des chemins ; et toute la semaine c'était plaisir d'entendre sur la hauteur le bruit des fouets, le craquement de la toile et le Dia hue ! des aides-meuniers… Le dimanche nous allions aux moulins, par bandes. Là-haut, les meuniers payaient le muscat. Les meunières étaient belles comme des reines, avec leurs fichus de dentelles et leurs croix d'or. Moi, j'apportais mon fifre, et jusqu'à la noire nuit on dansait des farandoles. Ces moulins-là, voyez-vous, faisaient la joie et la richesse de notre pays. Malheureusement, des Français de Paris eurent l'idée d'établir une minoterie à vapeur, sur la route de Tarascon. Tout beau, tout nouveau ! Les gens prirent l'habitude d'envoyer leurs blés aux minotiers, et les pauvres moulins à vent restèrent sans ouvrage. Pendant quelque temps ils essayèrent de lutter, mais la vapeur fut la plus forte, et l'un après l'autre, pécaïre ! ils furent tous obligés de fermer…",
   quiz:[["Où les Parisiens installent-ils une minoterie à vapeur ?",["Sur la route de Tarascon","À Avignon","Près du Rhône, à Arles"],"Le texte : « une minoterie à vapeur, sur la route de Tarascon »."],["Que deviennent les moulins à vent ?",["Ils ferment l'un après l'autre","Ils se mettent à la vapeur","Ils deviennent des musées"],"« L'un après l'autre, pécaïre ! ils furent tous obligés de fermer »."],["Que signifie « pécaïre ! » dans la bouche du narrateur ?",["Une exclamation provençale de pitié","Le nom d'un moulin","Un juron contre les Parisiens"],"Pécaïre est une interjection provençale qui exprime la compassion, comme « le pauvre ! » en français."]],
   idees:["Les moulins à vent faisaient la joie et la richesse du pays","Une minoterie à vapeur leur prend leurs clients","Malgré leurs efforts, les moulins ferment l'un après l'autre"]},
  {id:"ws12",th:"lettres nature",vu:"2026-11-04",src:"Alphonse Daudet, « Les Étoiles », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Les_%C3%A9toiles",titre:"Le berger du Luberon",
   texte:"Du temps que je gardais les bêtes sur le Luberon, je restais des semaines entières sans voir âme qui vive, seul dans le pâturage avec mon chien Labri et mes ouailles. De temps en temps l'ermite du Mont-de-l'Ure passait par là pour chercher des simples ou bien j'apercevais la face noire de quelque charbonnier du Piémont ; mais c'étaient des gens naïfs, silencieux à force de solitude, ayant perdu le goût de parler et ne sachant rien de ce qui se disait en bas dans les villages et les villes. Aussi, tous les quinze jours, lorsque j'entendais, sur le chemin qui monte, les sonnailles du mulet de notre ferme m'apportant les provisions de quinzaine, et que je voyais apparaître peu à peu, au-dessus de la côte, la tête éveillée du petit miarro (garçon de ferme), ou la coiffe rousse de la vieille tante Norade, j'étais vraiment bien heureux.",
   quiz:[["Tous les combien le berger reçoit-il ses provisions ?",["Tous les quinze jours","Chaque semaine","Chaque mois"],"Le mulet de la ferme lui apporte « les provisions de quinzaine »."],["Comment s'appelle son chien ?",["Labri","Miarro","Norade"],"Le texte : « seul dans le pâturage avec mon chien Labri et mes ouailles »."],["Pourquoi le berger est-il si heureux de voir arriver le mulet ?",["Il rompt sa solitude et apporte des nouvelles d'en bas","Il a très faim","Il doit rendre son troupeau"],"Il reste des semaines sans voir personne ; les rares passants ne savent rien des villages."]],
   idees:["Le berger vit seul des semaines entières dans la montagne","Les rares passants sont silencieux et ignorent les nouvelles","L'arrivée des provisions, tous les quinze jours, est sa grande joie"]},
  {id:"ws13",th:"lettres",vu:"2026-11-04",src:"Jules Verne, Vingt mille lieues sous les mers, chapitre 1 (1870) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Vingt_mille_lieues_sous_les_mers/Partie_1/Chapitre_1",titre:"Une chose énorme",
   texte:"L'année 1866 fut marquée par un événement bizarre, un phénomène inexpliqué et inexplicable que personne n'a sans doute oublié. Sans parler des rumeurs qui agitaient les populations des ports et surexcitaient l'esprit public à l'intérieur des continents, les gens de mer furent particulièrement émus. Les négociants, armateurs, capitaines de navires, skippers et masters de l'Europe et de l'Amérique, officiers des marines militaires de tous pays, et, après eux, les gouvernements des divers États des deux continents, se préoccupèrent de ce fait au plus haut point. En effet, depuis quelque temps, plusieurs navires s'étaient rencontrés sur mer avec « une chose énorme, » un objet long, fusiforme, parfois phosphorescent, infiniment plus vaste et plus rapide qu'une baleine.",
   quiz:[["En quelle année se produit l'événement ?",["1866","1870","1856"],"Le texte : « L'année 1866 fut marquée par un événement bizarre »."],["À quoi compare-t-on la « chose énorme » ?",["À une baleine, en plus vaste et plus rapide","À un navire de guerre","À une île flottante"],"La chose est « infiniment plus vaste et plus rapide qu'une baleine »."],["Que veut dire « fusiforme » ?",["En forme de fuseau, allongé et effilé aux deux bouts","Qui fond au soleil","Qui avance très vite"],"Un fuseau est renflé au milieu et pointu aux bouts : la forme d'un objet « long, fusiforme »."]],
   idees:["En 1866, un phénomène inexpliqué agite le monde entier","Les marins surtout, puis les gouvernements, s'en inquiètent","Des navires ont croisé un objet long, parfois lumineux, plus grand qu'une baleine"]},
  {id:"ws14",th:"lettres",vu:"2026-11-04",src:"Guy de Maupassant, « Le Papa de Simon », La Maison Tellier (1881) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/La_Maison_Tellier_(recueil,_Ollendorff_1891)/Le_Papa_de_Simon",titre:"Simon à la sortie de l'école",
   texte:"Le fils de la Blanchotte parut à son tour sur le seuil de l'école. Il avait sept ou huit ans. Il était un peu pâlot, très propre, avec l'air timide, presque gauche. Il s'en retournait chez sa mère quand les groupes de ses camarades, chuchotant toujours et le regardant avec les yeux malins et cruels des enfants qui méditent un mauvais coup, l'entourèrent peu à peu et finirent par l'enfermer tout à fait. Il restait là, planté au milieu d'eux, surpris et embarrassé, sans comprendre ce qu'on allait lui faire. Mais le gars qui avait apporté la nouvelle, enorgueilli du succès obtenu déjà, lui demanda : — Comment t'appelles-tu, toi ? Il répondit : — « Simon. » — Simon quoi ? reprit l'autre. L'enfant répéta tout confus : — « Simon. » Le gars lui cria : — « On s'appelle Simon quelque chose… c'est pas un nom ça… Simon. » Et lui, prêt à pleurer, répondit pour la troisième fois : — Je m'appelle Simon. Les galopins se mirent à rire. Le gars triomphant éleva la voix : — « Vous voyez bien qu'il n'a pas de papa. »",
   quiz:[["Quel âge a Simon ?",["Sept ou huit ans","Dix ans","Cinq ans"],"Le texte : « Il avait sept ou huit ans »."],["Qu'est-ce qui fait rire les autres enfants ?",["Simon ne peut donner que son prénom","Simon pleure","Simon porte des habits sales"],"Simon répète seulement « Simon », sans nom de famille."],["Que cherche à montrer le gars en posant trois fois la même question ?",["Que Simon n'a pas de père","Que Simon a oublié son nom","Que Simon est sourd"],"Sa conclusion : « Vous voyez bien qu'il n'a pas de papa »."]],
   idees:["Simon, nouveau à l'école, est encerclé par ses camarades à la sortie","Un grand garçon lui demande son nom pour l'humilier","Simon ne peut dire que son prénom : on en conclut qu'il n'a pas de père"]},
  {id:"ws15",th:"lettres histoire",vu:"2026-11-04",src:"Honoré de Balzac, Eugénie Grandet (1834) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Eug%C3%A9nie_Grandet",titre:"Une rue de Saumur",
   texte:"Il se trouve dans certaines provinces des maisons dont la vue inspire une mélancolie égale à celle que provoquent les cloîtres les plus sombres, les landes les plus ternes ou les ruines les plus tristes. Peut-être y a-t-il à la fois dans ces maisons et le silence du cloître et l'aridité des landes, et les ossements des ruines. La vie et le mouvement y sont si tranquilles qu'un étranger les croirait inhabitées, s'il ne rencontrait tout à coup le regard pâle et froid d'une personne immobile dont la figure à demi monastique dépasse l'appui de la croisée, au bruit d'un pas inconnu. Ces principes de mélancolie existent dans la physionomie d'un logis situé à Saumur, au bout de la rue montueuse qui mène au château, par le haut de la ville. Cette rue, maintenant peu fréquentée, chaude en été, froide en hiver, obscure en quelques endroits, est remarquable par la sonorité de son petit pavé caillouteux, toujours propre et sec, par l'étroitesse de sa voie tortueuse, par la paix de ses maisons qui appartiennent à la vieille ville, et que dominent les remparts.",
   quiz:[["Dans quelle ville se trouve le logis décrit ?",["Saumur","Tours","Angers"],"Le logis est « situé à Saumur, au bout de la rue montueuse qui mène au château »."],["À quoi Balzac compare-t-il la mélancolie de ces maisons ?",["À celle des cloîtres, des landes et des ruines","À celle d'un cimetière","À celle d'un hiver sans fin"],"Le texte cite « les cloîtres les plus sombres, les landes les plus ternes ou les ruines les plus tristes »."],["Que veut dire « montueuse », pour la rue ?",["Qui monte, en pente","Pleine de monde","Bordée de monuments"],"La rue mène au château « par le haut de la ville » : elle monte."]],
   idees:["Certaines maisons de province inspirent une profonde mélancolie","Elles semblent inhabitées, tant la vie y est tranquille","Le roman s'ouvre sur une vieille rue de Saumur, silencieuse et tortueuse"]},
  {id:"ws16",th:"lettres histoire",vu:"2026-11-04",src:"Alphonse Daudet, « La Mule du pape », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/La_mule_du_Pape",titre:"Avignon au temps des papes",
   texte:"Pour la gaieté, la vie, l'animation, le train des fêtes, jamais une ville pareille. C'étaient, du matin au soir, des processions, des pèlerinages, les rues jonchées de fleurs, tapissées de hautes lices, des arrivages de cardinaux par le Rhône, bannières au vent, galères pavoisées, les soldats du Pape qui chantaient du latin sur les places, les crécelles des frères quêteurs ; puis, du haut en bas des maisons qui se pressaient en bourdonnant autour du grand palais papal comme des abeilles autour de leur ruche, c'était encore le tic tac des métiers à dentelles, le va-et-vient des navettes tissant l'or des chasubles, les petits marteaux des ciseleurs de burettes, les tables d'harmonie qu'on ajustait chez les luthiers, les cantiques des ourdisseuses ; par là-dessus le bruit des cloches, et toujours quelques tambourins qu'on entendait ronfler, là-bas, du côté du pont. Car chez nous, quand le peuple est content, il faut qu'il danse, il faut qu'il danse ; et comme en ce temps-là les rues de la ville étaient trop étroites pour la farandole, fifres et tambourins se postaient sur le pont d'Avignon, au vent frais du Rhône, et jour et nuit l'on y dansait, l'on y dansait…",
   quiz:[["Où dansait-on, faute de place dans les rues ?",["Sur le pont d'Avignon","Dans le palais des papes","Sur les bords de la Durance"],"Les rues étant trop étroites, « fifres et tambourins se postaient sur le pont d'Avignon »."],["À quoi sont comparées les maisons serrées autour du palais ?",["À des abeilles autour de leur ruche","À des moutons autour du berger","À des enfants autour de leur mère"],"Les maisons se pressent autour du palais « comme des abeilles autour de leur ruche »."],["Quel trait d'Avignon ce passage veut-il surtout montrer ?",["Une ville joyeuse et pleine d'activité","Une ville pauvre et silencieuse","Une ville en guerre"],"Première phrase : « Pour la gaieté, la vie, l'animation, le train des fêtes, jamais une ville pareille »."]],
   idees:["Avignon, au temps des papes, était la ville la plus gaie qui soit","Processions, fêtes et métiers animaient les rues du matin au soir","Le peuple content dansait sans cesse, notamment sur le pont"]},
  {id:"ws17",th:"lettres",vu:"2026-11-04",src:"Alexandre Dumas, Le Comte de Monte-Cristo, chapitre 2 (1844) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Le_Comte_de_Monte-Cristo/Chapitre_2",titre:"Le retour d'Edmond",
   texte:"— Que le Seigneur me pardonne, dit le jeune homme, de me réjouir d'un bonheur fait avec le deuil d'une famille ! mais Dieu sait que je n'eusse pas désiré ce bonheur ; il arrive, et je n'ai pas la force de m'en affliger : le brave capitaine Leclère est mort, mon père, et il est probable que, par la protection de M. Morrel, je vais avoir sa place. Comprenez-vous, mon père ? capitaine à vingt ans ! avec cent louis d'appointements et une part dans les bénéfices ! n'est-ce pas plus que ne pouvait vraiment l'espérer un pauvre matelot comme moi.",
   quiz:[["Pourquoi Edmond va-t-il peut-être devenir capitaine ?",["Le capitaine Leclère est mort","Il a acheté le navire","Il a sauvé l'équipage d'un naufrage"],"Le texte : « le brave capitaine Leclère est mort »."],["À quel âge Edmond deviendrait-il capitaine ?",["À vingt ans","À trente ans","À dix-huit ans"],"« Capitaine à vingt ans ! »"],["Pourquoi Edmond demande-t-il pardon au Seigneur ?",["Il se réjouit d'un bonheur venu de la mort d'un autre","Il a désobéi à son père","Il a abandonné son navire"],"Il se réjouit « d'un bonheur fait avec le deuil d'une famille »."]],
   idees:["Edmond se reproche de se réjouir d'un bonheur né d'un deuil","Le capitaine Leclère est mort, et Edmond va sans doute prendre sa place","Capitaine à vingt ans : c'est plus qu'un pauvre matelot pouvait espérer"]},
  {id:"ws18",th:"sciences lettres",vu:"2026-11-04",src:"Jules Verne, Voyage au centre de la Terre, chapitre 22 (1864) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Voyage_au_centre_de_la_Terre/Chapitre_22",titre:"Les terrains primitifs",
   texte:"Lorsque la terre se refroidit peu à peu aux premiers jours du monde, la diminution de son volume produisit dans l'écorce des dislocations, des ruptures, des retraits, des fendilles. Le couloir actuel était une fissure de ce genre par laquelle s'épanchait autrefois le granit éruptif. Ses mille détours formaient un inextricable labyrinthe à travers le sol primordial. À mesure que nous descendions, la succession des couches composant le terrain primitif apparaissait avec plus de netteté. La science géologique considère ce terrain primitif comme la base de l'écorce minérale, et elle a reconnu qu'il se compose de trois couches différentes, les schistes, les gneiss, les micaschistes, reposant sur cette roche inébranlable qu'on appelle le granit. Or, jamais minéralogistes ne s'étaient rencontrés dans des circonstances aussi merveilleuses pour étudier la nature sur place. Ce que la sonde, machine inintelligente et brutale, ne pouvait rapporter à la surface du globe de sa texture interne, nous allions l'étudier de nos yeux, le toucher de nos mains.",
   quiz:[["Sur quelle roche reposent les trois couches du terrain primitif ?",["Le granit","Le calcaire","Le basalte"],"Les trois couches reposent « sur cette roche inébranlable qu'on appelle le granit »."],["Qu'est-ce que les voyageurs peuvent faire mieux qu'une sonde ?",["Étudier la roche de leurs yeux et de leurs mains","Creuser plus vite","Rapporter de l'or"],"Ce que la sonde ne rapporte pas, « nous allions l'étudier de nos yeux, le toucher de nos mains »."],["D'où vient le couloir où descendent les voyageurs ?",["D'une fissure née du refroidissement de la Terre","D'une ancienne mine","D'un tunnel creusé par un fleuve"],"En se refroidissant, la Terre s'est fendue : « Le couloir actuel était une fissure de ce genre »."]],
   idees:["La galerie est une ancienne fissure née du refroidissement de la Terre","Le terrain primitif se compose de schistes, de gneiss et de micaschistes, posés sur le granit","Les voyageurs peuvent étudier sur place ce qu'aucune sonde ne rapporte"]},
  {id:"ws19",th:"lettres",vu:"2026-11-04",src:"Émile Zola, Au Bonheur des Dames, chapitre 5 (1883) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Au_bonheur_des_dames/5",titre:"Denise convoquée",
   texte:"Denise était descendue au rayon depuis une demi-heure à peine, lorsque madame Aurélie lui dit de sa voix brève : — Mademoiselle, on vous demande à la direction. La jeune fille trouva Mouret seul, assis dans le grand cabinet tendu de reps vert. Il venait de se rappeler « la mal peignée », comme la nommait Bourdoncle ; et lui qui répugnait d'ordinaire au rôle de gendarme, il avait eu l'idée de la faire comparaître pour la secouer un peu, si elle était toujours fagotée en provinciale. La veille, malgré sa plaisanterie, il avait éprouvé devant madame Desforges, une contrariété d'amour-propre, en voyant discuter l'élégance d'une de ses vendeuses. C'était, chez lui, un sentiment confus, un mélange de sympathie et de colère.",
   quiz:[["Qui convoque Denise à la direction ?",["Mouret","Bourdoncle","Madame Aurélie"],"Le texte : « La jeune fille trouva Mouret seul, assis dans le grand cabinet »."],["Quel surnom Bourdoncle donne-t-il à Denise ?",["« La mal peignée »","« La provinciale »","« La petite sauvage »"],"Il se rappelle « la mal peignée », comme la nommait Bourdoncle."],["Que veut dire « fagotée » ?",["Mal habillée","Fatiguée","Punie"],"Mouret veut la secouer « si elle était toujours fagotée en provinciale » : vêtue sans goût."]],
   idees:["Denise est appelée à la direction peu après son arrivée au rayon","Mouret veut la secouer à cause de sa tenue de provinciale","Il éprouve pour elle un mélange de sympathie et d'agacement"]},
  {id:"ws20",th:"lettres",vu:"2026-11-04",src:"Alphonse Daudet, « Le Curé de Cucugnan », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Le_cur%C3%A9_de_Cucugnan",titre:"Le curé de Cucugnan",
   texte:"L'abbé Martin était curé… de Cucugnan. Bon comme le pain, franc comme l'or, il aimait paternellement ses Cucugnanais ; pour lui, son Cucugnan aurait été le paradis sur terre, si les Cucugnanais lui avaient donné un peu plus de satisfaction. Mais, hélas ! les araignées filaient dans son confessionnal, et, le beau jour de Pâques, les hosties restaient au fond de son saint-ciboire. Le bon prêtre en avait le cœur meurtri, et toujours il demandait à Dieu la grâce de ne pas mourir avant d'avoir ramené au bercail son troupeau dispersé. Or, vous allez voir que Dieu l'entendit.",
   quiz:[["Qu'est-ce qui attriste l'abbé Martin ?",["Ses paroissiens ne viennent plus se confesser ni communier","Son église tombe en ruine","Il doit quitter Cucugnan"],"Les araignées filent dans son confessionnal et les hosties restent au fond du ciboire : personne ne vient."],["Que demande-t-il à Dieu ?",["De ne pas mourir avant d'avoir ramené son troupeau","Une nouvelle église","De partir pour Avignon"],"Il demande à Dieu « la grâce de ne pas mourir avant d'avoir ramené au bercail son troupeau dispersé »."],["Que signifie « ramener au bercail son troupeau dispersé » ?",["Faire revenir ses paroissiens à l'Église","Rassembler ses moutons","Retrouver sa famille"],"Image du pasteur : le troupeau, ce sont ses paroissiens, le bercail, l'Église."]],
   idees:["L'abbé Martin, bon comme le pain, aime ses paroissiens","Mais les Cucugnanais délaissent la confession et la communion","Il prie pour les ramener avant de mourir, et Dieu l'entend"]},
  {id:"ws21",th:"lettres eco",vu:"2026-11-04",src:"Guy de Maupassant, « Mon oncle Jules », Miss Harriet (1884) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Miss_Harriet_(recueil)/%C3%89dition_Conard,_1910/Mon_oncle_Jules",titre:"La gêne",
   texte:"Ma mère souffrait beaucoup de la gêne où nous vivions, et elle trouvait souvent des paroles aigres pour son mari, des reproches voilés et perfides. Le pauvre homme avait alors un geste qui me navrait. Il se passait la main ouverte sur le front, comme pour essuyer une sueur qui n'existait pas, et il ne répondait rien. Je sentais sa douleur impuissante. On économisait sur tout ; on n'acceptait jamais un dîner, pour n'avoir pas à le rendre ; on achetait les provisions au rabais, les fonds de boutique. Mes sœurs faisaient leurs robes elles-mêmes et avaient de longues discussions sur le prix du galon qui valait quinze centimes le mètre. Notre nourriture ordinaire consistait en soupe grasse et bœuf accommodé à toutes les sauces. Cela est sain et réconfortant, parait-il ; j'aurais préféré autre chose.",
   quiz:[["Pourquoi la famille n'accepte-t-elle jamais un dîner ?",["Pour ne pas avoir à le rendre","Par timidité","Parce que le père est malade"],"Le texte : « on n'acceptait jamais un dîner, pour n'avoir pas à le rendre »."],["Combien coûte le mètre de galon ?",["Quinze centimes","Un franc","Cinq centimes"],"Le galon « valait quinze centimes le mètre »."],["Que révèle le geste du père qui s'essuie le front sans répondre ?",["Une douleur qu'il ne peut pas exprimer","De la colère","La chaleur de la pièce"],"Le narrateur : « Je sentais sa douleur impuissante »."]],
   idees:["La famille vit dans la gêne et la mère en accable son mari","On économise sur tout, des dîners aux provisions","Le narrateur enfant subit cette vie étriquée"]},
  {id:"ws22",th:"lettres",vu:"2026-11-04",src:"Guy de Maupassant, « Mon oncle Jules », Miss Harriet (1884) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Miss_Harriet_(recueil)/%C3%89dition_Conard,_1910/Mon_oncle_Jules",titre:"La promenade du dimanche",
   texte:"Mais chaque dimanche nous allions faire notre tour de jetée en grande tenue. Mon père, en redingote, en grand chapeau, en gants, offrait le bras à ma mère, pavoisée comme un navire un jour de fête. Mes sœurs, prêtes les premières, attendaient le signal du départ ; mais, au dernier moment, on découvrait toujours une tache oubliée sur la redingote du père de famille, et il fallait bien vite l'effacer avec un chiffon mouillé de benzine. Mon père, gardant son grand chapeau sur la tête, attendait, en manches de chemise, que l'opération fût terminée, tandis que ma mère se hâtait, ayant ajusté ses lunettes de myope, et ôté ses gants pour ne les pas gâter.",
   quiz:[["Où la famille se promène-t-elle le dimanche ?",["Sur la jetée","Au jardin public","Dans la forêt"],"Le texte : « chaque dimanche nous allions faire notre tour de jetée en grande tenue »."],["Avec quoi efface-t-on la tache de la redingote ?",["Un chiffon mouillé de benzine","De l'eau savonneuse","Une brosse sèche"],"« Il fallait bien vite l'effacer avec un chiffon mouillé de benzine »."],["Que suggère l'image de la mère « pavoisée comme un navire un jour de fête » ?",["Elle est très parée, avec un peu de ridicule","Elle a le mal de mer","Elle porte un drapeau"],"Un navire pavoisé est couvert de drapeaux : l'image souligne l'excès de parure, avec ironie."]],
   idees:["Chaque dimanche, la famille fait en grande tenue son tour de jetée","Une tache découverte au dernier moment retarde toujours le départ","La scène montre le souci des apparences d'une famille modeste"]},
  {id:"ws23",th:"lettres",vu:"2026-11-04",src:"Guy de Maupassant, « La Parure », Contes du jour et de la nuit (1885) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Contes_du_jour_et_de_la_nuit_(%C3%A9d._Flammarion,_1885)/La_Parure",titre:"Une erreur du destin",
   texte:"C'était une de ces jolies et charmantes filles, nées, comme par une erreur du destin, dans une famille d'employés. Elle n'avait pas de dot, pas d'espérances, aucun moyen d'être connue, comprise, aimée, épousée par un homme riche et distingué ; et elle se laissa marier avec un petit commis du ministère de l'instruction publique. Elle fut simple ne pouvant être parée, mais malheureuse comme une déclassée ; car les femmes n'ont point de caste ni de race, leur beauté, leur grâce et leur charme leur servant de naissance et de famille. Leur finesse native, leur instinct d'élégance, leur souplesse d'esprit, sont leur seule hiérarchie, et font des filles du peuple les égales des plus grandes dames.",
   quiz:[["Qui épouse-t-elle ?",["Un petit commis du ministère de l'Instruction publique","Un riche négociant","Un officier"],"« Elle se laissa marier avec un petit commis du ministère de l'instruction publique »."],["Selon le narrateur, qu'est-ce qui sert de naissance aux femmes ?",["Leur beauté, leur grâce et leur charme","Leur dot","Leur famille"],"Leur beauté, leur grâce et leur charme leur servent « de naissance et de famille »."],["Pourquoi dit-elle qu'elle est née « par une erreur du destin » ?",["Elle se sent faite pour un monde plus riche que le sien","Elle a été adoptée","Elle est née loin de sa famille"],"Jolie et charmante, elle est pourtant née « dans une famille d'employés », sans dot."]],
   idees:["Une jeune femme jolie naît dans une famille modeste, sans dot","Elle épouse un petit employé et se sent déclassée","Pour le narrateur, grâce et finesse égalent les filles du peuple aux grandes dames"]},
  {id:"ws24",th:"lettres",vu:"2026-11-04",src:"Guy de Maupassant, « La Parure », Contes du jour et de la nuit (1885) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Contes_du_jour_et_de_la_nuit_(%C3%A9d._Flammarion,_1885)/La_Parure",titre:"Les rêves de Mathilde",
   texte:"Elle souffrait sans cesse, se sentant née pour toutes les délicatesses et tous les luxes. Elle souffrait de la pauvreté de son logement, de la misère des murs, de l'usure des sièges, de la laideur des étoffes. Toutes ces choses, dont une autre femme de sa caste ne se serait même pas aperçue, la torturaient et l'indignaient. La vue de la petite Bretonne qui faisait son humble ménage éveillait en elle des regrets désolés et des rêves éperdus. Elle songeait aux antichambres muettes, capitonnées avec des tentures orientales, éclairées par de hautes torchères de bronze, et aux deux grands valets en culotte courte qui dorment dans les larges fauteuils, assoupis par la chaleur lourde du calorifère.",
   quiz:[["Qu'est-ce qui éveille ses regrets ?",["La vue de la petite Bretonne qui fait son ménage","Les visites de ses amies","Les lettres de sa mère"],"« La vue de la petite Bretonne qui faisait son humble ménage éveillait en elle des regrets désolés »."],["À quoi songe-t-elle ?",["À des antichambres luxueuses et silencieuses","À un voyage en Orient","À une maison de campagne"],"Elle songe « aux antichambres muettes, capitonnées avec des tentures orientales »."],["Que montre la phrase « une autre femme de sa caste ne se serait même pas aperçue » de ces choses ?",["Que sa souffrance vient de ses rêves plus que de sa vraie misère","Que son logement est très délabré","Qu'elle est aveugle"],"Une autre ne verrait rien : c'est son désir de luxe qui la torture."]],
   idees:["Elle souffre de tout ce qui est pauvre autour d'elle","Ce qu'une autre ne remarquerait pas la torture","Elle rêve sans cesse de luxe et de salons raffinés"]},
  {id:"ws25",th:"lettres",vu:"2026-11-04",src:"Honoré de Balzac, Le Père Goriot (1835) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Le_P%C3%A8re_Goriot_(1910)/I",titre:"Au lecteur du Père Goriot",
   texte:"Le char de la civilisation, semblable à celui de l'idole de Jaggernat, à peine retardé par un cœur moins facile à broyer que les autres et qui enraie sa roue, l'a brisé bientôt et continue sa marche glorieuse. Ainsi ferez-vous, vous qui tenez ce livre d'une main blanche, vous qui vous enfoncez dans un moelleux fauteuil en vous disant : « Peut-être ceci va-t-il m'amuser. » Après avoir lu les secrètes infortunes du père Goriot, vous dînerez avec appétit en mettant votre insensibilité sur le compte de l'auteur, en le taxant d'exagération, en l'accusant de poésie.",
   quiz:[["Comment Balzac imagine-t-il son lecteur ?",["Enfoncé dans un fauteuil moelleux","Debout dans une librairie","Dans un train"],"Le lecteur s'enfonce « dans un moelleux fauteuil » en espérant s'amuser."],["De quoi le lecteur accusera-t-il l'auteur, selon Balzac ?",["D'exagération et de poésie","De mensonge","D'ennui"],"Il accusera l'auteur d'« exagération » et de « poésie »."],["Que reproche Balzac à son lecteur ?",["Son insensibilité : il dînera avec appétit après avoir lu","Sa paresse","Son ignorance"],"Le texte : « vous dînerez avec appétit en mettant votre insensibilité sur le compte de l'auteur »."]],
   idees:["La civilisation écrase les cœurs sans s'arrêter","Le lecteur confortable lira ces malheurs sans en être touché","Balzac devance son reproche : on l'accusera d'exagérer"]},
  {id:"ws26",th:"lettres",vu:"2026-11-04",src:"Pierre Loti, Pêcheur d'Islande, première partie, chapitre 1 (1886) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/P%C3%AAcheur_d%E2%80%99Islande,_1886/I",titre:"La sainte vierge des marins",
   texte:"Toutes ces boiseries étaient grossières et frustes, imprégnées d'humidité et de sel ; usées, polies par les frottements de leurs mains. Ils avaient bu, dans leurs écuelles, du vin et du cidre, aussi la joie de vivre éclairait leurs figures, qui étaient franches et braves. Maintenant ils restaient attablés et devisaient, en breton, sur des questions de femmes et de mariages. Contre un panneau du fond, une sainte vierge en faïence était fixée sur une planchette, à une place d'honneur. Elle était un peu ancienne, la patronne de ces marins, et peinte avec un art encore naïf. Mais les personnages en faïence se conservent beaucoup plus longtemps que les vrais hommes ; aussi sa robe rouge et bleue faisait encore l'effet d'une petite chose très fraîche au milieu de tous les gris sombres de cette pauvre maison de bois.",
   quiz:[["En quelle langue les marins parlent-ils ?",["En breton","En français","En normand"],"Ils devisaient « en breton, sur des questions de femmes et de mariages »."],["Pourquoi la robe de la vierge paraît-elle encore fraîche ?",["Les personnages en faïence se conservent mieux que les hommes","On la repeint chaque année","Elle est neuve"],"« Les personnages en faïence se conservent beaucoup plus longtemps que les vrais hommes »."],["Que veut dire « frustes », pour les boiseries ?",["Grossières, mal travaillées","Très anciennes et précieuses","Peintes en couleurs vives"],"Le texte associe « grossières et frustes » : un bois brut, sans finesse."]],
   idees:["Les marins se reposent dans une cabine étroite, humide et usée","Ils parlent en breton de femmes et de mariages","Une vierge en faïence, patronne des marins, garde ses couleurs"]},
  {id:"ws27",th:"lettres histoire",vu:"2026-11-04",src:"Erckmann-Chatrian, Histoire d'un conscrit de 1813, chapitre 4 (1864) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Histoire_d%E2%80%99un_conscrit_de_1813/4",titre:"Chez le sonneur de cloches",
   texte:"En songeant à cela j'arrivai chez le sonneur de cloches Brainstein, qui demeurait au coin de la petite place, dans une vieille baraque décrépite ; ses deux garçons étaient tisserands, et dans ce vieux nid on entendait grincer les métiers et siffler les navettes du matin au soir. La grand-mère, tellement vieille qu'on ne voyait plus ses yeux, dormait dans un antique fauteuil, au haut duquel perchait une pie. Le père Brainstein, quand il n'avait pas à sonner les cloches pour un baptême, un enterrement ou un mariage, lisait dans son almanach, derrière les petites vitres rondes de la croisée. À côté de leur baraque était une cassine, sous le toit de la vieille halle, où travaillait le savetier Koniam, et plus loin se trouvait l'étalage des bouchers et des fruitières.",
   quiz:[["Quel métier font les deux fils Brainstein ?",["Tisserands","Sonneurs de cloches","Savetiers"],"« Ses deux garçons étaient tisserands » : on entend les métiers et les navettes."],["Qu'est-ce qui perche sur le fauteuil de la grand-mère ?",["Une pie","Un chat","Un perroquet"],"La grand-mère dort dans un antique fauteuil, « au haut duquel perchait une pie »."],["Que veut dire « décrépite », pour la baraque ?",["Usée et délabrée par l'âge","Fraîchement repeinte","Construite en pierre"],"Décrépit : affaibli, dégradé par l'âge. Le texte parle d'une « vieille baraque » et d'un « vieux nid »."]],
   idees:["Le narrateur arrive chez Brainstein, le sonneur de cloches","Dans la vieille maison, on entend les métiers à tisser du matin au soir","Toute une petite ville d'artisans vit autour de la halle"]},
  {id:"ws28",th:"lettres",vu:"2026-11-04",src:"Guy de Maupassant, « Le Petit Fût », Les Sœurs Rondoli (1884) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Les_S%C5%93urs_Rondoli_(recueil,_Ollendorff_1904)/Le_Petit_F%C3%BBt",titre:"La mère Magloire",
   texte:"Chicot la regardait accomplir sa besogne. Ses doigts crochus, noués, durs comme des pattes de crabe, saisissaient à la façon de pinces les tubercules grisâtres dans une manne, et vivement elle les faisait tourner, enlevant de longues bandes de peau sous la lame d'un vieux couteau qu'elle tenait de l'autre main. Et, quand la pomme de terre était devenue toute jaune, elle la jetait dans un seau d'eau. Trois poules hardies s'en venaient l'une après l'autre jusque dans ses jupes ramasser les épluchures, puis se sauver à toutes pattes, portant au bec leur butin.",
   quiz:[["À quoi ressemblent les doigts de la mère Magloire ?",["À des pattes de crabe","À des branches sèches","À des griffes de chat"],"« Ses doigts crochus, noués, durs comme des pattes de crabe »."],["Que font les poules ?",["Elles viennent ramasser les épluchures","Elles picorent dans le seau","Elles dorment au soleil"],"Les poules viennent « ramasser les épluchures » puis se sauvent avec leur butin."],["Qu'est-ce qu'une « manne », où se trouvent les pommes de terre ?",["Un grand panier","Un seau d'eau","Un sac de toile"],"La manne est un grand panier d'osier ; le seau d'eau sert, lui, aux pommes de terre épluchées."]],
   idees:["Chicot observe la vieille éplucher ses pommes de terre","Ses mains crochues travaillent vite et avec adresse","Les poules viennent voler les épluchures jusque dans ses jupes"]},
  {id:"ws29",th:"lettres",vu:"2026-11-04",src:"Marcel Proust, Du côté de chez Swann, « Combray », I (1913) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Du_c%C3%B4t%C3%A9_de_chez_Swann/Partie_1",titre:"Longtemps, je me suis couché de bonne heure",
   texte:"Longtemps, je me suis couché de bonne heure. Parfois, à peine ma bougie éteinte, mes yeux se fermaient si vite que je n'avais pas le temps de me dire : « Je m'endors. » Et, une demi-heure après, la pensée qu'il était temps de chercher le sommeil m'éveillait ; je voulais poser le volume que je croyais avoir encore dans les mains et souffler ma lumière ; je n'avais pas cessé en dormant de faire des réflexions sur ce que je venais de lire, mais ces réflexions avaient pris un tour un peu particulier ; il me semblait que j'étais moi-même ce dont parlait l'ouvrage : une église, un quatuor, la rivalité de François I et de Charles-Quint. Cette croyance survivait pendant quelques secondes à mon réveil ; elle ne choquait pas ma raison, mais pesait comme des écailles sur mes yeux et les empêchait de se rendre compte que le bougeoir n'était pas allumé.",
   quiz:[["Que croit être le narrateur à demi endormi ?",["Ce dont parlait le livre qu'il lisait","Un chevalier du Moyen Âge","Un oiseau dans la forêt"],"« Il me semblait que j'étais moi-même ce dont parlait l'ouvrage »."],["Qu'est-ce qui le réveille une demi-heure après s'être endormi ?",["La pensée qu'il était temps de chercher le sommeil","Le sifflement d'un train","Sa mère qui entre dans la chambre"],"« La pensée qu'il était temps de chercher le sommeil m'éveillait »."],["Que fait la croyance du narrateur « comme des écailles sur [ses] yeux » ?",["Elle l'empêche de voir que la bougie est éteinte","Elle lui fait mal aux yeux","Elle l'aide à se rendormir"],"Elle pèse sur ses yeux et les empêche « de se rendre compte que le bougeoir n'était pas allumé »."]],
   idees:["Le narrateur s'endormait souvent très vite en lisant","Le livre continuait de l'occuper dans son demi-sommeil","Il croyait même être devenu ce dont parlait l'ouvrage"]},
  {id:"ws30",th:"lettres philo",vu:"2026-11-04",src:"Marcel Proust, Du côté de chez Swann, « Combray », I (1913) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Du_c%C3%B4t%C3%A9_de_chez_Swann/Partie_1",titre:"Un homme qui dort",
   texte:"Un homme qui dort tient en cercle autour de lui le fil des heures, l'ordre des années et des mondes. Il les consulte d'instinct en s'éveillant, et y lit en une seconde le point de la terre qu'il occupe, le temps qui s'est écoulé jusqu'à son réveil ; mais leurs rangs peuvent se mêler, se rompre. Que vers le matin, après quelque insomnie, le sommeil le prenne en train de lire, dans une posture trop différente de celle où il dort habituellement, il suffit de son bras soulevé pour arrêter et faire reculer le soleil, et à la première minute de son réveil, il ne saura plus l'heure, il estimera qu'il vient à peine de se coucher. Que s'il s'assoupit dans une position encore plus déplacée et divergente, par exemple après dîner assis dans un fauteuil, alors le bouleversement sera complet dans les mondes désorbités, le fauteuil magique le fera voyager à toute vitesse dans le temps et dans l'espace, et au moment d'ouvrir les paupières, il se croira couché quelques mois plus tôt dans une autre contrée.",
   quiz:[["Que suffit-il pour dérégler le sens du temps du dormeur ?",["Une posture inhabituelle, comme un bras soulevé","Un bruit dans la rue","Un repas trop lourd"],"« Il suffit de son bras soulevé pour arrêter et faire reculer le soleil »."],["Où le fauteuil « magique » fait-il voyager le dormeur ?",["Dans le temps et dans l'espace","Seulement dans ses souvenirs d'enfance","Dans un autre pays qu'il ne connaît pas"],"« Le fauteuil magique le fera voyager à toute vitesse dans le temps et dans l'espace »."],["Que veut dire « désorbités », dans « les mondes désorbités » ?",["Sortis de leur ordre habituel","Détruits","Éclairés"],"Image des astres sortis de leur orbite : le dormeur ne sait plus où ni quand il est."]],
   idees:["Au réveil, le dormeur retrouve d'instinct le lieu et l'heure","Une position inhabituelle suffit à brouiller ces repères","Il peut alors se croire ailleurs, des mois plus tôt"]},
  {id:"ws31",th:"lettres",vu:"2026-11-04",src:"Marcel Proust, Du côté de chez Swann, « Combray », I (1913) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Du_c%C3%B4t%C3%A9_de_chez_Swann/Partie_1",titre:"La lanterne magique",
   texte:"On avait bien inventé, pour me distraire les soirs où on me trouvait l'air trop malheureux, de me donner une lanterne magique, dont, en attendant l'heure du dîner, on coiffait ma lampe ; et, à l'instar des premiers architectes et maîtres verriers de l'âge gothique, elle substituait à l'opacité des murs d'impalpables irisations, de surnaturelles apparitions multicolores, où des légendes étaient dépeintes comme dans un vitrail vacillant et momentané. Mais ma tristesse n'en était qu'accrue, parce que rien que le changement d'éclairage détruisait l'habitude que j'avais de ma chambre et grâce à quoi, sauf le supplice du coucher, elle m'était devenue supportable. Maintenant je ne la reconnaissais plus et j'y étais inquiet, comme dans une chambre d'hôtel ou de « chalet » où je fusse arrivé pour la première fois en descendant de chemin de fer.",
   quiz:[["Pourquoi la lanterne magique augmente-t-elle sa tristesse ?",["Le changement d'éclairage lui rend sa chambre étrangère","Les histoires projetées lui font peur","Il doit la partager avec d'autres enfants"],"Le changement d'éclairage « détruisait l'habitude que j'avais de ma chambre »."],["À quoi les images projetées sont-elles comparées ?",["À un vitrail vacillant","À un tableau de musée","À un théâtre d'ombres chinoises"],"Les légendes sont dépeintes « comme dans un vitrail vacillant et momentané »."],["À qui le narrateur compare-t-il la lanterne magique ?",["Aux maîtres verriers de l'âge gothique","À un peintre de la Renaissance","À un montreur de marionnettes"],"Elle agit « à l'instar des premiers architectes et maîtres verriers de l'âge gothique »."]],
   idees:["À Combray, l'heure du coucher angoisse l'enfant","On lui offre une lanterne magique pour le distraire","Mais elle lui rend sa chambre méconnaissable et accroît son inquiétude"]},
  {id:"ws32",th:"lettres",vu:"2026-11-04",src:"Joris-Karl Huysmans, À rebours, chapitre 1 (1884) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/%C3%80_rebours/Chapitre_I",titre:"Le sermon aux fournisseurs",
   texte:"Enfin, il avait fait préparer une haute salle, destinée à la réception de ses fournisseurs ; ils entraient, s'asseyaient les uns à côté des autres, dans des stalles d'église, et alors il montait dans une chaire magistrale et prêchait le sermon sur le dandysme, adjurant ses bottiers et ses tailleurs de se conformer, de la façon la plus absolue, à ses brefs en matière de coupe, les menaçant d'une excommunication pécuniaire s'ils ne suivaient pas, à la lettre, les instructions contenues dans ses monitoires et ses bulles. Il s'acquit la réputation d'un excentrique qu'il paracheva en se vêtant de costumes de velours blanc, de gilets d'orfroi, en plantant, en guise de cravate, un bouquet de Parme dans l'échancrure décolletée d'une chemise, en donnant aux hommes de lettres des dîners retentissants, un entre autres, renouvelé du xviii siècle, où, pour célébrer la plus futile des mésaventures, il avait organisé un repas de deuil.",
   quiz:[["Où des Esseintes fait-il asseoir ses bottiers et tailleurs ?",["Dans des stalles d'église","Autour d'une table de banquet","Sur des bancs d'école"],"« Ils entraient, s'asseyaient les uns à côté des autres, dans des stalles d'église »."],["De quoi menace-t-il ceux qui ne suivent pas ses instructions ?",["D'une excommunication pécuniaire","D'un procès","De ne plus leur adresser la parole"],"Il les menace « d'une excommunication pécuniaire »."],["Pourquoi le texte emploie-t-il des mots d'Église (chaire, sermon, bulles) ?",["Pour se moquer d'un dandy qui se prend pour un pape de la mode","Parce que des Esseintes est prêtre","Parce que la scène se passe dans une église"],"Il « prêchait le sermon sur le dandysme » : le vocabulaire religieux rend la scène ironique."]],
   idees:["Des Esseintes reçoit ses fournisseurs comme un prédicateur en chaire","Il leur impose ses goûts vestimentaires comme des commandements","Ses extravagances lui valent une réputation d'excentrique"]},
  {id:"ws33",th:"lettres",vu:"2026-11-04",src:"Joris-Karl Huysmans, La Cathédrale, chapitre 1 (1898) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/La_Cath%C3%A9drale_(Huysmans)/I",titre:"La place balayée par le vent",
   texte:"Durtal le connaissait ce moment délicieux où l'on reprend haleine, encore abasourdi par ce brusque passage d'une bise cinglante à une caresse veloutée d'air. Tous les matins, à cinq heures, il quittait son logis et pour atteindre les dessous de l'étrange bois, il devait traverser cette place ; et toujours les mêmes gens paraissaient au débouché des mêmes rues ; des religieuses courbant la tête, penchées toutes en avant, la coiffe retroussée, battant de l'aile, le vent s'engouffrant dans les jupes tenues à grand'peine ; puis repliées en deux, des femmes ratatinées dans leurs vêtements, les serrant contre elles, s'avançaient, le dos incliné, fouettées par les rafales.",
   quiz:[["À quelle heure Durtal quitte-t-il son logis ?",["À cinq heures du matin","À midi","À la tombée de la nuit"],"« Tous les matins, à cinq heures, il quittait son logis »."],["Comment marchent les religieuses sur la place ?",["Courbant la tête, penchées en avant","D'un pas lent et droit","En se tenant par le bras"],"Des religieuses « courbant la tête, penchées toutes en avant »."],["Quel est ce « moment délicieux » que Durtal connaît ?",["Le passage du vent glacial à l'air doux de l'abri","Le lever du soleil","Le repas du matin"],"Le texte : « ce brusque passage d'une bise cinglante à une caresse veloutée d'air »."]],
   idees:["Chaque matin Durtal traverse la même place, à Chartres","Il y croise toujours les mêmes passants","Tous avancent courbés contre le vent"]},
  {id:"ws34",th:"lettres",vu:"2026-11-04",src:"Joris-Karl Huysmans, La Cathédrale, chapitre 1 (1898) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/La_Cath%C3%A9drale_(Huysmans)/I",titre:"L'étrange forêt",
   texte:"Bien qu'il connût la route, il s'avançait avec précaution, dans cette avenue que bordaient d'énormes arbres dont les cimes se perdaient dans l'ombre. L'on pouvait se croire dans une serre coiffée d'un dôme de verre noir, car l'on marchait sur des dalles et nul ciel n'apparaissait et nulle brise ne passait au-dessus de vous. Les quelques étoiles mêmes dont les lueurs clignaient au loin, n'appartenaient à aucun firmament, car elles tremblotaient presque au ras des pavés, s'allumaient sur la terre, en somme. L'on n'entendait, dans cette obscurité, que des bruits légers de pas ; l'on n'apercevait que des ombres silencieuses, modelées ainsi que sur un fond de crépuscule avec des lignes plus foncées de nuit.",
   quiz:[["Qu'est en réalité cette « forêt » aux énormes arbres ?",["L'intérieur d'une cathédrale, encore dans le noir","Un parc de la ville","Une serre de jardinier"],"On marche sur des dalles, nul ciel n'apparaît : ce sont les piliers et la nef de la cathédrale, dans le noir. Le livre a pour titre La Cathédrale."],["Que sont les « étoiles » qui brillent au ras des pavés ?",["Des lumières allumées sur le sol, comme des veilleuses","Des reflets de la lune","Des lucioles"],"Elles « tremblotaient presque au ras des pavés, s'allumaient sur la terre » : des veilleuses, pas des astres."],["Que veut dire « firmament » ?",["La voûte du ciel","La terre ferme","Une lumière très vive"],"Le firmament est le ciel où brillent les étoiles ; celles-ci n'appartiennent « à aucun firmament »."]],
   idees:["Durtal avance dans une avenue obscure bordée d'arbres immenses","Aucun ciel n'apparaît, on marche sur des dalles","Ce décor de forêt nocturne est en fait l'intérieur de la cathédrale"]},
  {id:"ws35",th:"lettres",vu:"2026-11-04",src:"Joris-Karl Huysmans, En route, préface (édition de 1896) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/En_route_(Huysmans)/Texte_entier",titre:"Trop de lettres",
   texte:"Je n'aime ni les avant-propos, ni les préfaces et, autant que possible, je m'abstiens de faire devancer mes livres par d'inutiles phrases. Il me faut donc un motif sérieux, quelque chose comme un cas de légitime défense, pour me résoudre à dédicacer de ces quelques lignes cette nouvelle édition d'En Route. Ce motif le voici : Depuis la mise en vente de ce volume, ma correspondance, déjà très développée par les discussions dont Là-Bas fut cause, s'est accrue de telle sorte que je me vois dans la nécessité ou de ne plus répondre aux lettres que je reçois, ou de renoncer à tout travail.",
   quiz:[["Pourquoi Huysmans écrit-il exceptionnellement une préface ?",["Son courrier est devenu si abondant qu'il l'empêche de travailler","Son éditeur l'a exigé","Il veut corriger des fautes du livre"],"Sa correspondance « s'est accrue de telle sorte » qu'il ne peut plus tout faire."],["Quel choix sa correspondance lui impose-t-elle ?",["Ne plus répondre aux lettres ou renoncer à tout travail","Changer d'éditeur ou de pays","Écrire moins de livres ou les écrire plus courts"],"Il doit choisir : « ne plus répondre aux lettres que je reçois, ou de renoncer à tout travail »."],["Pourquoi parle-t-il de « légitime défense » ?",["Pour dire qu'il faut une raison très sérieuse pour qu'il écrive une préface","Parce qu'on l'a attaqué en justice","Parce qu'un lecteur l'a menacé"],"Il n'aime pas les préfaces : il lui faut un motif sérieux, « quelque chose comme un cas de légitime défense »."]],
   idees:["Huysmans n'aime pas écrire de préfaces","Le succès d'En route lui vaut une correspondance énorme","Il doit choisir entre répondre et travailler"]},
  {id:"ws36",th:"lettres",vu:"2026-11-04",src:"Léon Bloy, Le Désespéré, chapitre 1 (1886) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Le_D%C3%A9sesp%C3%A9r%C3%A9/01",titre:"Le père et le fils écrivain",
   texte:"Tel a été le vestibule de mon existence d'écrivain, — existence à peine changée, d'ailleurs, même aujourd'hui que je suis devenu quasi célèbre. Mon père le savait et en mourait de honte. « Excellent théologien maçonnique, adorateur de Rousseau et de Benjamin Franklin, toute sa jurisprudence critique était d'arpenter le mérite à la toise du succès. À ce point de vue, Dumas père et Béranger lui paraissaient des abreuvoirs suffisants pour toutes les soifs esthétiques. « Il me chérissait, cependant, à sa manière. Avant que j'eusse fini de baver dans mes langes, avant même que je vinsse au monde, il avait soigneusement marqué toutes les étapes de ma vie, avec la plus géométrique des sollicitudes. Rien n'avait été oublié, excepté l'éventualité d'une pente littéraire.",
   quiz:[["À quoi le père mesurait-il le mérite ?",["Au succès","À la sainteté","À l'érudition"],"« Toute sa jurisprudence critique était d'arpenter le mérite à la toise du succès »."],["Qu'avait-il oublié en traçant la vie de son fils ?",["La possibilité d'une vocation littéraire","Le choix d'une épouse","Le service militaire"],"« Rien n'avait été oublié, excepté l'éventualité d'une pente littéraire »."],["Que veut dire « arpenter le mérite à la toise du succès » ?",["Mesurer la valeur d'un auteur à sa réussite","Marcher beaucoup pour réussir","Réussir grâce à son mérite"],"Arpenter et toise sont des mots de mesure : le père mesurait la valeur d'après le succès."]],
   idees:["Le narrateur a connu la misère avant de devenir écrivain","Son père, qui jugeait tout au succès, en avait honte","Il avait tout prévu pour son fils, sauf la littérature"]},
  {id:"ws37",th:"philo lettres",vu:"2026-11-04",src:"Léon Bloy, La Femme pauvre, deuxième partie, chapitre 1 (1897) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/La_Femme_pauvre/Partie_2/1",titre:"Le mystère de la Pauvreté",
   texte:"Vous aurez toujours des pauvres parmi vous. Depuis le gouffre de cette Parole, aucun homme n'a jamais pu dire ce que c'est que la Pauvreté. Les Saints qui l'ont épousée d'amour et qui lui ont fait beaucoup d'enfants assurent qu'elle est infiniment aimable. Ceux qui ne veulent pas de cette compagne meurent quelquefois d'épouvante ou de désespoir sous son baiser, et la multitude passe « de l'utérus au sépulcre » sans savoir ce qu'il faut penser de ce monstre. Quand on interroge Dieu, il répond que c'est Lui qui est le Pauvre : Ego sum pauper. Quand on ne l'interroge pas, il étale sa magnificence. La Création paraît être une fleur de la Pauvreté infinie ; et le chef-d'œuvre suprême de Celui qu'on nomme le Tout-Puissant a été de se faire crucifier comme un voleur dans l'Ignominie absolue. Les Anges se taisent et les Démons tremblants s'arrachent la langue pour ne pas parler. Les seuls idiots de ce dernier siècle ont entrepris d'élucider le mystère. En attendant que l'abîme les engloutisse, la Pauvreté se promène tranquillement avec son masque et son crible.",
   quiz:[["Selon les Saints, comment est la Pauvreté ?",["Infiniment aimable","Une épreuve à fuir","Un châtiment mérité"],"« Les Saints qui l'ont épousée d'amour […] assurent qu'elle est infiniment aimable »."],["Que répond Dieu quand on l'interroge, selon Bloy ?",["Que c'est Lui qui est le Pauvre","Que les pauvres seront riches","Qu'il faut donner aux pauvres"],"Dieu répond « que c'est Lui qui est le Pauvre : Ego sum pauper »."],["D'où vient la phrase « Vous aurez toujours des pauvres parmi vous » ?",["De l'Évangile : c'est une parole du Christ","D'un proverbe paysan","D'un discours politique"],"Bloy parle du « gouffre de cette Parole » : c'est la parole de Jésus rapportée par les Évangiles."]],
   idees:["Nul n'a jamais su dire ce qu'est la Pauvreté","Les Saints l'aiment, les autres la redoutent","Bloy y voit un mystère divin, jusque dans la Croix"]},
  {id:"ws38",th:"lettres",vu:"2026-11-04",src:"Léon Bloy, Le Désespéré, chapitre 2 (1886) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Le_D%C3%A9sesp%C3%A9r%C3%A9/02",titre:"Le triomphe de la médiocrité",
   texte:"Alexis Dulaurier, ami, par choix, de tout le monde et, par conséquent, sans principes comme sans passions, comblé des dons de la médiocrité, — cette force à déraciner des Himalayas ! — pouvait raisonnablement prétendre à tous les succès. Quand l'heure fut venue, il n'eut qu'à toucher du doigt les murailles de bêtise de la grande Publicité pour qu'elles tombassent aussitôt devant lui et pour qu'il entrât, comme un Antiochus, dans cette forteresse imprenable aux gens de génie, avec les cent vingt éléphants futiles chargés de son bagage littéraire. Sa prépondérante situation d'écrivain est désormais incontestable.",
   quiz:[["Pourquoi Dulaurier pouvait-il prétendre à tous les succès, selon Bloy ?",["Il était comblé des dons de la médiocrité","Il avait du génie","Il était très riche"],"Le texte : « comblé des dons de la médiocrité »."],["À qui le narrateur le compare-t-il en entrant dans la forteresse ?",["À Antiochus et ses éléphants","À Napoléon","À Hannibal franchissant les Alpes"],"Il entre « comme un Antiochus » dans la forteresse, « avec les cent vingt éléphants futiles » de son bagage."],["Sur quel ton Bloy parle-t-il de Dulaurier ?",["Ironique : il le méprise en ayant l'air de le louer","Admiratif","Neutre"],"Les « dons de la médiocrité » et les « murailles de bêtise » montrent l'ironie méprisante."]],
   idees:["Dulaurier est l'ami de tous, donc sans principes","Sa médiocrité est sa vraie force","La grande publicité s'ouvre devant lui, fermée aux gens de génie"]},
  {id:"ws39",th:"lettres nature",vu:"2026-11-04",src:"Alphonse Daudet, « Installation », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Installation",titre:"Le moulin au soleil",
   texte:"C'est de là que je vous écris, ma porte grande ouverte, au bon soleil. Un joli bois de pins tout étincelant de lumière dégringole devant moi jusqu'au bas de la côte. À l'horizon, les Alpilles découpent leurs crêtes fines… Pas de bruit… À peine, de loin en loin, un son de fifre, un courlis dans les lavandes, un grelot de mules sur la route… Tout ce beau paysage provençal ne vit que par la lumière. Et maintenant, comment voulez-vous que je le regrette, votre Paris bruyant et noir ? Je suis si bien dans mon moulin ! C'est si bien le coin que je cherchais, un petit coin parfumé et chaud, à mille lieues des journaux, des fiacres, du brouillard !…",
   quiz:[["Quelles montagnes découpent leurs crêtes à l'horizon ?",["Les Alpilles","Les Pyrénées","Les Vosges"],"« À l'horizon, les Alpilles découpent leurs crêtes fines »."],["Que fuit le narrateur en s'installant au moulin ?",["Paris, ses journaux, ses fiacres et son brouillard","La mer et les tempêtes","Sa famille"],"Il ne regrette pas « votre Paris bruyant et noir » ni ses journaux, ses fiacres, son brouillard."],["Selon le narrateur, qu'est-ce qui fait vivre le paysage provençal ?",["La lumière","Le bruit","Les gens"],"Le texte : « Tout ce beau paysage provençal ne vit que par la lumière »."]],
   idees:["Le narrateur écrit porte ouverte, au soleil","Le paysage provençal est calme et lumineux","Il ne regrette pas du tout Paris"]},
  {id:"ws40",th:"lettres nature",vu:"2026-11-04",src:"Alphonse Daudet, « Installation », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Installation",titre:"La rentrée des troupeaux",
   texte:"Il faut vous dire qu'en Provence, c'est l'usage, quand viennent les chaleurs, d'envoyer le bétail dans les Alpes. Bêtes et gens passent cinq ou six mois là-haut, logés à la belle étoile, dans l'herbe jusqu'au ventre ; puis, au premier frisson de l'automne, on redescend au mas, et l'on revient brouter bourgeoisement les petites collines grises que parfume le romarin… Donc hier soir les troupeaux rentraient. Depuis le matin, le portail attendait, ouvert à deux battants ; les bergeries étaient pleines de paille fraîche. D'heure en heure on se disait : « Maintenant, ils sont à Eyguières, maintenant au Paradou. » Puis, tout à coup, vers le soir, un grand cri : « Les voilà ! » et là-bas, au lointain, nous voyons le troupeau s'avancer dans une gloire de poussière.",
   quiz:[["Où envoie-t-on le bétail quand viennent les chaleurs ?",["Dans les Alpes","En Camargue","Au bord de la mer"],"« Quand viennent les chaleurs, d'envoyer le bétail dans les Alpes »."],["Combien de temps bêtes et gens restent-ils là-haut ?",["Cinq ou six mois","Deux semaines","Toute l'année"],"« Bêtes et gens passent cinq ou six mois là-haut »."],["Qu'est-ce qu'un « mas » ?",["Une ferme provençale","Une montagne","Une bergerie d'altitude"],"On « redescend au mas » à l'automne : la ferme, en bas, d'où l'on attend les troupeaux."]],
   idees:["En Provence, on mène le bétail l'été dans les Alpes","À l'automne, les troupeaux redescendent au mas","Tout le mas attend leur retour avec impatience"]},
  {id:"ws41",th:"lettres nature",vu:"2026-11-04",src:"Alphonse Daudet, « Le Phare des Sanguinaires », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Le_phare_des_Sanguinaires",titre:"L'île des Sanguinaires",
   texte:"Figurez-vous une île rougeâtre et d'aspect farouche ; le phare à une pointe, à l'autre une vieille tour génoise où, de mon temps, logeait un aigle. En bas, au bord de l'eau, un lazaret en ruine, envahi de partout par les herbes ; puis, des ravins, des maquis, de grandes roches, quelques chèvres sauvages, de petits chevaux corses gambadant la crinière au vent ; enfin là-haut, tout en haut, dans un tourbillon d'oiseaux de mer, la maison du phare, avec sa plate-forme en maçonnerie blanche, où les gardiens se promènent de long en large, la porte verte en ogive, la petite tour de fonte, et au-dessus la grosse lanterne à facettes qui flambe au soleil et fait de la lumière même pendant le jour…",
   quiz:[["Qu'y a-t-il à l'autre pointe de l'île, en face du phare ?",["Une vieille tour génoise","Un village de pêcheurs","Une chapelle"],"« Le phare à une pointe, à l'autre une vieille tour génoise »."],["D'après le texte, dans quelle région se trouve l'île ?",["En Corse","En Bretagne","En Provence"],"La tour génoise et les petits chevaux corses situent l'île en Corse."],["Que veut dire « farouche », pour l'aspect de l'île ?",["Sauvage, qui semble hostile","Couvert de fleurs","Très peuplé"],"Farouche : sauvage, rude. Le texte décrit ravins, maquis, roches et chèvres sauvages."]],
   idees:["L'île est sauvage et rougeâtre","On y voit un lazaret en ruine, des maquis et des bêtes libres","Tout en haut se dresse la maison du phare"]},
  {id:"ws42",th:"lettres",vu:"2026-11-04",src:"Alphonse Daudet, « Les Trois Messes basses », Lettres de mon moulin (édition de 1879) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Les_trois_messes_basses",titre:"Le diable déguisé en clerc",
   texte:"Cette conversation se tenait une nuit de Noël de l'an de grâce mil six cent et tant, entre le révérend dom Balaguère, ancien prieur des Barnabites, présentement chapelain gagé des sires de Trinquelage, et son petit clerc Garrigou, ou du moins ce qu'il croyait être le petit clerc Garrigou, car vous saurez que le diable, ce soir-là, avait pris la face ronde et les traits indécis du jeune sacristain pour mieux induire le révérend père en tentation et lui faire commettre un épouvantable péché de gourmandise. Donc, pendant que le soi-disant Garrigou (hum ! hum !) faisait à tour de bras carillonner les cloches de la chapelle seigneuriale, le révérend achevait de revêtir sa chasuble dans la petite sacristie du château ; et, l'esprit déjà troublé par toutes ces descriptions gastronomiques, il se répétait à lui-même en s'habillant : — Des dindes rôties… des carpes dorées… des truites grosses comme ça !…",
   quiz:[["Qui a pris l'apparence du petit clerc Garrigou ?",["Le diable","Le marquis","Un ange"],"Le diable avait pris « la face ronde et les traits indécis du jeune sacristain »."],["Quel péché le faux Garrigou veut-il faire commettre au chapelain ?",["La gourmandise","L'orgueil","La colère"],"Pour faire commettre au chapelain « un épouvantable péché de gourmandise »."],["Pourquoi le narrateur glisse-t-il « (hum ! hum !) » après « le soi-disant Garrigou » ?",["Pour rappeler avec malice que c'est le diable","Parce qu'il tousse","Parce qu'il a oublié son nom"],"Le narrateur sait que ce Garrigou est le diable et le fait comprendre d'un clin d'œil."]],
   idees:["La scène se passe une nuit de Noël au XVIIe siècle","Le diable a pris les traits du clerc pour tenter dom Balaguère","Le chapelain, troublé, ne pense plus qu'au réveillon"]},
  {id:"ws43",th:"lettres",vu:"2026-11-04",src:"Alphonse Daudet, « Les Vieux », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/Les_vieux",titre:"Une lettre de Paris",
   texte:"Tu entreras sans frapper, — la porte est toujours ouverte, — et, en entrant, tu crieras bien fort : « Bonjour, braves gens ! Je suis l'ami de Maurice… » Alors, tu verras deux petits vieux, oh ! mais vieux, vieux, archivieux, te tendre les bras du fond de leurs grands fauteuils, et tu les embrasseras de ma part, avec tout ton cœur, comme s'ils étaient à toi. Puis vous causerez ; ils te parleront de moi, rien que de moi ; ils te raconteront mille folies que tu écouteras sans rire… Tu ne riras pas, hein ?… Ce sont mes grands-parents, deux êtres dont je suis toute la vie et qui ne m'ont pas vu depuis dix ans…",
   quiz:[["Qui sont les deux petits vieux ?",["Les grands-parents de Maurice","Les parents du meunier","Des voisins du moulin"],"« Ce sont mes grands-parents, deux êtres dont je suis toute la vie »."],["Depuis combien de temps ne l'ont-ils pas vu ?",["Dix ans","Un an","Vingt ans"],"« Qui ne m'ont pas vu depuis dix ans »."],["Pourquoi le narrateur demande-t-il : « Tu ne riras pas, hein ? »",["Il craint que son ami se moque de ces vieillards qui l'aiment","Il raconte une histoire triste","Son ami rit trop fort"],"Ils raconteront « mille folies » sur lui : il veut qu'on les écoute avec respect."]],
   idees:["Maurice demande à son ami d'aller voir ses grands-parents","Il lui décrit l'accueil qui l'attend","Il ne les a pas vus depuis dix ans"]},
  {id:"ws44",th:"lettres eco",vu:"2026-11-04",src:"Alphonse Daudet, « L'Élixir du Révérend Père Gaucher », Lettres de mon moulin (1869) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Lettres_de_mon_moulin/L%E2%80%99%C3%A9lixir_du_P%C3%A8re_Gaucher",titre:"La misère des Pères blancs",
   texte:"Il y a vingt ans, les Prémontrés, ou plutôt les Pères blancs, comme les appellent nos Provençaux, étaient tombés dans une grande misère. Si vous aviez vu leur maison de ce temps-là, elle vous aurait fait peine. Le grand mur, la tour Pacôme, s'en allaient en morceaux. Tout autour du cloître rempli d'herbes, les colonnettes se fendaient, les saints de pierre croulaient dans leurs niches. Pas un vitrail debout, pas une porte qui tînt. Dans les préaux, dans les chapelles, le vent du Rhône soufflait comme en Camargue, éteignant les cierges, cassant le plomb des vitrages, chassant l'eau des bénitiers. Mais le plus triste de tout, c'était le clocher du couvent, silencieux comme un pigeonnier vide ; et les Pères, faute d'argent pour s'acheter une cloche, obligés de sonner matines avec des cliquettes de bois d'amandier !…",
   quiz:[["Avec quoi les Pères sonnent-ils matines ?",["Des cliquettes de bois d'amandier","Une cloche fêlée","Un tambour"],"« Obligés de sonner matines avec des cliquettes de bois d'amandier »."],["Comment les Provençaux appellent-ils les Prémontrés ?",["Les Pères blancs","Les Pères noirs","Les frères gris"],"Le texte : « les Prémontrés, ou plutôt les Pères blancs, comme les appellent nos Provençaux »."],["Que veut dire « sonner matines » ?",["Appeler à la prière de la nuit ou du petit matin","Réveiller les paysans","Annoncer un mariage"],"Les matines sont l'office de prière de la nuit ou de l'aube ; faute de cloche, ils ont des cliquettes."]],
   idees:["Il y a vingt ans, les Prémontrés étaient très pauvres","Leur couvent tombait en ruine","Ils n'avaient même plus de quoi s'acheter une cloche"]},
  {id:"ws45",th:"lettres",vu:"2026-11-04",src:"Jules Renard, Poil de Carotte, « Les Poules » (1894) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Poil_de_Carotte/01",titre:"Fier de lui",
   texte:"Tâtonnant, il saisit le crochet de la porte. Au bruit de ses pas, les poules effarées s'agitent en gloussant sur leur perchoir. Poil de Carotte leur crie : — Taisez-vous donc, c'est moi ! ferme la porte et se sauve, les jambes, les bras comme ailés. Quand il rentre, haletant, fier de lui, dans la chaleur et la lumière, il lui semble qu'il échange des loques pesantes de boue et de pluie contre un vêtement neuf et léger. Il sourit, se tient droit, dans son orgueil, attend les félicitations, et maintenant hors de danger, cherche sur le visage de ses parents la trace des inquiétudes qu'ils ont eues. Mais grand frère Félix et sœur Ernestine continuent tranquillement leur lecture, et madame Lepic lui dit, de sa voix naturelle : — Poil de Carotte, tu iras les fermer tous les soirs.",
   quiz:[["Qu'espère Poil de Carotte en rentrant ?",["Des félicitations","Une gifle","Un bon dîner"],"Il attend les félicitations et cherche sur le visage de ses parents « la trace des inquiétudes »."],["Que lui dit sa mère ?",["Qu'il ira fermer les poules tous les soirs","Qu'il a été très courageux","Qu'il a oublié la porte"],"« Poil de Carotte, tu iras les fermer tous les soirs »."],["Que montre la réponse de madame Lepic ?",["Qu'elle n'a pas eu peur pour lui et le traite durement","Qu'elle est fière de lui","Qu'elle a oublié les poules"],"Elle répond « de sa voix naturelle » : aucune inquiétude, aucun éloge, une corvée de plus."]],
   idees:["Poil de Carotte surmonte sa peur et ferme les poules","Il rentre fier, attendant qu'on le félicite","Personne ne s'en soucie, et la corvée devient la sienne"]},
  {id:"ws46",th:"lettres",vu:"2026-11-04",src:"Jules Renard, Poil de Carotte, « C'est le chien » (1894) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Poil_de_Carotte/03",titre:"La ruse de Poil de Carotte",
   texte:"Mais Poil de Carotte, sans qu'on le lui ordonne, est allé voir ce qu'il y a. Un chemineau attardé passe dans la rue peut-être et rentre tranquillement chez lui, à moins qu'il n'escalade le mur du jardin pour voler. Poil de Carotte, par le long corridor noir, s'avance, les bras tendus vers la porte. Il trouve le verrou et le tire avec fracas, mais il n'ouvre pas la porte. Autrefois il s'exposait, sortait dehors, et sifflant, chantant, tapant du pied, il s'efforçait d'effrayer l'ennemi. Aujourd'hui il triche. Tandis que ses parents s'imaginent qu'il fouille hardiment les coins et tourne autour de la maison en gardien fidèle, il les trompe et reste collé derrière la porte. Un jour il se fera pincer, mais depuis longtemps sa ruse lui réussit.",
   quiz:[["Que fait réellement Poil de Carotte quand il va voir ?",["Il reste collé derrière la porte","Il fait le tour de la maison","Il sort chasser le voleur"],"« Il les trompe et reste collé derrière la porte »."],["Comment fait-il croire qu'il est sorti ?",["En tirant le verrou avec fracas","En claquant la porte du jardin","En sifflant dehors"],"« Il trouve le verrou et le tire avec fracas, mais il n'ouvre pas la porte »."],["Que veut dire « chemineau » ?",["Un vagabond qui va par les chemins","Un ramoneur","Un employé des chemins de fer"],"Le chemineau est un vagabond : on l'imagine passer dans la rue ou escalader le mur pour voler."]],
   idees:["Quand le chien aboie, Poil de Carotte va voir","Autrefois il sortait vraiment affronter l'ennemi","Aujourd'hui il triche et reste derrière la porte"]},
  {id:"ws47",th:"lettres eco",vu:"2026-11-04",src:"Émile Zola, Germinal, première partie, chapitre 1 (1885) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Germinal/Partie_I/Chapitre_1",titre:"Un homme seul sur la route",
   texte:"Dans la plaine rase, sous la nuit sans étoiles, d'une obscurité et d'une épaisseur d'encre, un homme suivait seul la grande route de Marchiennes à Montsou, dix kilomètres de pavé coupant tout droit, à travers les champs de betteraves. Devant lui, il ne voyait même pas le sol noir, et il n'avait la sensation de l'immense horizon plat que par les souffles du vent de mars, des rafales larges comme sur une mer, glacées d'avoir balayé des lieues de marais et de terres nues. Aucune ombre d'arbre ne tachait le ciel, le pavé se déroulait avec la rectitude d'une jetée, au milieu de l'embrun aveuglant des ténèbres. L'homme était parti de Marchiennes vers deux heures. Il marchait d'un pas allongé, grelottant sous le coton aminci de sa veste et de son pantalon de velours. Un petit paquet, noué dans un mouchoir à carreaux, le gênait beaucoup ; et il le serrait contre ses flancs, tantôt d'un coude, tantôt de l'autre, pour glisser au fond de ses poches les deux mains à la fois, des mains gourdes que les lanières du vent d'est faisaient saigner.",
   quiz:[["Quelle route l'homme suit-il ?",["De Marchiennes à Montsou","De Paris à Lille","De Lens à Arras"],"« La grande route de Marchiennes à Montsou »."],["Qu'est-ce qui gêne beaucoup l'homme en marchant ?",["Un petit paquet noué dans un mouchoir à carreaux","Ses sabots trop grands","Un lourd sac d'outils"],"« Un petit paquet, noué dans un mouchoir à carreaux, le gênait beaucoup »."],["Que suggèrent ses « mains gourdes » qui saignent ?",["Le froid terrible et la pauvreté de l'homme","Qu'il s'est battu","Qu'il a travaillé à la mine ce jour-là"],"Gourd : engourdi par le froid. Il grelotte sous une veste de coton aminci, sous le vent de mars."]],
   idees:["Un homme marche seul, de nuit, dans une plaine plate","Il a froid et ne porte qu'un petit paquet","Le vent glacé lui fait saigner les mains"]},
  {id:"ws48",th:"lettres",vu:"2026-11-04",src:"Comtesse de Ségur, Les Malheurs de Sophie, chapitre 2 (1858) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Les_Malheurs_de_Sophie/2",titre:"Un enterrement très gai",
   texte:"Quand la procession arriva au petit jardin de Sophie, on posa par terre le brancard avec la boîte qui contenait les restes de la malheureuse poupée. Les enfants se mirent à creuser la fosse ; ils y descendirent la boîte, jetèrent dessus des fleurs et des feuilles, puis la terre qu'ils avaient retirée ; ils ratissèrent promptement tout autour et y plantèrent deux lilas. Pour terminer la fête, ils coururent au bassin du potager et y remplirent leurs petits arrosoirs pour arroser les lilas ; ce fut l'occasion de nouveaux jeux et de nouveaux rires, parce qu'on s'arrosait les jambes, qu'on se poursuivait et se sauvait en riant et en criant. On n'avait jamais vu un enterrement plus gai. Il est vrai que la morte était une vieille poupée, sans couleur, sans cheveux, sans jambes et sans tête, et que personne ne l'aimait ni ne la regrettait.",
   quiz:[["Que plantent les enfants sur la tombe ?",["Deux lilas","Un rosier","Des tulipes"],"« Ils ratissèrent promptement tout autour et y plantèrent deux lilas »."],["Pourquoi l'enterrement est-il si gai ?",["Personne n'aimait ni ne regrettait cette vieille poupée","La poupée n'était pas vraiment cassée","Les parents avaient promis un goûter"],"La morte était une vieille poupée, et « personne ne l'aimait ni ne la regrettait »."],["Qu'est-ce qu'un « brancard », dans la procession ?",["Un support à porter à plusieurs","Une branche de lilas","Un petit cercueil"],"On pose « par terre le brancard avec la boîte » : le brancard sert à porter la boîte."]],
   idees:["Les enfants enterrent la poupée dans le jardin de Sophie","La cérémonie finit en jeux d'arrosoirs","Personne ne regrette la vieille poupée"]},
  {id:"ws49",th:"lettres histoire",vu:"2026-11-04",src:"Stendhal, La Chartreuse de Parme, chapitre 3 (1839) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/La_Chartreuse_de_Parme_(%C3%A9dition_Martineau,_1927)/Chapitre_III",titre:"Fabrice et la cantinière",
   texte:"Je vois le fin mot, s'écria-t-elle enfin d'un air de triomphe : vous êtes un jeune bourgeois amoureux de la femme de quelque capitaine du 4 de hussards. Votre amoureuse vous aura fait cadeau de l'uniforme que vous portez, et vous courez après elle. Vrai, comme Dieu est là-haut, vous n'avez jamais été soldat ; mais, comme un brave garçon que vous êtes, puisque votre régiment est au feu, vous voulez y paraître, et ne pas passer pour un capon. Fabrice convint de tout ; c'était le seul moyen qu'il eût de recevoir de bons conseils. J'ignore toutes les façons d'agir de ces Français, se disait-il, et, si je ne suis pas guidé par quelqu'un, je parviendrai encore à me faire jeter en prison, et l'on me volera mon cheval.",
   quiz:[["Que s'imagine la cantinière à propos de Fabrice ?",["Qu'il est un jeune bourgeois amoureux d'une femme de capitaine","Qu'il est un espion","Qu'il est déserteur"],"« Vous êtes un jeune bourgeois amoureux de la femme de quelque capitaine du 4 de hussards »."],["Pourquoi Fabrice convient-il de tout ?",["C'est le seul moyen de recevoir de bons conseils","Il a peur d'être arrêté","Il ne comprend pas la question"],"« C'était le seul moyen qu'il eût de recevoir de bons conseils »."],["Que veut dire « capon » ?",["Un lâche","Un espion","Un officier"],"Il veut paraître au feu « et ne pas passer pour un capon » : un poltron."]],
   idees:["La cantinière devine que Fabrice n'a jamais été soldat","Elle invente une histoire d'amour pour l'expliquer","Fabrice accepte pour être guidé"]},
  {id:"ws50",th:"lettres histoire eco",vu:"2026-11-04",src:"Stendhal, La Chartreuse de Parme, chapitre 3 (1839) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/La_Chartreuse_de_Parme_(%C3%A9dition_Martineau,_1927)/Chapitre_III",titre:"Le prix d'un cheval",
   texte:"Fabrice suivit ce conseil, et, présentant un napoléon à la vivandière, la pria de se payer. — C'est pitié de le voir ! s'écria cette femme ; le pauvre petit ne sait pas seulement dépenser son argent ! Tu mériterais bien qu'après avoir empoigné ton napoléon je fisse prendre son grand trot à Cocotte ; du diable si ta rosse pourrait me suivre. Que ferais-tu, nigaud, en me voyant détaler ? Apprends que, quand le brutal gronde, on ne montre jamais d'or. Tiens, lui dit-elle, voilà dix-huit francs cinquante centimes, et ton déjeuner te coûte trente sous. Maintenant, nous allons bientôt avoir des chevaux à revendre. Si la bête est petite, tu en donneras dix francs, et, dans tous les cas, jamais plus de vingt francs, quand ce serait le cheval des quatre fils Aymon.",
   quiz:[["Combien coûte le déjeuner de Fabrice ?",["Trente sous","Un napoléon","Dix francs"],"« Voilà dix-huit francs cinquante centimes, et ton déjeuner te coûte trente sous »."],["Quel conseil la vivandière donne-t-elle sur l'or ?",["Ne jamais en montrer quand le canon gronde","Le cacher dans sa botte","L'échanger contre des sous"],"« Quand le brutal gronde, on ne montre jamais d'or »."],["Que veut dire la vivandière par « le brutal gronde » ?",["Le canon tonne : on est en pleine bataille","Un homme se met en colère","L'orage arrive"],"Le brutal, en argot de soldat, c'est le canon : la bataille fait rage autour d'eux."]],
   idees:["Fabrice paie avec un napoléon, imprudemment","La vivandière lui rend honnêtement sa monnaie","Elle lui apprend le prix d'un cheval sur le champ de bataille"]},
  {id:"ws51",th:"lettres nature",vu:"2026-11-04",src:"Hector Malot, En famille, chapitre 1 (1893) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/En_famille_(Hector_Malot)/Texte_entier",titre:"Un drôle d'âne",
   texte:"Était-il possible que l'âne qui y était attelé l'eût amenée de si loin jusque-là ? Au premier coup d'œil on pouvait en douter, tant il était maigre, épuisé, vidé ; mais, à le regarder de plus près, on voyait que cet épuisement n'était que le résultat des fatigues longuement endurées dans la misère. En réalité, c'était un animal robuste, d'assez grande taille, plus haute que celle de notre âne d'Europe, élancé, au poil gris cendré avec le ventre clair malgré les poussières des routes qui le salissaient ; des lignes noires transversales marquaient ses jambes fines aux pieds rayés, et, si fatigué qu'il fût, il n'en tenait pas moins sa tête haute d'un air volontaire, résolu et coquin. Son harnais se montrait digne de la voiture, rafistolé avec des ficelles de diverses couleurs, les unes grosses, les autres petites au hasard des trouvailles, mais qui disparaissaient sous les branches fleuries et les roseaux, coupés le long du chemin, dont on l'avait couvert pour le défendre du soleil et des mouches.",
   quiz:[["Qu'a de particulier cet « âne » ?",["Des lignes noires transversales sur les jambes","Une seule oreille","Un pelage entièrement noir"],"« Des lignes noires transversales marquaient ses jambes fines aux pieds rayés »."],["Pourquoi l'a-t-on couvert de branches et de roseaux ?",["Pour le défendre du soleil et des mouches","Pour le décorer pour une fête","Pour le cacher"],"Branches et roseaux le couvrent « pour le défendre du soleil et des mouches »."],["Que veut dire « rafistolé », pour le harnais ?",["Réparé tant bien que mal","Neuf et brillant","Orné de fleurs"],"Le harnais tient avec des ficelles de toutes sortes, « au hasard des trouvailles » : il est réparé grossièrement."]],
   idees:["L'âne semble d'abord épuisé","Il est en réalité robuste, avec des rayures sur les jambes","Son harnais rafistolé est couvert de branches"]},
  {id:"ws52",th:"nature lettres",vu:"2026-11-04",src:"Prosper Mérimée, « Mateo Falcone » (1829) (texte de fr.wikisource.org)",lien:"https://fr.wikisource.org/wiki/Colomba_et_autres_contes_et_nouvelles/Mateo_Falcone",titre:"Le maquis corse",
   texte:"Il faut savoir que le laboureur corse, pour s'épargner la peine de fumer son champ, met le feu à une certaine étendue de bois : tant pis si la flamme se répand plus loin que besoin n'est, arrive que pourra ; on est sûr d'avoir une bonne récolte en semant sur cette terre fertilisée par les cendres des arbres qu'elle portait. Les épis enlevés, car on laisse la paille, qui donnerait de la peine à recueillir, les racines qui sont, restées en terre sans se consumer poussent au printemps suivant des cépées très épaisses, qui en peu d'années parviennent à une hauteur de sept ou huit pieds. C'est cette manière de taillis fourré que l'on nomme maquis. Différentes espèces d'arbres et d'arbrisseaux le composent, mêlés et confondus comme il plaît à Dieu. Ce n'est que la hache à la main que l'homme s'y ouvrirait un passage, et l'on voit des maquis si épais et si touffus, que les mouflons eux-mêmes ne peuvent y pénétrer.",
   quiz:[["Pourquoi le laboureur corse met-il le feu au bois ?",["Pour fertiliser la terre avec les cendres","Pour chasser les bandits","Pour faire du charbon"],"« On est sûr d'avoir une bonne récolte en semant sur cette terre fertilisée par les cendres »."],["Qui ne peut même pas pénétrer dans les maquis les plus épais ?",["Les mouflons","Les chèvres","Les sangliers"],"« Des maquis si épais et si touffus, que les mouflons eux-mêmes ne peuvent y pénétrer »."],["Que veut dire « fumer son champ » ?",["Y mettre de l'engrais","Y brûler du tabac","Le laisser au repos"],"Fumer un champ, c'est l'engraisser avec du fumier ; ici, les cendres remplacent ce travail."]],
   idees:["Le laboureur corse brûle le bois pour semer","Les racines repoussent en taillis très épais","Ce fourré, le maquis, est presque impénétrable"]}
];
